  defp mission_state_ground_network_entries(state) do
    normalize_mission_state_ground_network(
      Map.get(state, "ground_network"),
      "mission_state.ground_network"
    ) ++
      normalize_mission_state_ground_network(
        Map.get(state, "station_calendar"),
        "mission_state.station_calendar"
      ) ++
      normalize_mission_state_ground_network(
        Map.get(state, "station_calendar_provider"),
        "mission_state.station_calendar_provider"
      )
  end

  defp normalize_mission_state_ground_network(nil, _source), do: []

  defp normalize_mission_state_ground_network(
         station_calendar_providers,
         "mission_state.station_calendar_provider"
       )
       when is_list(station_calendar_providers) do
    station_calendar_providers
    |> Enum.flat_map(fn
      %{} = provider ->
        StationCalendar.to_ground_network(provider)

      _provider ->
        []
    end)
    |> Enum.map(&put_mission_state_source_path(&1, "mission_state.station_calendar_provider"))
  end

  defp normalize_mission_state_ground_network(ground_network, source)
       when is_list(ground_network) do
    Enum.map(ground_network, fn entry ->
      entry
      |> normalize_mission_state_ground_network_entry()
      |> put_mission_state_source_path(source)
    end)
  end

  defp normalize_mission_state_ground_network(%{} = station_calendar_provider, _source) do
    station_calendar_provider
    |> StationCalendar.to_ground_network()
    |> Enum.map(&put_mission_state_source_path(&1, "mission_state.station_calendar_provider"))
  end

  defp normalize_mission_state_ground_network(_ground_network, source) do
    raise ArgumentError, "#{source} must be a list or station calendar provider object"
  end

  defp normalize_mission_state_objective(objective) do
    objective = stringify_keys(objective)

    objective_type =
      objective["type"] || objective["objective_type"] || objective["objective"]

    case normalized_mission_state_objective_type(objective_type) do
      value when value in [nil, ""] ->
        objective

      value ->
        Map.put(objective, "type", value)
    end
  end

  defp normalized_mission_state_objective_type(value) do
    value
    |> objective_pressure_label()
    |> canonical_mission_state_objective_type()
  end

  defp canonical_mission_state_objective_type("target_commitment"), do: "target_observation"

  defp canonical_mission_state_objective_type(value)
       when value in [
              "delivery_latency",
              "delivery_latency_limit",
              "max_delivery_latency",
              "required_delivery_latency"
            ],
       do: "collection_latency"

  defp canonical_mission_state_objective_type("required_downlink_completion"),
    do: "downlink_completion"

  defp canonical_mission_state_objective_type(value), do: value

  defp normalize_mission_state_ground_network_entry(entry) do
    entry
    |> stringify_keys()
    |> normalize_station_availability_field("availability")
    |> normalize_station_availability_field("status")
    |> normalize_station_availability_field("station_contention_status")
  end

  defp put_mission_state_source_path(entry, source) do
    Map.put_new(entry, "mission_state_source_path", source)
  end

  defp normalize_station_availability_field(entry, field) do
    case Map.get(entry, field) do
      value when value in [nil, ""] or is_number(value) ->
        entry

      value ->
        Map.put(entry, field, normalized_station_availability_token(value))
    end
  end

  defp branch_generation_policy(request) do
    policy = stringify_keys(get_key(request, :branch_generation_policy) || %{})
    urgent_priority_threshold = numeric_policy_value(policy, "urgent_priority_threshold", 8.0)

    derive? =
      truthy?(get_key(request, :derive_branches?)) or
        truthy?(get_key(request, :derive_branches)) or
        truthy?(Map.get(policy, "derive_branches"))

    %{
      "derive_branches" => derive?,
      "fuel_margin_threshold" => numeric_policy_value(policy, "fuel_margin_threshold", 0.25),
      "power_margin_threshold" => numeric_policy_value(policy, "power_margin_threshold", 0.2),
      "downlink_margin_threshold" =>
        numeric_policy_value(policy, "downlink_margin_threshold", 0.75),
      "storage_margin_threshold" => numeric_policy_value(policy, "storage_margin_threshold", 0.2),
      "thermal_margin_c_threshold" =>
        numeric_policy_value(
          policy,
          "thermal_margin_c_threshold",
          numeric_policy_value(policy, "thermal_margin_threshold", nil)
        ),
      "urgent_priority_threshold" => urgent_priority_threshold,
      "target_priority_feedback_threshold" =>
        numeric_policy_value(
          policy,
          "target_priority_feedback_threshold",
          urgent_priority_threshold
        ),
      "station_throughput_feedback_threshold" =>
        numeric_policy_value(policy, "station_throughput_feedback_threshold", 0.8),
      "contact_success_feedback_threshold" =>
        numeric_policy_value(policy, "contact_success_feedback_threshold", 0.8),
      "observation_success_feedback_threshold" =>
        numeric_policy_value(policy, "observation_success_feedback_threshold", 0.8),
      "maneuver_success_feedback_threshold" =>
        numeric_policy_value(policy, "maneuver_success_feedback_threshold", 0.8),
      "maneuver_execution_timing_3sigma_threshold_s" =>
        numeric_policy_value(policy, "maneuver_execution_timing_3sigma_threshold_s", 60.0),
      "maneuver_execution_delta_v_3sigma_threshold_km_s" =>
        numeric_policy_value(
          policy,
          "maneuver_execution_delta_v_3sigma_threshold_km_s",
          0.001
        ),
      "command_success_feedback_threshold" =>
        numeric_policy_value(policy, "command_success_feedback_threshold", 0.8),
      "downlink_demand_feedback_threshold_mb" =>
        numeric_policy_value(policy, "downlink_demand_feedback_threshold_mb", 0.0),
      "allow_urgent_placeholder" =>
        boolean_policy_value(policy, "allow_urgent_placeholder", true),
      "combine_derived_branches" => truthy?(Map.get(policy, "combine_derived_branches"))
    }
  end

  defp maybe_add_derived_branches(
         branches,
         _prior_plan,
         _mission_state,
         _operational_feedback,
         _operational_feedback_provenance,
         %{
           "derive_branches" => false
         }
       ),
       do: branches

  defp maybe_add_derived_branches(
         branches,
         prior_plan,
         mission_state,
         operational_feedback,
         operational_feedback_provenance,
         policy
       ) do
    individual_derived =
      []
      |> Kernel.++(derived_degraded_spacecraft_branches(mission_state))
      |> Kernel.++(derived_ground_network_branches(mission_state, prior_plan))
      |> Kernel.++(derived_station_calendar_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_station_calendar_pressure_branches(mission_state))
      |> Kernel.++(
        derived_mission_state_station_reservation_review_summary_pressure_branches(mission_state)
      )
      |> Kernel.++(
        derived_mission_state_station_reservation_hold_pressure_branches(mission_state)
      )
      |> Kernel.++(
        derived_operational_feedback_branches(
          mission_state,
          prior_plan,
          operational_feedback,
          operational_feedback_provenance,
          policy
        )
      )
      |> Kernel.++(derived_power_constrained_branches(mission_state, policy))
      |> Kernel.++(derived_thermal_constrained_branches(mission_state, policy))
      |> Kernel.++(derived_payload_constrained_branches(mission_state))
      |> Kernel.++(derived_antenna_constrained_branches(mission_state))
      |> Kernel.++(derived_resource_projection_pressure_branches(prior_plan, policy))
      |> Kernel.++(
        derived_mission_state_resource_projection_pressure_branches(mission_state, policy)
      )
      |> Kernel.++(derived_resource_filter_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_resource_filter_pressure_branches(mission_state))
      |> Kernel.++(derived_contact_filter_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_contact_filter_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_contact_contention_pressure_branches(mission_state))
      |> Kernel.++(derived_contact_contention_resolution_pressure_branches(prior_plan))
      |> Kernel.++(
        derived_mission_state_contact_contention_resolution_pressure_branches(mission_state)
      )
      |> Kernel.++(derived_contact_allocation_pressure_branches(prior_plan))
      |> Kernel.++(derived_contact_allocation_summary_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_contact_allocation_pressure_branches(mission_state))
      |> Kernel.++(
        derived_mission_state_contact_allocation_summary_pressure_branches(mission_state)
      )
      |> Kernel.++(derived_mission_state_candidate_diff_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_candidate_rejection_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_provider_counteroffer_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_schema_validation_pressure_branches(mission_state))
      |> Kernel.++(derived_operational_readiness_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_operational_readiness_pressure_branches(mission_state))
      |> Kernel.++(derived_quality_gate_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_quality_gate_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_model_acceptance_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_validation_safety_case_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_refresh_budget_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_refresh_freshness_pressure_branches(mission_state))
      |> Kernel.++(derived_link_capacity_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_link_capacity_pressure_branches(mission_state))
      |> Kernel.++(derived_score_term_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_score_term_pressure_branches(mission_state))
      |> Kernel.++(derived_objective_satisfaction_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_objective_satisfaction_pressure_branches(mission_state))
      |> Kernel.++(derived_objective_tradeoff_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_objective_tradeoff_pressure_branches(mission_state))
      |> Kernel.++(derived_constraint_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_constraint_pressure_branches(mission_state))
      |> Kernel.++(derived_timeline_integrity_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_timeline_integrity_pressure_branches(mission_state))
      |> Kernel.++(derived_timeline_dependency_impact_pressure_branches(prior_plan))
      |> Kernel.++(
        derived_mission_state_timeline_dependency_impact_pressure_branches(mission_state)
      )
      |> Kernel.++(derived_timeline_publication_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_timeline_publication_pressure_branches(mission_state))
      |> Kernel.++(derived_timeline_lifecycle_state_pressure_branches(prior_plan))
      |> Kernel.++(
        derived_mission_state_timeline_lifecycle_state_pressure_branches(mission_state)
      )
      |> Kernel.++(derived_timeline_activity_lifecycle_state_pressure_branches(prior_plan))
      |> Kernel.++(
        derived_mission_state_timeline_activity_lifecycle_state_pressure_branches(mission_state)
      )
      |> Kernel.++(derived_timeline_activity_precondition_pressure_branches(prior_plan))
      |> Kernel.++(
        derived_mission_state_timeline_activity_precondition_pressure_branches(mission_state)
      )
      |> Kernel.++(derived_timeline_preservation_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_timeline_preservation_pressure_branches(mission_state))
      |> Kernel.++(derived_timeline_diff_pressure_branches(prior_plan, policy))
      |> Kernel.++(derived_mission_state_timeline_diff_pressure_branches(mission_state, policy))
      |> Kernel.++(derived_planned_activity_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_planned_activity_pressure_branches(mission_state))
      |> Kernel.++(derived_proposed_contact_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_proposed_contact_pressure_branches(mission_state))
      |> Kernel.++(derived_contact_intent_pressure_branches(prior_plan))
      |> Kernel.++(derived_contact_intent_summary_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_contact_intent_pressure_branches(mission_state))
      |> Kernel.++(derived_mission_state_contact_intent_summary_pressure_branches(mission_state))
      |> Kernel.++(derived_realized_activity_pressure_branches(prior_plan))
      |> Kernel.++(
        derived_mission_state_realized_activity_pressure_branches(mission_state, prior_plan)
      )
      |> Kernel.++(derived_operational_timeline_pressure_branches(prior_plan))
      |> Kernel.++(derived_mission_state_operational_timeline_pressure_branches(mission_state))
      |> Kernel.++(derived_operator_review_pressure_branches(prior_plan, policy))
      |> Kernel.++(derived_mission_state_operator_review_pressure_branches(mission_state, policy))
      |> Kernel.++(derived_cadence_import_pressure_branches(prior_plan, policy))
      |> Kernel.++(derived_mission_state_cadence_import_pressure_branches(mission_state, policy))
      |> Kernel.++(derived_fuel_preservation_branches(mission_state, policy))
      |> Kernel.++(derived_urgent_target_branches(mission_state, prior_plan, policy))
      |> Kernel.++(derived_collection_latency_branches(mission_state, prior_plan))
      |> Kernel.++(derived_downlink_constrained_branches(mission_state, prior_plan, policy))
      |> dedupe_contact_intent_pressure_branches()

    derived =
      [baseline_branch()]
      |> Kernel.++(individual_derived)
      |> Kernel.++(derived_combined_branch(individual_derived, policy))
      |> Enum.map(&normalize_strategy_branch/1)

    explicit_ids = MapSet.new(Enum.map(branches, & &1["id"]))

    appended =
      derived
      |> Enum.reject(&MapSet.member?(explicit_ids, &1["id"]))
      |> disambiguate_resource_projection_pressure_branch_ids()
      |> disambiguate_resource_filter_pressure_branch_ids()
      |> disambiguate_contact_filter_pressure_branch_ids()
      |> disambiguate_contact_contention_pressure_branch_ids()
      |> disambiguate_contact_allocation_pressure_branch_ids()
      |> disambiguate_score_term_pressure_branch_ids()
      |> disambiguate_objective_satisfaction_pressure_branch_ids()
      |> disambiguate_objective_tradeoff_pressure_branch_ids()
      |> disambiguate_constraint_pressure_branch_ids()
      |> disambiguate_timeline_integrity_pressure_branch_ids()
      |> disambiguate_timeline_dependency_impact_pressure_branch_ids()
      |> disambiguate_timeline_publication_pressure_branch_ids()
      |> disambiguate_timeline_lifecycle_state_pressure_branch_ids()
      |> disambiguate_timeline_activity_lifecycle_state_pressure_branch_ids()
      |> disambiguate_timeline_activity_precondition_pressure_branch_ids()
      |> disambiguate_timeline_preservation_pressure_branch_ids()
      |> disambiguate_timeline_diff_pressure_branch_ids()
      |> disambiguate_review_replay_pressure_branch_ids()
      |> disambiguate_degraded_spacecraft_branch_ids()
      |> disambiguate_ground_network_branch_ids()
      |> disambiguate_mission_state_resource_branch_ids()

    (branches ++ appended)
    |> dedupe_branches()
    |> Enum.sort_by(& &1["id"])
  end

  defp dedupe_branches(branches) do
    branches
    |> Enum.reduce({MapSet.new(), []}, fn branch, {seen, kept} ->
      if MapSet.member?(seen, branch["id"]) do
        {seen, kept}
      else
        {MapSet.put(seen, branch["id"]), [branch | kept]}
      end
    end)
    |> elem(1)
    |> Enum.reverse()
  end

  defp dedupe_contact_intent_pressure_branches(branches) do
    branches
    |> Enum.reduce({MapSet.new(), []}, fn branch, {seen, kept} ->
      identity = contact_intent_pressure_branch_identity(branch)

      cond do
        is_nil(identity) ->
          {seen, [branch | kept]}

        MapSet.member?(seen, identity) ->
          {seen, kept}

        true ->
          {MapSet.put(seen, identity), [branch | kept]}
      end
    end)
    |> elem(1)
    |> Enum.reverse()
  end

  defp contact_intent_pressure_branch_identity(%{"events" => [event | _events]}) do
    if event["feedback_scope"] == "contact_intent" do
      contact_id =
        event["source_activity_id"] ||
          event["contact_id"] ||
          event["source_activity_ids"] |> List.wrap() |> List.first()

      gate_status = event["contact_intent_gate_status"]

      if contact_id in [nil, ""] or gate_status in [nil, ""] do
        nil
      else
        {gate_status, contact_id}
      end
    end
  end

  defp contact_intent_pressure_branch_identity(_branch), do: nil

  defp baseline_branch do
    %{
      "id" => "baseline",
      "label" => "Mission-state baseline",
      "metadata" => %{"derived_source" => "branch_generation.baseline"}
    }
  end

