      numeric_or_nil: &numeric_or_nil/1,
      stringify_keys: &stringify_keys/1
    ]
  end

  defp normalized_station_availability_token(value) when is_number(value) do
    if value < 1.0, do: "reduced_capacity", else: "available"
  end

  defp normalized_station_availability_token(value) do
    case encode_value(value) do
      value when is_binary(value) ->
        value
        |> String.trim()
        |> String.downcase()
        |> String.replace(~r/[\s-]+/, "_")
        |> canonical_station_availability_token()

      value ->
        value
    end
  end

  defp canonical_station_availability_token(value) when value in ["outage", "offline", "down"],
    do: "unavailable"

  defp canonical_station_availability_token(value), do: value

  defp derived_operational_feedback_branches(
         mission_state,
         prior_plan,
         operational_feedback,
         operational_feedback_provenance,
         policy
       ) do
    horizon_end_s = get_in(prior_plan, ["planning_horizon", "duration_s"]) || 0.0
    station_ids = planning_ground_station_ids(mission_state, prior_plan)
    target_ids = planning_target_ids(mission_state, prior_plan)
    target_priorities = planning_target_priorities(mission_state, prior_plan)
    maneuver_activities = planning_maneuver_activities(prior_plan)
    command_activities = planning_command_activities(prior_plan)
    trust_boundary = operational_feedback_trust_boundary_context(operational_feedback_provenance)

    throughput_events =
      operational_feedback
      |> Map.get("station_throughput_factor", %{})
      |> low_station_throughput_feedback_events(
        station_ids,
        policy["station_throughput_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    contact_success_events =
      operational_feedback
      |> Map.get("contact_success_rate", %{})
      |> low_contact_success_feedback_events(
        station_ids,
        policy["contact_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    observation_success_events =
      operational_feedback
      |> Map.get("observation_success_rate", %{})
      |> low_observation_success_feedback_events(
        target_ids,
        target_priorities,
        policy["observation_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    observation_quality_events =
      operational_feedback
      |> Map.get("image_quality_score", %{})
      |> low_observation_quality_feedback_events(
        Map.get(operational_feedback, "image_quality_status", %{}),
        Map.get(operational_feedback, "image_quality_source", %{}),
        Map.get(operational_feedback, "cloud_cover_fraction", %{}),
        Map.get(operational_feedback, "blur_score", %{}),
        target_ids,
        target_priorities,
        policy["observation_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    maneuver_success_events =
      operational_feedback
      |> Map.get("maneuver_success_rate", %{})
      |> low_maneuver_success_feedback_events(
        maneuver_activities,
        policy["maneuver_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    maneuver_execution_uncertainty_events =
      operational_feedback
      |> Map.get("maneuver_execution_uncertainty", %{})
      |> maneuver_execution_uncertainty_feedback_events(
        maneuver_activities,
        policy,
        horizon_end_s,
        trust_boundary
      )

    command_success_events =
      operational_feedback
      |> Map.get("command_success_rate", %{})
      |> low_command_success_feedback_events(
        command_activities,
        policy["command_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    downlink_demand_events =
      operational_feedback
      |> Map.get("downlink_demand_mb", %{})
      |> downlink_demand_feedback_events(
        Map.get(operational_feedback, "downlink_demand_sources", %{}),
        station_ids,
        policy["downlink_demand_feedback_threshold_mb"],
        horizon_end_s,
        trust_boundary
      )

    target_priority_events =
      operational_feedback
      |> Map.get("target_priority_overrides", %{})
      |> high_target_priority_feedback_events(
        target_ids,
        policy["target_priority_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    resource_margin_events =
      operational_feedback
      |> Map.get("resource_margin_overrides", %{})
      |> low_resource_margin_feedback_events(policy, horizon_end_s, trust_boundary)

    resource_availability_events =
      operational_feedback
      |> Map.get("resource_availability_overrides", %{})
      |> resource_availability_feedback_events(horizon_end_s, trust_boundary)

    [
      feedback_branch(
        "derived_station_throughput_feedback",
        "Derived station throughput feedback",
        throughput_events,
        "operational_feedback.station_throughput_factor"
      ),
      feedback_branch(
        "derived_contact_success_feedback",
        "Derived contact success feedback",
        contact_success_events,
        "operational_feedback.contact_success_rate"
      ),
      feedback_branch(
        "derived_observation_success_feedback",
        "Derived observation success feedback",
        observation_success_events,
        "operational_feedback.observation_success_rate"
      ),
      feedback_branch(
        "derived_observation_quality_feedback",
        "Derived observation quality feedback",
        observation_quality_events,
        "operational_feedback.image_quality_score"
      ),
      feedback_branch(
        "derived_maneuver_success_feedback",
        "Derived maneuver success feedback",
        maneuver_success_events,
        "operational_feedback.maneuver_success_rate"
      ),
      feedback_branch(
        "derived_maneuver_execution_uncertainty_feedback",
        "Derived maneuver execution uncertainty feedback",
        maneuver_execution_uncertainty_events,
        "operational_feedback.maneuver_execution_uncertainty"
      ),
      feedback_branch(
        "derived_command_success_feedback",
        "Derived command success feedback",
        command_success_events,
        "operational_feedback.command_success_rate"
      ),
      feedback_branch(
        "derived_downlink_demand_feedback",
        "Derived downlink demand feedback",
        downlink_demand_events,
        "operational_feedback.downlink_demand_mb"
      ),
      feedback_branch(
        "derived_target_priority_feedback",
        "Derived target priority feedback",
        target_priority_events,
        "operational_feedback.target_priority_overrides"
      ),
      feedback_branch(
        "derived_resource_margin_feedback",
        "Derived resource margin feedback",
        resource_margin_events,
        "operational_feedback.resource_margin_overrides"
      ),
      feedback_branch(
        "derived_resource_availability_feedback",
        "Derived resource availability feedback",
        resource_availability_events,
        "operational_feedback.resource_availability_overrides"
      )
    ]
    |> Enum.reject(&is_nil/1)
  end

  defp feedback_branch(_id, _label, [], _derived_source), do: nil

  defp feedback_branch(id, label, events, derived_source) do
    %{
      "id" => id,
      "label" => label,
      "events" => events,
      "metadata" => %{"derived_source" => derived_source}
    }
  end

  defp low_station_throughput_feedback_events(
         factors,
         station_ids,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(factors) do
    low_station_feedback_events(
      factors,
      station_ids,
      threshold,
      horizon_end_s,
      trust_boundary,
      &station_throughput_feedback_event/5
    )
    |> Enum.sort_by(&{Map.get(&1, "ground_station_id", ""), &1["station_throughput_factor"]})
  end

  defp low_station_throughput_feedback_events(
         _factors,
         _station_ids,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_contact_success_feedback_events(
         factors,
         station_ids,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(factors) do
    low_station_feedback_events(
      factors,
      station_ids,
      threshold,
      horizon_end_s,
      trust_boundary,
      &contact_success_feedback_event/5
    )
    |> Enum.sort_by(&{Map.get(&1, "ground_station_id", ""), &1["contact_success_factor"]})
  end

  defp low_contact_success_feedback_events(
         _factors,
         _station_ids,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_observation_success_feedback_events(
         factors,
         target_ids,
         target_priorities,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(factors) do
    factors
    |> Enum.flat_map(fn
      {"default", factor} ->
        if low_feedback_factor?(factor, threshold) do
          Enum.map(target_ids, fn target_id ->
            observation_success_feedback_event(
              target_id,
              factor,
              "default",
              horizon_end_s,
              Map.get(target_priorities, target_id),
              trust_boundary
            )
          end)
        else
          []
        end

      {target_id, factor} ->
        if target_id in target_ids and low_feedback_factor?(factor, threshold) do
          [
            observation_success_feedback_event(
              target_id,
              factor,
              "target",
              horizon_end_s,
              Map.get(target_priorities, target_id),
              trust_boundary
            )
          ]
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["target_id"], &1["observation_success_factor"]})
  end

  defp low_observation_success_feedback_events(
         _factors,
         _target_ids,
         _target_priorities,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_observation_quality_feedback_events(
         scores,
         statuses,
         sources,
         cloud_cover_fractions,
         blur_scores,
         target_ids,
         target_priorities,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(scores) do
    statuses = if is_map(statuses), do: statuses, else: %{}
    sources = if is_map(sources), do: sources, else: %{}
    cloud_cover_fractions = if is_map(cloud_cover_fractions), do: cloud_cover_fractions, else: %{}
    blur_scores = if is_map(blur_scores), do: blur_scores, else: %{}

    [scores, statuses, cloud_cover_fractions, blur_scores]
    |> feedback_event_keys()
    |> Enum.flat_map(fn
      "default" ->
        target_ids
        |> Enum.map(fn target_id ->
          observation_quality_feedback_event(
            target_id,
            "default",
            horizon_end_s,
            Map.get(target_priorities, target_id),
            trust_boundary,
            scores,
            statuses,
            sources,
            cloud_cover_fractions,
            blur_scores
          )
        end)
        |> Enum.filter(&low_feedback_factor?(&1["observation_success_factor"], threshold))

      target_id ->
        if target_id in target_ids do
          [
            observation_quality_feedback_event(
              target_id,
              "target",
              horizon_end_s,
              Map.get(target_priorities, target_id),
              trust_boundary,
              scores,
              statuses,
              sources,
              cloud_cover_fractions,
              blur_scores
            )
          ]
          |> Enum.filter(&low_feedback_factor?(&1["observation_success_factor"], threshold))
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["target_id"], &1["image_quality_score"]})
  end

  defp low_observation_quality_feedback_events(
         _scores,
         _statuses,
         _sources,
         _cloud_cover_fractions,
         _blur_scores,
         _target_ids,
         _target_priorities,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp feedback_event_keys(maps) do
    maps
    |> Enum.flat_map(fn
      %{} = map -> Map.keys(map)
      _map -> []
    end)
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp low_maneuver_success_feedback_events(
         factors,
         maneuver_activities,
         threshold,
         horizon_end_s,
