    |> Enum.flat_map(fn
      {"default", factor} ->
        if low_feedback_factor?(factor, threshold) do
          Enum.map(maneuver_activities, fn activity ->
            maneuver_success_feedback_event(
              activity,
              factor,
              "default",
              "default",
              horizon_end_s,
              trust_boundary
            )
          end)
        else
          []
        end

      {feedback_key, factor} ->
        if low_feedback_factor?(factor, threshold) do
          maneuver_activities
          |> Enum.filter(&(feedback_key in maneuver_feedback_keys(&1)))
          |> Enum.map(fn activity ->
            maneuver_success_feedback_event(
              activity,
              factor,
              maneuver_feedback_scope(activity, feedback_key),
              feedback_key,
              horizon_end_s,
              trust_boundary
            )
          end)
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["activity_id"], &1["feedback_key"], &1["maneuver_success_factor"]})
