  defp downlink_demand_feedback_events(
         demands,
         demand_sources,
         station_ids,
         threshold_mb,
         horizon_end_s,
         trust_boundary
       )
       when is_map(demands) do
    demands
    |> Enum.flat_map(fn
      {"default", required_downlink_mb} ->
        if downlink_demand_relevant?(required_downlink_mb, threshold_mb) do
          [
            downlink_demand_feedback_event(
              nil,
              required_downlink_mb,
              "default",
              demand_sources_for(demand_sources, "default"),
              horizon_end_s,
              trust_boundary
            )
          ]
        else
          []
        end

      {station_id, required_downlink_mb} ->
        if station_id in station_ids and
             downlink_demand_relevant?(required_downlink_mb, threshold_mb) do
          [
            downlink_demand_feedback_event(
              station_id,
              required_downlink_mb,
              "station",
              demand_sources_for(demand_sources, station_id),
              horizon_end_s,
              trust_boundary
            )
          ]
        else
          []
        end
    end)
    |> Enum.sort_by(&{Map.get(&1, "ground_station_id", ""), &1["required_downlink_mb"]})
  end

  defp downlink_demand_feedback_events(
         _demands,
         _demand_sources,
         _station_ids,
         _threshold_mb,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp demand_sources_for(%{} = demand_sources, key) do
    encoded_key = encode_value(key)

    Map.get(demand_sources, encoded_key, Map.get(demand_sources, key, []))
  end

  defp demand_sources_for(_demand_sources, _key), do: []

  defp downlink_demand_source_list(sources) do
    sources
    |> List.wrap()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      source_list -> source_list
    end
  end

  defp high_target_priority_feedback_events(
         priorities,
         target_ids,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(priorities) do
    priorities
    |> Enum.flat_map(fn
      {"default", priority} ->
        if high_feedback_priority?(priority, threshold) do
          Enum.map(
            target_ids,
            &target_priority_feedback_event(
              &1,
              priority,
              "default",
              horizon_end_s,
              trust_boundary
            )
          )
        else
          []
        end

      {target_id, priority} ->
        if target_id in target_ids and high_feedback_priority?(priority, threshold) do
          [
            target_priority_feedback_event(
              target_id,
              priority,
              "target",
              horizon_end_s,
              trust_boundary
            )
          ]
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["target_id"], -&1["priority"]})
  end

  defp high_target_priority_feedback_events(
         _priorities,
         _target_ids,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_resource_margin_feedback_events(overrides, policy, horizon_end_s, trust_boundary)
       when is_map(overrides) do
    overrides
    |> Enum.flat_map(fn {spacecraft_id, margins} ->
      margins
      |> stringify_keys()
      |> low_spacecraft_resource_margin_feedback_events(
        to_string(spacecraft_id),
        policy,
        horizon_end_s,
        trust_boundary
      )
    end)
    |> Enum.sort_by(&{&1["spacecraft_id"], &1["resource_field"]})
  end

  defp low_resource_margin_feedback_events(_overrides, _policy, _horizon_end_s, _trust_boundary),
    do: []

  defp resource_availability_feedback_events(overrides, horizon_end_s, trust_boundary)
       when is_map(overrides) do
    overrides
    |> Enum.flat_map(fn {spacecraft_id, availability} ->
      availability
      |> stringify_keys()
      |> spacecraft_resource_availability_feedback_events(
        to_string(spacecraft_id),
        horizon_end_s,
        trust_boundary
      )
    end)
    |> Enum.sort_by(&{&1["spacecraft_id"], &1["resource_field"]})
  end

  defp resource_availability_feedback_events(_overrides, _horizon_end_s, _trust_boundary),
    do: []

  defp spacecraft_resource_availability_feedback_events(
         availability,
         spacecraft_id,
         horizon_end_s,
         trust_boundary
       )
       when is_map(availability) and spacecraft_id not in ["", "nil"] do
    degraded_events =
      if spacecraft_degraded_availability_feedback?(availability) do
        [
          degraded_spacecraft_feedback_event(
            spacecraft_id,
            availability,
            horizon_end_s,
            trust_boundary
          )
        ]
      else
        []
      end

    resource_events =
      ["payload_available", "antenna_available"]
      |> Enum.flat_map(fn field ->
        case Map.get(availability, field) do
          false ->
            [
              resource_availability_feedback_event(
                spacecraft_id,
                field,
                availability_feedback_reason(field),
                horizon_end_s,
                trust_boundary
              )
            ]

          _value ->
            []
        end
      end)

    degraded_events ++ resource_events
  end

  defp spacecraft_resource_availability_feedback_events(
         _availability,
         _spacecraft_id,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_spacecraft_resource_margin_feedback_events(
         margins,
         spacecraft_id,
         policy,
         horizon_end_s,
         trust_boundary
       )
       when is_map(margins) and spacecraft_id not in ["", "nil"] do
    ["fuel_margin", "power_margin", "storage_margin", "downlink_margin", "thermal_margin_c"]
    |> Enum.flat_map(fn field ->
      value = Map.get(margins, field)
      threshold = resource_margin_feedback_threshold(policy, field)

      if is_number(value) and is_number(threshold) and value <= threshold do
        [
          resource_margin_feedback_event(
            spacecraft_id,
            field,
            value,
            threshold,
            horizon_end_s,
            trust_boundary
          )
        ]
      else
        []
      end
    end)
  end

  defp low_spacecraft_resource_margin_feedback_events(
         _margins,
         _spacecraft_id,
         _policy,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp resource_margin_feedback_threshold(policy, "thermal_margin_c"),
    do: Map.get(policy, "thermal_margin_c_threshold")

  defp resource_margin_feedback_threshold(policy, field),
    do: Map.get(policy, "#{field}_threshold")

  defp low_station_feedback_events(
         factors,
         station_ids,
         threshold,
         horizon_end_s,
         trust_boundary,
         event_fun
       ) do
    Enum.flat_map(factors, fn
      {"default", factor} ->
        if low_feedback_factor?(factor, threshold) do
          [event_fun.(nil, factor, "default", horizon_end_s, trust_boundary)]
        else
          []
        end

      {station_id, factor} ->
        if station_id in station_ids and low_feedback_factor?(factor, threshold) do
          [event_fun.(station_id, factor, "station", horizon_end_s, trust_boundary)]
        else
          []
        end
    end)
  end

  defp low_feedback_factor?(factor, threshold) when is_number(factor) and is_number(threshold),
    do: factor < threshold

  defp low_feedback_factor?(_factor, _threshold), do: false

  defp high_feedback_priority?(priority, threshold)
       when is_number(priority) and is_number(threshold),
       do: priority >= threshold

  defp high_feedback_priority?(_priority, _threshold), do: false

  defp downlink_demand_relevant?(required_downlink_mb, threshold_mb)
       when is_number(required_downlink_mb) and is_number(threshold_mb),
       do: required_downlink_mb > threshold_mb

  defp downlink_demand_relevant?(required_downlink_mb, _threshold_mb)
       when is_number(required_downlink_mb),
       do: required_downlink_mb > 0.0

  defp downlink_demand_relevant?(_required_downlink_mb, _threshold_mb), do: false

  defp station_throughput_feedback_event(
         station_id,
         factor,
         source_scope,
         horizon_end_s,
         trust_boundary
       ) do
    %{
      "type" => "station_throughput_feedback",
      "station_throughput_factor" => factor |> max(0.0) |> min(1.0),
      "feedback_source" => "operational_feedback.station_throughput_factor",
      "feedback_scope" => source_scope,
      "starts_at_s" => 0.0,
      "ends_at_s" => horizon_end_s,
      "ground_station_id" => station_id,
      "trust_boundary" =>
        feedback_event_trust_boundary(
          trust_boundary,
          "station_throughput_factor",
          station_id || "default"
        )
    }
    |> compact_map()
  end

  defp numeric_policy_value(policy, key, default) do
    case numeric_or_nil(Map.get(policy, key)) do
      value when is_number(value) -> value
      _value -> default
    end
  end

  defp policy_count_value(policy, key, default) do
    case numeric_policy_value(policy, key, default) do
      value when is_number(value) -> max(trunc(value), 0)
      _value -> default
    end
  end

  defp boolean_policy_value(policy, key, default) do
    case json_boolean_value(Map.get(policy, key, default)) do
      value when is_boolean(value) -> value
      _value -> default
    end
  end

  defp json_boolean_value(value) when is_boolean(value), do: value

  defp json_boolean_value(value) when is_number(value) do
    cond do
      value == 1 -> true
      value == 0 -> false
      true -> nil
    end
  end

  defp json_boolean_value(value) when is_binary(value) do
    case String.downcase(String.trim(value)) do
      "true" -> true
      "1" -> true
      "false" -> false
      "0" -> false
      _value -> nil
    end
  end

  defp json_boolean_value(_value), do: nil

  defp contact_success_feedback_event(
         station_id,
         factor,
         source_scope,
         horizon_end_s,
         trust_boundary
       ) do
    %{
      "type" => "contact_success_feedback",
      "contact_success_factor" => factor |> max(0.0) |> min(1.0),
      "feedback_source" => "operational_feedback.contact_success_rate",
      "feedback_scope" => source_scope,
      "starts_at_s" => 0.0,
      "ends_at_s" => horizon_end_s,
      "ground_station_id" => station_id,
      "trust_boundary" =>
        feedback_event_trust_boundary(
          trust_boundary,
          "contact_success_rate",
          station_id || "default"
        )
    }
    |> compact_map()
  end

  defp observation_success_feedback_event(
         target_id,
         factor,
         source_scope,
         horizon_end_s,
         priority,
         trust_boundary
       ) do
    %{
      "type" => "observation_success_feedback",
      "target_id" => target_id,
      "observation_success_factor" => factor |> max(0.0) |> min(1.0),
      "feedback_source" => "operational_feedback.observation_success_rate",
      "feedback_scope" => source_scope,
      "priority" => priority,
      "required_observations" => 1,
      "allow_placeholder" => false,
      "starts_at_s" => 0.0,
      "ends_at_s" => horizon_end_s,
      "trust_boundary" =>
        feedback_event_trust_boundary(
          trust_boundary,
          "observation_success_rate",
          target_id || "default"
        )
    }
    |> compact_map()
  end

  defp observation_quality_feedback_event(
         target_id,
         source_scope,
         horizon_end_s,
         priority,
         trust_boundary,
         scores,
         statuses,
         sources,
         cloud_cover_fractions,
         blur_scores
       ) do
    score = feedback_event_number_value(scores, target_id)
    status = feedback_event_string_value(statuses, target_id)
    cloud_cover_fraction = feedback_event_number_value(cloud_cover_fractions, target_id)
    blur_score = feedback_event_number_value(blur_scores, target_id)

    {factor, feedback_source} =
      observation_quality_feedback_factor(score, status, cloud_cover_fraction, blur_score)

    trust_boundary =
      feedback_event_trust_boundary(
        trust_boundary,
        operational_feedback_field_from_source(feedback_source),
        target_id || "default"
      )

    target_id
    |> observation_success_feedback_event(
      factor,
      source_scope,
      horizon_end_s,
      priority,
      trust_boundary
    )
    |> Map.put("feedback_source", feedback_source)
    |> put_optional_number("image_quality_score", score)
    |> put_optional_string(
      "image_quality_status",
      status
    )
    |> put_optional_string(
      "image_quality_source",
      feedback_event_string_value(sources, target_id)
    )
    |> put_optional_number("cloud_cover_fraction", cloud_cover_fraction)
    |> put_optional_number("blur_score", blur_score)
  end

  defp observation_quality_feedback_factor(
         score,
         status,
         cloud_cover_fraction,
         blur_score
       ) do
    [
      {"operational_feedback.image_quality_score", score},
      {"operational_feedback.image_quality_status", image_quality_status_feedback_factor(status)},
      {"operational_feedback.cloud_cover_fraction", inverse_quality_factor(cloud_cover_fraction)},
      {"operational_feedback.blur_score", inverse_quality_factor(blur_score)}
    ]
    |> Enum.filter(fn {_source, value} -> is_number(value) end)
    |> Enum.min_by(fn {_source, value} -> value end, fn ->
      {"operational_feedback.image_quality_score", 1.0}
    end)
    |> then(fn {source, factor} -> {clamp_unit_interval(factor), source} end)
  end

  defp image_quality_status_feedback_factor(status) when is_binary(status) do
    case normalized_status_token(status) do
      status
      when status in [
             "failed",
             "failure",
             "rejected",
             "unusable",
             "invalid",
             "missing",
             "not_usable",
             "no_image",
             "clouded_out"
           ] ->
        0.0

      status when status in ["poor", "degraded", "marginal", "partial"] ->
        0.5

      _status ->
        nil
    end
  end

  defp image_quality_status_feedback_factor(_status), do: nil

  defp inverse_quality_factor(value) when is_number(value), do: 1.0 - clamp_unit_interval(value)
  defp inverse_quality_factor(_value), do: nil

  defp feedback_event_number_value(values, target_id) do
    Enum.find_value([target_id, "default"], fn key ->
      case Map.get(values, key) do
        value when is_number(value) -> value
        _value -> nil
      end
    end)
  end

  defp feedback_event_string_value(values, target_id) do
    Enum.find_value([target_id, "default"], fn key ->
      case encode_value(Map.get(values, key)) do
        value when is_binary(value) and value != "" -> value
        _value -> nil
      end
    end)
  end

  defp command_success_feedback_event(
         activity,
         factor,
         source_scope,
         feedback_key,
         horizon_end_s,
         trust_boundary
       ) do
    %{
      "type" => "command_success_feedback",
      "activity_id" => Map.get(activity, "id") || Map.get(activity, "activity_id"),
      "scenario_id" => Map.get(activity, "scenario_id"),
      "command_success_factor" => factor |> max(0.0) |> min(1.0),
      "feedback_source" => "operational_feedback.command_success_rate",
      "feedback_scope" => source_scope,
      "feedback_key" => feedback_key,
      "starts_at_s" => 0.0,
      "ends_at_s" => horizon_end_s,
      "trust_boundary" =>
        feedback_event_trust_boundary(
          trust_boundary,
          "command_success_rate",
          feedback_key || "default"
        )
    }
    |> compact_map()
  end

