  defp planning_target_priorities(mission_state, prior_plan) do
    [
      Map.get(mission_state, "targets", []),
      Map.get(mission_state, "objectives", []),
      prior_plan_candidate_activities(prior_plan),
      prior_plan_activities(prior_plan)
    ]
    |> List.flatten()
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(%{}, fn item, acc ->
      target_id = Map.get(item, "target_id") || Map.get(item, "id")
      priority = numeric_or_nil(Map.get(item, "priority") || Map.get(item, "target_priority"))

      if target_id in [nil, ""] or not is_number(priority) do
        acc
      else
        Map.put_new(acc, target_id, priority)
      end
    end)
  end

  defp derived_fuel_preservation_branches(mission_state, policy) do
    resources =
      mission_state
      |> Map.get("resources", %{})
      |> stringify_keys()

    fuel_sources = mission_state_resource_margin_sources(mission_state, "fuel_margin")
    fuel_source = List.first(fuel_sources)
    fuel_margin = fuel_source && fuel_source["fuel_margin"]
    requested? = truthy?(Map.get(resources, "fuel_preservation_requested"))
    low_fuel? = is_number(fuel_margin) and fuel_margin <= policy["fuel_margin_threshold"]

    objective_requested? =
      mission_state
      |> Map.get("objectives", [])
      |> Enum.any?(&(Map.get(&1, "type") == "fuel_preservation"))

    if requested? or objective_requested? or low_fuel? do
      [
        %{
          "id" => "derived_fuel_preservation",
          "label" => "Derived fuel preservation",
          "events" =>
            [%{"type" => "fuel_preservation_mode"}] ++
              resource_margin_pressure_events(
                mission_state,
                fuel_sources,
                policy,
                "fuel_margin",
                "fuel_margin_threshold",
                "fuel_margin_low"
              ),
          "metadata" => %{
            "derived_source" => mission_state_resource_source_path(mission_state, "fuel_margin")
          }
        }
      ]
    else
      []
    end
  end

  defp resource_margin_pressure_events(
         mission_state,
         sources,
         policy,
         field,
         threshold_key,
         reason
       ) do
    sources
    |> Enum.filter(fn source ->
      is_number(source[field]) and source[field] <= policy[threshold_key]
    end)
    |> case do
      [] ->
        []

      sources ->
        sources
    end
    |> Enum.map(fn source ->
      %{
        "type" => "resource_margin_pressure",
        "spacecraft_id" =>
          Map.get(source || %{}, "spacecraft_id") ||
            mission_state_resource_spacecraft_id(mission_state),
        "resource_field" => field,
        field => source[field],
        threshold_key => policy[threshold_key],
        "derivation_reasons" => [reason],
        "source_quality" => source && source["source_quality"]
      }
      |> compact_map()
    end)
  end

