  defp normalize_contact_allocation_row(row) do
    row
    |> normalize_contact_allocation_status_field("allocation_status")
    |> normalize_contact_allocation_status_field("effective_allocation_status")
    |> normalize_contact_allocation_status_field("review_status")
    |> normalize_contact_allocation_status_field("approval_status")
    |> normalize_contact_allocation_policy_decision()
  end

  defp normalize_contact_allocation_status_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, normalized_status_token(value))
    end
  end

  defp normalize_contact_allocation_policy_decision(%{"policy_decision" => %{} = decision} = row) do
    decision =
      decision
      |> stringify_keys()
      |> normalize_contact_allocation_status_field("classification")

    Map.put(row, "policy_decision", decision)
  end

  defp normalize_contact_allocation_policy_decision(row), do: row

  defp contact_allocation_effective_status(row) do
    Map.get(row, "effective_allocation_status") || Map.get(row, "allocation_status")
  end

  defp contact_allocation_contact_identity(contact) do
    ContactAllocationPressureBranches.contact_identity(contact)
  end

  defp normalized_status_token(nil), do: nil

  defp normalized_status_token(status) when is_atom(status) do
    status
    |> Atom.to_string()
    |> normalized_status_token()
  end

  defp normalized_status_token(status) when is_binary(status) do
    status
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp normalized_status_token(status), do: status

  defp contact_allocation_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      Map.get(row, "resource_trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_resource_suppression", "resource_trust_boundary"]) ||
      get_in(row, ["source_resource_suppression", "resource_provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

