    |> LinkCapacitySourceReports.prior_plan_reports(prior_plan_source_report_family_callbacks())
    |> LinkCapacityPressureBranches.from_reports(link_capacity_pressure_branch_callbacks())
    |> disambiguate_link_capacity_pressure_branch_ids()
  end

  defp derived_mission_state_link_capacity_pressure_branches(mission_state) do
    mission_state
    |> mission_state_link_capacity_reports()
    |> LinkCapacityPressureBranches.from_reports(link_capacity_pressure_branch_callbacks())
    |> disambiguate_link_capacity_pressure_branch_ids()
  end

  defp mission_state_link_capacity_reports(mission_state) do
    LinkCapacitySourceReports.reports(
      mission_state,
      source_report_family_callbacks()
    )
  end

  defp link_capacity_pressure_branch(row, source_path) do
    LinkCapacityPressureBranches.build(
      row,
      source_path,
      link_capacity_pressure_branch_callbacks()
    )
  end

  defp disambiguate_link_capacity_pressure_branch_ids(branches) do
    LinkCapacityPressureBranches.disambiguate(
      branches,
      link_capacity_pressure_branch_callbacks()
    )
  end

  defp link_capacity_pressure_row?(row) do
    LinkCapacityPressureBranches.pressure_row?(row, link_capacity_pressure_branch_callbacks())
  end

  defp link_capacity_pressure_branch_callbacks,
    do: [
      activity_raw_end: &activity_raw_end/1,
      activity_raw_start: &activity_raw_start/1,
      activity_source_window_id: &activity_source_window_id/1,
      branch_id_fragment: &branch_id_fragment/1,
      compact_map: &compact_map/1,
      contact_identity: &contact_allocation_contact_identity/1,
      encode_value: &encode_value/1,
      nested_ground_station_id: &nested_ground_station_id/1,
      numeric_or_nil: &numeric_or_nil/1,
      positive_number?: &positive_number?/1,
      stable_id_string?: &stable_id_string?/1,
      stringify_keys: &stringify_keys/1
    ]

  defp normalize_downlink_source_list(values) do
    values
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp derived_score_term_pressure_branches(prior_plan) do
    prior_plan
    |> ObjectiveConstraintSourceReports.prior_score_term_reports(
      prior_plan_source_report_family_callbacks()
    )
    |> ObjectiveConstraintSourceReports.pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      score_term_pressure_branch(row, source_path, index)
    end)
  end

  defp derived_mission_state_score_term_pressure_branches(mission_state) do
    mission_state
    |> ObjectiveConstraintSourceReports.score_term_reports(source_report_family_callbacks())
    |> ObjectiveConstraintSourceReports.pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      score_term_pressure_branch(row, source_path, index)
    end)
  end

  defp score_term_pressure_branch(row, source_path, index) do
    row = normalize_score_term_pressure_row(row)

    row
    |> score_term_pressure_events(source_path)
    |> case do
      [] ->
        []

      events ->
        identity =
          row["id"] || row["branch_id"] || row["scenario_id"] ||
            score_term_pressure_event_identity(events) || index

        [
          %{
            "id" => "derived_score_term_pressure_#{branch_id_fragment(identity)}",
            "label" => "Derived score-term pressure #{identity}",
            "events" => events,
            "metadata" =>
              %{
                "derived_source" => source_path,
                "score_term_key" => row["term_key"],
                "score_term_value" => score_term_value(row),
                "score_term_selected" => row["selected"]
              }
              |> compact_map()
          }
        ]
    end
  end

  defp disambiguate_score_term_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if score_term_pressure_branch_id?(branch_id) and Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> score_term_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("score_term_branch_base_id", branch_id)
          |> Map.put("score_term_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_score_term_suffixes()
  end

  defp score_term_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_score_term_pressure_")

  defp score_term_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_score_term_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "score_term_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["score_term_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["score_term_branch_base_id"]}_#{suffix}")
        |> Map.update("metadata", %{}, &Map.put(&1, "score_term_branch_identity", suffix))
      else
        branch
      end
    end)
  end

  defp score_term_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["feedback_source"],
        event["ground_station_id"],
        event["target_id"],
        event["objective_id"],
        event["score_term_key"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["downlink_demand_source"],
        event["downlink_demand_sources"],
        event["downlink_completion_source"],
        event["downlink_completion_sources"],
        event["required_downlink_mb"],
        event["required_contacts"],
        event["required_observations"],
        event["starts_at_s"],
        event["ends_at_s"],
        event["trust_boundary"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp normalize_score_term_pressure_row(row) do
    row
    |> normalize_score_term_pressure_field("term_key")
    |> normalize_objective_pressure_row()
  end

  defp normalize_score_term_pressure_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, score_term_key(value))
    end
  end

  defp score_term_key(key) when is_atom(key) do
    key
    |> Atom.to_string()
    |> score_term_key()
  end

  defp score_term_key(key) when is_binary(key) do
    key
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp score_term_key(key), do: key

  defp score_term_pressure_event_identity(events) do
    Enum.find_value(events, fn event ->
      event["ground_station_id"] || event["target_id"] || event["objective_id"]
    end)
  end

  defp score_term_pressure_events(row, source_path) do
    []
    |> Kernel.++(score_term_collection_latency_gap_events(row, source_path))
    |> Kernel.++(score_term_downlink_gap_events(row, source_path))
    |> Kernel.++(score_term_target_gap_events(row, source_path))
  end

  defp score_term_collection_latency_gap_events(row, source_path) do
    max_latency_s = score_term_max_latency_s(row)
    planned_latency_s = score_term_planned_latency_s(row)
    latency_gap = score_term_latency_gap(row)

    latency_gap? =
      score_term_collection_latency_objective?(row) and
        (positive_number?(latency_gap) or
           (is_number(max_latency_s) and
              (is_nil(planned_latency_s) or planned_latency_s > max_latency_s)))

    if latency_gap? and score_term_collection_latency_routed?(row) do
      planned_downlink_mb = score_term_planned_downlink_mb(row)
      downlink_gap = score_term_downlink_gap(row)

      [
        %{
          "type" => "downlink_completion_gap",
          "objective_id" => row["objective_id"] || row["id"],
          "objective_type" => row["objective"] || row["objective_type"] || "collection_latency",
          "latency_objective" => true,
          "target_id" => score_term_primary_target_id(row),
          "scenario_id" => objective_pressure_scenario_id(row),
          "branch_id" => row["branch_id"],
          "ground_station_id" => score_term_station_id(row),
          "collection_id" => score_term_collection_id(row),
          "collection_ids" => score_term_collection_ids(row),
          "product_id" => score_term_product_id(row),
          "product_ids" => score_term_product_ids(row),
          "payload_id" => score_term_payload_id(row),
          "payload_ids" => score_term_payload_ids(row),
          "instrument_id" => score_term_instrument_id(row),
          "instrument_ids" => score_term_instrument_ids(row),
          "starts_at_s" => score_term_latency_window_start_s(row),
          "ends_at_s" => score_term_latency_window_end_s(row),
          "required_contacts" => score_term_required_contacts(row, score_term_contact_gap(row)),
          "planned_contacts" => score_term_planned_contacts(row),
          "required_downlink_mb" => score_term_required_downlink_mb(row, downlink_gap),
          "planned_downlink_mb" => planned_downlink_mb,
          "max_latency_s" => max_latency_s,
          "planned_latency_s" => planned_latency_s,
          "source_activity_id" => score_term_source_activity_id(row),
          "source_activity_ids" => score_term_source_activity_ids(row),
          "score_term_key" => row["term_key"],
          "score_term_value" => score_term_value(row),
          "timeline_score" => numeric_or_nil(row["timeline_score"]),
          "score_terms" => row["score_terms"],
          "downlink_demand_sources" => [score_term_downlink_source(row)],
          "downlink_completion_sources" => [score_term_downlink_source(row)],
          "derivation_reasons" => score_term_latency_reasons(row, latency_gap),
          "feedback_source" => source_path,
          "feedback_scope" => "score_term",
          "trust_boundary" => score_term_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
  end

  defp score_term_downlink_gap_events(row, source_path) do
    station_id = score_term_station_id(row)
    downlink_gap = score_term_downlink_gap(row)
    contact_gap = score_term_contact_gap(row)

    cond do
      not stable_id_string?(station_id) ->
        []

      not (positive_number?(downlink_gap) or positive_number?(contact_gap)) ->
        []

      true ->
        planned_downlink_mb = score_term_planned_downlink_mb(row)
        planned_contacts = score_term_planned_contacts(row)

        [
          %{
            "type" => "downlink_completion_gap",
            "objective_id" => row["objective_id"] || row["id"],
            "objective_type" => row["objective"] || row["objective_type"] || "score_term_gap",
            "scenario_id" => objective_pressure_scenario_id(row),
            "branch_id" => row["branch_id"],
            "ground_station_id" => station_id,
            "collection_id" => score_term_collection_id(row),
            "collection_ids" => score_term_collection_ids(row),
            "product_id" => score_term_product_id(row),
            "product_ids" => score_term_product_ids(row),
            "payload_id" => score_term_payload_id(row),
            "payload_ids" => score_term_payload_ids(row),
            "instrument_id" => score_term_instrument_id(row),
            "instrument_ids" => score_term_instrument_ids(row),
            "starts_at_s" => score_term_window_start_s(row),
            "ends_at_s" => score_term_window_end_s(row),
            "required_contacts" => score_term_required_contacts(row, contact_gap),
            "planned_contacts" => planned_contacts,
            "required_downlink_mb" => score_term_required_downlink_mb(row, downlink_gap),
            "planned_downlink_mb" => planned_downlink_mb,
            "source_activity_ids" => score_term_source_activity_ids(row),
            "score_term_key" => row["term_key"],
            "score_term_value" => score_term_value(row),
            "timeline_score" => numeric_or_nil(row["timeline_score"]),
            "score_terms" => row["score_terms"],
            "downlink_demand_sources" => [score_term_downlink_source(row)],
            "downlink_completion_sources" => [score_term_downlink_source(row)],
            "derivation_reasons" => score_term_downlink_reasons(row, contact_gap, downlink_gap),
            "feedback_source" => source_path,
            "feedback_scope" => "score_term",
            "trust_boundary" => score_term_trust_boundary(row)
          }
          |> compact_map()
        ]
    end
  end

  defp score_term_target_gap_events(row, source_path) do
    target_gap = score_term_target_gap(row)

    if positive_number?(target_gap) do
      row
      |> score_term_gap_target_ids()
      |> Enum.map(fn target_id ->
        target_spec = score_term_target_spec(row, target_id)

        %{
          "type" => "urgent_target",
          "objective_id" => row["objective_id"] || row["id"],
          "objective_type" =>
            row["objective"] || row["objective_type"] || "score_term_target_gap",
          "target_id" => target_id,
          "scenario_id" => objective_pressure_scenario_id(row),
          "branch_id" => row["branch_id"],
          "starts_at_s" => score_term_window_start_s(row),
          "ends_at_s" => score_term_window_end_s(row),
          "priority" => score_term_target_priority(row, target_spec),
          "latitude_deg" => score_term_target_number(row, target_spec, "latitude_deg"),
          "longitude_deg" => score_term_target_number(row, target_spec, "longitude_deg"),
          "minimum_elevation_deg" =>
            score_term_target_number(row, target_spec, "minimum_elevation_deg"),
          "required_observations" => score_term_required_observations(row, target_gap),
          "planned_observations" => score_term_planned_observations(row),
          "source_activity_ids" => score_term_source_activity_ids(row),
          "score_term_key" => row["term_key"],
          "score_term_value" => score_term_value(row),
          "timeline_score" => numeric_or_nil(row["timeline_score"]),
          "score_terms" => row["score_terms"],
          "derivation_reason" => "score_term_target_gap",
          "derivation_reasons" => score_term_target_reasons(row),
          "feedback_source" => source_path,
          "feedback_scope" => "score_term",
          "trust_boundary" => score_term_trust_boundary(row)
        }
        |> compact_map()
      end)
    else
      []
    end
  end

  defp score_term_downlink_gap(row) do
    score_term_gap_value(row, [
      "downlink_shortfall_mb",
      "selected_downlink_shortfall_mb",
      "missing_downlink_mb",
      "downlink_completion_gap_mb",
      "required_downlink_gap_mb"
    ])
  end

  defp score_term_contact_gap(row) do
    score_term_gap_value(row, [
      "contact_count_gap",
      "downlink_contact_gap",
      "missing_contact_count",
      "downlink_contact_shortfall_count"
    ])
  end

  defp score_term_target_gap(row) do
    score_term_gap_value(row, [
      "observation_count_gap",
      "missing_observation_count",
      "target_observation_gap_count",
      "missed_target_count",
      "target_gap_count",
      "target_coverage_gap_count",
      "coverage_gap_count",
      "observation_shortfall_count",
      "revisit_gap_count",
      "missing_revisit_count",
      "target_revisit_gap_count",
      "revisit_shortfall_count",
      "coverage_shortfall_count"
    ])
  end

  defp score_term_latency_gap(row) do
    score_term_gap_value(row, [
      "collection_latency_gap_s",
      "latency_gap_s",
      "delivery_latency_gap_s",
      "collection_latency_shortfall_s",
      "late_delivery_s"
    ])
  end

  defp score_term_collection_latency_objective?(row) do
    row["objective"] == "collection_latency" or row["objective_type"] == "collection_latency" or
      row["term_key"] in [
        "collection_latency_gap_s",
        "latency_gap_s",
        "delivery_latency_gap_s",
        "collection_latency_shortfall_s",
        "late_delivery_s"
      ] or
      is_number(
        score_terms_number(row, [
          "collection_latency_gap_s",
          "latency_gap_s",
          "delivery_latency_gap_s",
          "collection_latency_shortfall_s",
          "late_delivery_s"
        ])
      )
  end

  defp score_term_collection_latency_routed?(row) do
    stable_id_string?(score_term_source_activity_id(row)) or
      stable_id_string?(score_term_station_id(row)) or
      stable_id_string?(score_term_primary_target_id(row)) or
      stable_id_string?(score_term_collection_id(row)) or
      stable_id_string?(score_term_product_id(row)) or
      stable_id_string?(score_term_payload_id(row)) or
      stable_id_string?(score_term_instrument_id(row))
  end

  defp score_term_gap_value(row, keys) do
    cond do
      row["term_key"] in keys ->
        score_term_value(row)

      is_map(row["score_terms"]) ->
        score_terms_number(row, keys)

      true ->
        nil
    end
  end

  defp score_term_value(row), do: numeric_or_nil(row["value"])

  defp score_term_keyed_map(score_terms) when is_map(score_terms) do
    Map.new(score_terms, fn {key, value} -> {score_term_key(key), value} end)
  end

  defp score_term_keyed_map(_score_terms), do: %{}

  defp score_term_station_id(row) do
    [
      row["ground_station_id"],
      row["station_id"],
      score_term_entity_id(row["ground_station"], ["ground_station_id", "station_id", "id"]),
      score_term_entity_id(row["station"], ["ground_station_id", "station_id", "id"]),
      objective_satisfaction_observation_context_value(row, [
        "ground_station_id",
        "station_id"
      ]),
      objective_pressure_observation_context_entity_id(
        row,
        [
          "ground_station",
          "station"
        ],
        [
          "ground_station_id",
          "station_id",
          "id"
        ]
      )
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp score_term_entity_id(%{} = entity, keys) do
    entity = stringify_keys(entity)

    keys
    |> Enum.map(&Map.get(entity, &1))
    |> Enum.find(&stable_id_string?/1)
  end

  defp score_term_entity_id(_entity, _keys), do: nil

  defp score_terms_number(row, keys) do
    score_terms =
      row
      |> Map.get("score_terms", %{})
      |> score_term_keyed_map()

    keys
    |> Enum.map(&numeric_or_nil(Map.get(score_terms, &1)))
    |> Enum.find(&is_number/1)
  end

  defp score_term_planned_downlink_mb(row) do
    [
      row["planned_downlink_mb"],
      row["selected_downlink_mb"],
      row["actual_downlink_mb"],
      row["planned_data_volume_mb"],
      row["selected_data_volume_mb"],
      row["actual_data_volume_mb"],
      row["delivered_data_volume_mb"],
      row["received_data_volume_mb"],
      row["planned_volume_mb"],
      row["selected_volume_mb"],
      row["actual_volume_mb"],
      objective_pressure_observation_context_number(row, [
        "planned_downlink_mb",
        "selected_downlink_mb",
        "actual_downlink_mb",
        "planned_data_volume_mb",
        "selected_data_volume_mb",
        "actual_data_volume_mb",
        "delivered_data_volume_mb",
        "received_data_volume_mb",
        "planned_volume_mb",
        "selected_volume_mb",
        "actual_volume_mb"
      ])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> value
      _value -> 0.0
    end
  end

  defp score_term_required_downlink_mb(row, downlink_gap) do
    explicit =
      [
        row["required_downlink_mb"],
        row["target_downlink_mb"],
        row["downlink_requirement_mb"],
        row["required_volume_mb"],
        row["required_data_volume_mb"],
        row["target_volume_mb"],
        row["target_data_volume_mb"],
        row["min_downlink_mb"],
        objective_pressure_observation_context_number(row, [
          "required_downlink_mb",
          "target_downlink_mb",
          "downlink_requirement_mb",
          "required_volume_mb",
          "required_data_volume_mb",
          "target_volume_mb",
          "target_data_volume_mb",
          "min_downlink_mb"
        ])
      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    cond do
      is_number(explicit) -> explicit
      positive_number?(downlink_gap) -> score_term_planned_downlink_mb(row) + downlink_gap
      true -> nil
    end
  end

  defp score_term_planned_contacts(row) do
    [
      row["planned_contacts"],
      row["selected_contact_count"],
      row["planned_contact_count"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> value
      _value -> 0
    end
  end

  defp score_term_required_contacts(row, contact_gap) do
    explicit =
      [
        row["required_contacts"],
        row["required_contact_count"],
        row["expected_contact_count"]
      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    cond do
      is_number(explicit) -> explicit
      positive_number?(contact_gap) -> score_term_planned_contacts(row) + contact_gap
      true -> 1
    end
  end

  defp score_term_planned_observations(row) do
    [
      row["planned_observations"],
      row["selected_observation_count"],
      row["planned_observation_count"],
      row["selected_count"],
      row["planned_revisits"],
      row["selected_revisits"],
      row["satisfied_revisits"],
      row["planned_revisit_count"],
      row["selected_revisit_count"],
      row["satisfied_revisit_count"],
      row["target_planned_revisit_count"],
      row["planned_coverage_count"],
      row["selected_coverage_count"],
      row["satisfied_coverage_count"],
      row["target_planned_coverage_count"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> value
      _value -> 0
    end
  end

  defp score_term_required_observations(row, target_gap) do
    explicit =
      [
        row["required_observations"],
        row["required_observation_count"],
        row["required_count"],
        row["required_revisits"],
        row["required_revisit_count"],
        row["target_required_revisit_count"],
        row["required_coverage_count"],
        row["target_required_coverage_count"]
      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    cond do
      is_number(explicit) ->
        max(ceil_count(explicit), 1)

      positive_number?(target_gap) ->
        max(ceil_count(score_term_planned_observations(row) + target_gap), 1)

      true ->
        1
    end
  end

  defp score_term_gap_target_ids(row) do
    [
      row["target_id"],
      row["target"],
      row["target_ids"],
      row["targets"],
      row["target_specs"],
      row["required_target"],
      row["required_targets"],
      row["committed_target"],
      row["committed_targets"],
      row["priority_target"],
      row["priority_targets"],
      row["candidate_target"],
      row["candidate_targets"],
      row["uncovered_target"],
      row["uncovered_targets"],
      row["unsatisfied_target"],
      row["unsatisfied_targets"],
      row["missing_target"],
      row["missing_targets"],
      row["missed_target"],
      row["missed_targets"],
      row["missed_observation_target"],
      row["missed_observation_targets"],
      row["revisit_target"],
      row["revisit_targets"],
      row["required_revisit_target"],
      row["required_revisit_targets"],
      row["missing_revisit_target"],
      row["missing_revisit_targets"],
      row["coverage_target"],
      row["coverage_targets"],
      row["required_coverage_target"],
      row["required_coverage_targets"],
      row["missing_coverage_target"],
      row["missing_coverage_targets"],
      row["target_gap_target"],
      row["target_gap_targets"],
      row["missed_target_ids"],
      row["missed_observation_target_ids"],
      row["required_target_ids"],
      row["candidate_target_ids"],
      row["uncovered_target_ids"],
      row["unsatisfied_target_ids"],
      row["missing_target_ids"],
      row["revisit_target_ids"],
      row["required_revisit_target_ids"],
      row["missing_revisit_target_ids"],
      row["coverage_target_ids"],
      row["required_coverage_target_ids"],
      row["missing_coverage_target_ids"],
      row["target_gap_ids"]
    ]
    |> Enum.flat_map(&score_term_target_ids/1)
    |> Kernel.++(objective_pressure_gap_context_target_ids(row))
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp score_term_target_ids(values) when is_list(values) do
    Enum.flat_map(values, &score_term_target_ids/1)
  end

  defp score_term_target_ids(%{} = target) do
    target = stringify_keys(target)
    [Map.get(target, "target_id") || Map.get(target, "id")]
  end

  defp score_term_target_ids(value), do: [encode_value(value)]

  defp score_term_source_activity_ids(row) do
    [
      row["activity_ids"],
      row["activities"],
      row["source_activity_ids"],
      row["source_activity_id"],
      row["source_activity"],
      row["source_activities"],
      row["contact_ids"],
      row["contact_id"],
      row["contacts"],
      row["contact"],
      row["selected_contact_ids"],
      row["selected_contacts"],
      row["selected_contact"],
      row["observation_activity_ids"],
      row["observation_activity_id"],
      row["observations"],
      row["observation"],
      row["selected_observation_ids"],
      row["selected_observation_id"],
      row["selected_observations"],
      row["selected_observation"],
      row["candidate_observation_ids"],
      row["candidate_observation_id"],
      row["candidate_observations"],
      row["candidate_observation"],
      row["source_observation"],
      row["source_observations"],
      row["activity_id"]
    ]
    |> Enum.flat_map(&score_term_activity_id_values/1)
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp score_term_source_activity_id(row) do
    [
      row["source_activity_id"],
      row["observation_activity_id"],
      row["selected_observation_id"],
      row["candidate_observation_id"],
      row["activity_id"]
    ]
    |> Enum.find(&stable_id_string?/1) ||
      first_stable_activity_id([
        row["source_activity"],
        row["source_activities"],
        row["source_observation"],
        row["source_observations"],
        row["observation"],
        row["observations"],
        row["selected_observation"],
        row["selected_observations"],
        row["candidate_observation"],
        row["candidate_observations"],
        row["activity"],
        row["activities"]
      ]) ||
      row
      |> score_term_source_activity_ids()
      |> List.first()
  end

  defp first_stable_activity_id(values) do
    values
    |> Enum.flat_map(&score_term_activity_id_values/1)
    |> Enum.find(&stable_id_string?/1)
  end

  defp score_term_activity_id_values(values) when is_list(values) do
    Enum.flat_map(values, &score_term_activity_id_values/1)
  end

  defp score_term_activity_id_values(%{} = activity) do
    activity = stringify_keys(activity)

    [
      activity["activity_id"],
      activity["source_activity_id"],
      activity["observation_activity_id"],
      activity["contact_id"],
      activity["downlink_activity_id"],
      activity["id"]
    ]
  end

  defp score_term_activity_id_values(value), do: [encode_value(value)]

  defp score_term_primary_target_id(row) do
    row
    |> score_term_gap_target_ids()
    |> List.first()
  end

  defp score_term_collection_id(row) do
    [
      row["collection_id"],
      score_term_entity_id(row["collection"], ["collection_id", "id"]),
      objective_pressure_collection_id(row)
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp score_term_collection_ids(row) do
    [
      row["collection_ids"],
      row["collections"],
      objective_satisfaction_observation_context_value(row, ["collection_ids", "collections"]),
      score_term_collection_id(row)
    ]
    |> score_term_stable_id_values(["collection_id", "id"])
  end

  defp score_term_product_id(row) do
    [
      row["product_id"],
      row["data_product_id"],
      score_term_entity_id(row["product"], ["product_id", "data_product_id", "id"]),
      score_term_entity_id(row["data_product"], ["product_id", "data_product_id", "id"]),
      objective_pressure_product_id(row)
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp score_term_product_ids(row) do
    [
      row["product_ids"],
      row["data_product_ids"],
      row["products"],
      row["data_products"],
      objective_satisfaction_observation_context_value(row, [
        "product_ids",
        "data_product_ids",
        "products",
        "data_products"
      ]),
      score_term_product_id(row)
    ]
    |> Enum.flat_map(&score_term_product_id_values/1)
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp score_term_product_id_values(values) when is_list(values) do
    Enum.flat_map(values, &score_term_product_id_values/1)
  end

  defp score_term_product_id_values(%{} = product) do
    product = stringify_keys(product)
    [product["product_id"] || product["data_product_id"] || product["id"]]
  end

  defp score_term_product_id_values(value), do: [encode_value(value)]

  defp score_term_payload_id(row) do
    [
      row["payload_id"],
      score_term_entity_id(row["payload"], ["payload_id", "id"]),
      objective_pressure_payload_id(row)
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp score_term_payload_ids(row) do
    [
      row["payload_ids"],
      row["payloads"],
      objective_satisfaction_observation_context_value(row, ["payload_ids", "payloads"]),
      score_term_payload_id(row)
    ]
    |> score_term_stable_id_values(["payload_id", "id"])
  end

  defp score_term_instrument_id(row) do
    [
      row["instrument_id"],
      score_term_entity_id(row["instrument"], ["instrument_id", "id"]),
      objective_pressure_instrument_id(row)
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp score_term_instrument_ids(row) do
    [
      row["instrument_ids"],
      row["instruments"],
      objective_satisfaction_observation_context_value(row, ["instrument_ids", "instruments"]),
      score_term_instrument_id(row)
    ]
    |> score_term_stable_id_values(["instrument_id", "id"])
  end

  defp score_term_stable_id_values(values, keys) do
    values
    |> Enum.flat_map(&score_term_stable_id_values_from_value(&1, keys))
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp score_term_stable_id_values_from_value(values, keys) when is_list(values) do
    Enum.flat_map(values, &score_term_stable_id_values_from_value(&1, keys))
  end

  defp score_term_stable_id_values_from_value(%{} = entity, keys) do
    entity = stringify_keys(entity)
    Enum.map(keys, &Map.get(entity, &1))
  end

  defp score_term_stable_id_values_from_value(value, _keys), do: [encode_value(value)]

  defp score_term_window_start_s(row),
    do:
      numeric_or_nil(
        row["starts_at_s"] || row["start_s"] || row["window_starts_at_s"] ||
          objective_pressure_observation_context_number(row, [
            "starts_at_s",
            "start_s",
            "window_starts_at_s"
          ])
      )

  defp score_term_window_end_s(row),
    do:
      numeric_or_nil(
        row["ends_at_s"] || row["end_s"] || row["window_ends_at_s"] ||
          objective_pressure_observation_context_number(row, [
            "ends_at_s",
            "end_s",
            "window_ends_at_s"
          ])
      )

  defp score_term_max_latency_s(row),
    do:
      numeric_or_nil(
        row["max_latency_s"] || row["required_latency_s"] || row["target_latency_s"] ||
          row["latency_limit_s"] || row["max_delivery_latency_s"] ||
          row["required_delivery_latency_s"] ||
          objective_pressure_observation_context_number(row, [
            "max_latency_s",
            "required_latency_s",
            "target_latency_s",
            "latency_limit_s",
            "max_delivery_latency_s",
            "required_delivery_latency_s"
          ])
      )

  defp score_term_planned_latency_s(row),
    do:
      numeric_or_nil(
        row["planned_latency_s"] || row["actual_latency_s"] || row["delivery_latency_s"] ||
          row["planned_delivery_latency_s"] || row["actual_delivery_latency_s"] ||
          objective_pressure_observation_context_number(row, [
            "planned_latency_s",
            "actual_latency_s",
            "delivery_latency_s",
            "planned_delivery_latency_s",
            "actual_delivery_latency_s"
          ])
      )

  defp score_term_latency_window_start_s(row) do
    numeric_or_nil(
      row["starts_at_s"] || row["window_starts_at_s"] || row["source_activity_ends_at_s"] ||
        row["observation_ends_at_s"] || row["collection_ends_at_s"] ||
        row["collection_end_s"] || row["start_s"] ||
        objective_pressure_observation_context_number(row, [
          "source_activity_ends_at_s",
          "observation_ends_at_s",
          "collection_ends_at_s",
          "collection_end_s",
          "ends_at_s",
          "end_s"
        ])
    )
  end

  defp score_term_latency_window_end_s(row) do
    explicit_end =
      numeric_or_nil(
        row["ends_at_s"] || row["window_ends_at_s"] || row["deadline_s"] ||
          row["delivery_deadline_s"] || row["latency_deadline_s"] || row["end_s"] ||
          objective_pressure_observation_context_number(row, [
            "deadline_s",
            "delivery_deadline_s",
            "latency_deadline_s"
          ])
      )

    start_s = score_term_latency_window_start_s(row)
    max_latency_s = score_term_max_latency_s(row)

    cond do
      is_number(explicit_end) -> explicit_end
      is_number(start_s) and is_number(max_latency_s) -> start_s + max_latency_s
      true -> nil
    end
  end

  defp score_term_target_spec(row, target_id) do
    [
      row["target"],
      row["targets"],
      row["target_specs"],
      row["required_target"],
      row["required_targets"],
      row["committed_target"],
      row["committed_targets"],
      row["priority_target"],
      row["priority_targets"],
      row["candidate_target"],
      row["candidate_targets"],
      row["uncovered_target"],
      row["uncovered_targets"],
      row["unsatisfied_target"],
      row["unsatisfied_targets"],
      row["missing_target"],
      row["missing_targets"],
      row["missed_target"],
      row["missed_targets"],
      row["missed_observation_target"],
      row["missed_observation_targets"],
      row["revisit_target"],
      row["revisit_targets"],
      row["required_revisit_target"],
      row["required_revisit_targets"],
      row["missing_revisit_target"],
      row["missing_revisit_targets"],
      row["coverage_target"],
      row["coverage_targets"],
      row["required_coverage_target"],
      row["required_coverage_targets"],
      row["missing_coverage_target"],
      row["missing_coverage_targets"],
      row["target_gap_target"],
      row["target_gap_targets"]
    ]
    |> List.flatten()
    |> Enum.map(fn
      %{} = target -> stringify_keys(target)
      _target -> nil
    end)
    |> Enum.reject(&is_nil/1)
    |> Enum.find(fn target ->
      (Map.get(target, "target_id") || Map.get(target, "id")) == target_id
    end)
    |> case do
      %{} = target -> target
      _target -> objective_pressure_gap_context_target_spec(row, target_id) || %{}
    end
  end

  defp score_term_target_priority(row, target_spec) do
    [
      target_spec["priority"],
      target_spec["target_priority"],
      row["priority"],
      row["target_priority"],
      score_terms_number(row, ["target_value"]),
      row["timeline_score"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
  end

  defp score_term_target_number(row, target_spec, field) do
    numeric_or_nil(Map.get(target_spec, field) || Map.get(row, field))
  end

  defp score_term_downlink_source(row) do
    [
      "score_term",
      row["id"] || row["scenario_id"] || row["term_key"] || "row",
      row["term_key"] || "gap"
    ]
    |> Enum.map(&branch_id_fragment/1)
    |> Enum.join(":")
  end

  defp score_term_downlink_reasons(row, contact_gap, downlink_gap) do
    []
    |> maybe_append_reason(positive_number?(downlink_gap), "score_term_downlink_volume_gap")
    |> maybe_append_reason(positive_number?(contact_gap), "score_term_contact_count_gap")
    |> maybe_append_reason(row["term_key"] not in [nil, ""], "score_term_#{row["term_key"]}")
    |> Enum.reverse()
    |> Enum.uniq()
  end

  defp score_term_target_reasons(row) do
    []
    |> maybe_append_reason(true, "score_term_target_gap")
    |> maybe_append_reason(row["term_key"] not in [nil, ""], "score_term_#{row["term_key"]}")
    |> Enum.reverse()
    |> Enum.uniq()
  end

  defp score_term_latency_reasons(row, latency_gap) do
    []
    |> maybe_append_reason(true, "collection_latency_gap")
    |> maybe_append_reason(true, "score_term_collection_latency_gap")
    |> maybe_append_reason(positive_number?(latency_gap), "score_term_latency_gap")
    |> maybe_append_reason(row["term_key"] not in [nil, ""], "score_term_#{row["term_key"]}")
    |> Enum.reverse()
    |> Enum.uniq()
  end

  defp score_term_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp derived_objective_satisfaction_pressure_branches(prior_plan) do
    prior_plan
    |> ObjectiveConstraintSourceReports.prior_objective_satisfaction_reports(
      prior_plan_source_report_family_callbacks()
    )
    |> ObjectiveConstraintSourceReports.pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      objective_satisfaction_pressure_branch(row, source_path, index)
    end)
  end

  defp derived_mission_state_objective_satisfaction_pressure_branches(mission_state) do
    mission_state
    |> ObjectiveConstraintSourceReports.objective_satisfaction_reports(
      source_report_family_callbacks()
    )
    |> ObjectiveConstraintSourceReports.pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      objective_satisfaction_pressure_branch(row, source_path, index)
    end)
  end

  defp objective_satisfaction_pressure_branch(row, source_path, index) do
    row =
      row
      |> normalize_objective_satisfaction_row_status()
      |> normalize_objective_pressure_row()

    row
    |> objective_satisfaction_pressure_events(source_path)
    |> Enum.map(fn event ->
      objective_id = objective_satisfaction_branch_identity(row, event, index)

      %{
        "id" => "derived_objective_satisfaction_#{branch_id_fragment(objective_id)}",
        "label" => "Derived objective satisfaction pressure #{objective_id}",
        "events" => [event],
        "metadata" =>
          %{
            "derived_source" => source_path,
            "objective" => row["objective"],
            "objective_status" => row["status"],
            "source_objective_status" => row["_source_objective_status"]
          }
          |> compact_map()
      }
    end)
  end

  defp disambiguate_objective_satisfaction_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if objective_satisfaction_pressure_branch_id?(branch_id) and
           Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> objective_satisfaction_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("objective_satisfaction_branch_base_id", branch_id)
          |> Map.put("objective_satisfaction_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_objective_satisfaction_suffixes()
  end

  defp objective_satisfaction_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_objective_satisfaction_")

  defp objective_satisfaction_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_objective_satisfaction_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "objective_satisfaction_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["objective_satisfaction_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["objective_satisfaction_branch_base_id"]}_#{suffix}")
        |> Map.update(
          "metadata",
          %{},
          &Map.put(&1, "objective_satisfaction_branch_identity", suffix)
        )
      else
        branch
      end
    end)
  end

  defp objective_satisfaction_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["feedback_source"],
        event["objective_id"],
        event["objective_type"],
        event["ground_station_id"],
        event["target_id"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["missed_downlink_activity_id"],
        event["missed_downlink_activity_ids"],
        event["required_downlink_mb"],
        event["required_contacts"],
        event["required_observations"],
        event["starts_at_s"],
        event["ends_at_s"],
        event["trust_boundary"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp objective_satisfaction_branch_identity(row, event, index) do
    base = Map.get(row, "id") || Map.get(row, "objective") || index

    case {row["objective"], event["target_id"], event["source_activity_id"]} do
      {objective, target_id, _source_activity_id}
      when objective in ["target_coverage", "coverage"] and target_id not in [nil, ""] ->
        "#{base}:#{target_id}"

      {"collection_latency", _target_id, source_activity_id}
      when source_activity_id not in [nil, ""] ->
        "#{base}:#{source_activity_id}"

      {objective, target_id, _source_activity_id}
      when objective in ["observation_success", "observation_quality", "image_quality"] and
             target_id not in [nil, ""] ->
        "#{base}:#{target_id}"

      {_objective, _target_id, _source_activity_id} ->
        base
    end
  end

  defp objective_satisfaction_pressure_events(%{"objective" => objective} = row, source_path)
       when objective in ["downlink_completion", "required_downlink_completion"] do
    required_contacts = objective_satisfaction_required_contacts(row)
    planned_contacts = objective_satisfaction_planned_contacts(row)
    required_downlink_mb = objective_satisfaction_required_downlink_mb(row)
    planned_downlink_mb = objective_satisfaction_planned_downlink_mb(row)

    contact_gap? =
      is_number(required_contacts) and required_contacts > planned_contacts

    volume_gap? =
      is_number(required_downlink_mb) and required_downlink_mb > planned_downlink_mb

    if objective_satisfaction_gap_status?(row["status"]) and (contact_gap? or volume_gap?) do
      [
        %{
          "type" => "downlink_completion_gap",
          "objective_id" => row["id"],
          "objective_type" => row["objective"],
          "scenario_id" => objective_pressure_scenario_id(row),
          "ground_station_id" => objective_pressure_station_id(row),
          "collection_id" => objective_pressure_collection_id(row),
          "collection_ids" => objective_pressure_collection_ids(row),
          "product_id" => objective_pressure_product_id(row),
          "product_ids" => objective_pressure_product_ids(row),
          "payload_id" => objective_pressure_payload_id(row),
          "payload_ids" => objective_pressure_payload_ids(row),
          "instrument_id" => objective_pressure_instrument_id(row),
          "instrument_ids" => objective_pressure_instrument_ids(row),
          "starts_at_s" => objective_satisfaction_window_start_s(row),
          "ends_at_s" => objective_satisfaction_window_end_s(row),
          "required_contacts" => required_contacts,
          "planned_contacts" => planned_contacts,
          "required_downlink_mb" => required_downlink_mb,
          "planned_downlink_mb" => planned_downlink_mb,
          "source_activity_ids" => objective_satisfaction_source_contact_ids(row),
          "derivation_reasons" =>
            objective_satisfaction_pressure_reasons(row, contact_gap?, volume_gap?),
          "feedback_source" => source_path,
          "feedback_scope" => "objective_satisfaction",
          "objective_status" => row["status"],
          "source_objective_status" => row["_source_objective_status"],
          "trust_boundary" => objective_satisfaction_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
  end

  defp objective_satisfaction_pressure_events(%{"objective" => objective} = row, source_path)
       when objective in [
              "target_coverage",
              "coverage",
              "target_commitment",
              "priority_commitment",
              "target_observation",
              "target_revisit"
            ] do
    if objective_satisfaction_gap_status?(row["status"]) do
      row
      |> objective_satisfaction_gap_target_ids()
      |> Enum.map(&objective_satisfaction_target_event(row, source_path, &1))
    else
      []
    end
  end

  defp objective_satisfaction_pressure_events(
         %{"objective" => "collection_latency"} = row,
         source_path
       ) do
    if objective_satisfaction_gap_status?(row["status"]) do
      [
        row
        |> objective_satisfaction_collection_latency_event(source_path)
        |> compact_map()
      ]
    else
      []
    end
  end

  defp objective_satisfaction_pressure_events(%{"objective" => objective} = row, source_path)
       when objective in ["observation_success", "observation_quality", "image_quality"] do
    if objective_satisfaction_gap_status?(row["status"]) do
      row
      |> objective_satisfaction_observation_quality_event(source_path)
      |> case do
        nil -> []
        event -> [event]
      end
    else
      []
    end
  end

  defp objective_satisfaction_pressure_events(_row, _source_path), do: []

  defp objective_satisfaction_observation_quality_event(row, source_path) do
    target_id = objective_satisfaction_primary_target_id(row)
    explicit_factor = objective_satisfaction_observation_success_factor(row)
    image_quality_score = image_quality_score_value(row)
    image_quality_status = image_quality_status_value(row)
    image_quality_source = image_quality_source_value(row)
    cloud_cover_fraction = cloud_cover_fraction_value(row)
    blur_score = blur_score_value(row)

    quality_evidence? =
      is_number(image_quality_score) or image_quality_status not in [nil, ""] or
        is_number(cloud_cover_fraction) or is_number(blur_score)

    {quality_factor, quality_feedback_source} =
      observation_quality_feedback_factor(
        image_quality_score,
        image_quality_status,
        cloud_cover_fraction,
        blur_score
      )

    factor = explicit_factor || if(quality_evidence?, do: quality_factor)

    if stable_id_string?(target_id) and is_number(factor) do
      %{
        "type" => "observation_success_feedback",
        "objective_id" => row["id"] || row["objective_id"],
        "objective_type" => row["objective"],
        "target_id" => target_id,
        "scenario_id" => objective_pressure_scenario_id(row),
        "spacecraft_id" => objective_pressure_spacecraft_id(row),
        "starts_at_s" => objective_satisfaction_window_start_s(row),
        "ends_at_s" => objective_satisfaction_window_end_s(row),
        "priority" => objective_satisfaction_target_priority(row, %{}),
        "required_observations" => objective_satisfaction_required_target_observations(row),
        "observation_success_factor" => factor,
        "image_quality_score" => image_quality_score,
        "image_quality_status" => image_quality_status,
        "image_quality_source" => image_quality_source,
        "cloud_cover_fraction" => cloud_cover_fraction,
        "blur_score" => blur_score,
        "source_activity_id" => objective_satisfaction_source_activity_id(row),
        "source_activity_ids" => objective_satisfaction_source_activity_ids(row),
        "derivation_reasons" =>
          objective_satisfaction_observation_quality_reasons(
            row,
            explicit_factor,
            image_quality_score,
            image_quality_status,
            cloud_cover_fraction,
            blur_score
          ),
        "feedback_source" => source_path,
        "feedback_scope" => "objective_satisfaction",
        "quality_feedback_source" =>
          objective_satisfaction_quality_feedback_source(quality_feedback_source),
        "objective_status" => row["status"],
        "source_objective_status" => row["_source_objective_status"],
        "trust_boundary" => objective_satisfaction_trust_boundary(row)
      }
      |> compact_map()
    end
  end

  defp objective_satisfaction_observation_success_factor(row) do
    first_unit_interval_activity_value(row, [
      "observation_success_factor",
      "observation_success_rate",
      "observation_success",
      "success_factor",
      "success_rate",
      "realized_success_factor",
      "planned_success_factor",
      ["quality", "observation_success_factor"],
      ["metadata", "observation_success_factor"]
    ])
  end

  defp objective_satisfaction_observation_quality_reasons(
         row,
         explicit_factor,
         image_quality_score,
         image_quality_status,
         cloud_cover_fraction,
         blur_score
       ) do
    []
    |> maybe_append_reason(is_number(explicit_factor), "objective_satisfaction_success_factor")
    |> maybe_append_reason(is_number(image_quality_score), "objective_satisfaction_image_quality")
    |> maybe_append_reason(
      image_quality_status not in [nil, ""],
      "objective_satisfaction_image_quality_status"
    )
    |> maybe_append_reason(is_number(cloud_cover_fraction), "objective_satisfaction_cloud_cover")
    |> maybe_append_reason(is_number(blur_score), "objective_satisfaction_blur")
    |> maybe_append_reason(row["status"] not in [nil, ""], "objective_status_#{row["status"]}")
    |> Enum.reverse()
  end

  defp objective_satisfaction_quality_feedback_source(source) when is_binary(source) do
    String.replace_prefix(source, "operational_feedback.", "objective_satisfaction.")
  end

  defp objective_satisfaction_quality_feedback_source(_source), do: nil

