      "scenario_id" => objective_pressure_scenario_id(row),
      "ground_station_id" => objective_pressure_station_id(row),
      "collection_id" => objective_pressure_collection_id(row),
      "collection_ids" => objective_pressure_collection_ids(row),
      "product_id" => objective_pressure_product_id(row),
      "product_ids" => objective_pressure_product_ids(row),
      "payload_id" => objective_pressure_payload_id(row),
      "payload_ids" => objective_pressure_payload_ids(row),
      "instrument_id" => objective_pressure_instrument_id(row),
      "instrument_ids" => objective_pressure_instrument_ids(row),
      "starts_at_s" => objective_satisfaction_latency_window_start_s(row),
      "ends_at_s" => objective_satisfaction_latency_window_end_s(row),
      "required_contacts" => objective_satisfaction_required_collection_latency_contacts(row),
      "planned_contacts" => objective_satisfaction_planned_contacts(row),
      "required_downlink_mb" => required_downlink_mb,
      "planned_downlink_mb" => planned_downlink_mb,
      "max_latency_s" => objective_satisfaction_max_latency_s(row),
      "planned_latency_s" => objective_satisfaction_planned_latency_s(row),
      "source_activity_id" => objective_satisfaction_source_activity_id(row),
      "source_activity_ids" => objective_satisfaction_source_activity_ids(row),
      "missed_downlink_activity_id" => objective_satisfaction_missed_downlink_activity_id(row),
      "missed_downlink_activity_ids" => objective_satisfaction_missed_downlink_activity_ids(row),
      "realized_status" => row["realized_status"],
      "contact_result" => provider_result_artifact_value(row["contact_result"]),
      "derivation_reasons" => objective_satisfaction_collection_latency_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "objective_satisfaction",
      "objective_status" => row["status"],
      "source_objective_status" => row["_source_objective_status"],
      "trust_boundary" => objective_satisfaction_trust_boundary(row)
    }
  end

  defp objective_satisfaction_target_event(row, source_path, target_id) do
    target_spec = objective_satisfaction_target_spec(row, target_id)

    %{
      "type" => "urgent_target",
      "objective_id" => row["id"],
      "objective_type" => objective_satisfaction_target_objective_type(row["objective"]),
      "target_id" => target_id,
      "scenario_id" => objective_pressure_scenario_id(row),
      "spacecraft_id" => objective_pressure_spacecraft_id(row),
      "starts_at_s" => objective_satisfaction_window_start_s(row),
      "ends_at_s" => objective_satisfaction_window_end_s(row),
      "priority" => objective_satisfaction_target_priority(row, target_spec),
      "latitude_deg" => objective_satisfaction_target_number(row, target_spec, "latitude_deg"),
      "longitude_deg" => objective_satisfaction_target_number(row, target_spec, "longitude_deg"),
      "minimum_elevation_deg" =>
        objective_satisfaction_target_number(row, target_spec, "minimum_elevation_deg"),
      "candidate_windows" => objective_satisfaction_candidate_windows(row),
      "allowed_scenario_ids" => objective_satisfaction_allowed_scenario_ids(row),
      "spacecraft_constraints" => objective_satisfaction_allowed_scenario_ids(row),
      "coverage_objective_id" => objective_satisfaction_coverage_objective_id(row),
      "planned_observations" =>
        objective_satisfaction_planned_target_observations(row, target_id),
      "required_observations" => objective_satisfaction_required_target_observations(row),
      "source_activity_ids" => objective_satisfaction_source_observation_ids(row),
      "derivation_reason" => "objective_satisfaction_#{row["status"]}",
      "derivation_reasons" => objective_satisfaction_target_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "objective_satisfaction",
      "objective_status" => row["status"],
      "source_objective_status" => row["_source_objective_status"],
      "trust_boundary" => objective_satisfaction_trust_boundary(row)
    }
