  defp normalize_objective_satisfaction_row_status(row) do
    case objective_satisfaction_row_status_value(row) do
      status when status in [nil, ""] ->
        row

      status ->
        source_status = objective_satisfaction_status_label(status)
        normalized_status = objective_satisfaction_status(status)

        row
        |> put_if_present("status", normalized_status)
        |> put_source_objective_status(source_status, normalized_status)
    end
  end

  defp put_source_objective_status(row, source_status, normalized_status) do
    if source_status in [nil, "", normalized_status] do
      row
    else
      Map.put(row, "_source_objective_status", source_status)
    end
  end

  defp objective_satisfaction_row_status_value(row) do
