  defp objective_pressure_label(label) when is_atom(label) do
    label
    |> Atom.to_string()
    |> objective_pressure_label()
  end

  defp objective_pressure_label(label) when is_binary(label) do
    label
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp objective_pressure_label(label), do: label

  defp objective_satisfaction_status(status) when is_boolean(status),
    do: if(status, do: "met", else: "unmet")

  defp objective_satisfaction_status(status) when is_atom(status),
    do: status |> objective_satisfaction_status_label() |> objective_satisfaction_status()

  defp objective_satisfaction_status(status) when is_binary(status) do
    case objective_satisfaction_status_label(status) do
      status when status in ["satisfied", "complete", "completed"] ->
        "met"

      status when status in ["unsatisfied", "not_satisfied", "not_met", "missing"] ->
        "unmet"

      status when status in ["missed", "failed", "late", "overdue", "violated", "breached"] ->
        "unmet"

      status
      when status in [
             "shortfall",
             "insufficient",
             "below_target",
             "below_threshold",
             "under_target",
             "under_threshold",
             "gap",
             "has_gap",
             "at_risk",
             "needs_replan",
             "needs_refresh",
             "requires_attention",
             "degraded",
             "behind_plan"
           ] ->
        "partial"

      status
      when status in ["candidate_found", "candidate_window_available", "viable_candidate"] ->
        "candidate_available"

      status when status in ["no_candidate", "no_window", "no_viable_candidate"] ->
        "no_candidate_window"

      status ->
        status
    end
  end

  defp objective_satisfaction_status(status), do: status

  defp objective_satisfaction_status_label(status) when is_boolean(status),
    do: if(status, do: "met", else: "unmet")

  defp objective_satisfaction_status_label(status) when is_atom(status) do
