      gap when is_number(gap) and gap > 0.0 ->
        planned_observations = objective_satisfaction_planned_observations(row)
        planned_count = planned_observations || objective_satisfaction_planned_contacts(row)

        planned_count + gap

      _gap ->
        nil
    end
  end

