  defp objective_satisfaction_latency_window_start_s(row) do
    numeric_or_nil(
      objective_satisfaction_window_start_s(row) || row["source_activity_ends_at_s"] ||
        row["observation_ends_at_s"] || row["collection_ends_at_s"] ||
        row["collection_end_s"] ||
