  defp objective_satisfaction_latency_window_end_s(row) do
    explicit_end =
      numeric_or_nil(
        objective_satisfaction_window_end_s(row) || row["deadline_s"] ||
          row["delivery_deadline_s"] || row["latency_deadline_s"] ||
          objective_pressure_observation_context_number(row, [
            "deadline_s",
            "delivery_deadline_s",
            "latency_deadline_s"
          ])
      )

    start_s = objective_satisfaction_latency_window_start_s(row)
    max_latency_s = objective_satisfaction_max_latency_s(row)

    cond do
      is_number(explicit_end) ->
        explicit_end

      is_number(start_s) and is_number(max_latency_s) ->
        start_s + max_latency_s

      true ->
        nil
    end
  end

