    mission_state
    |> ObjectiveConstraintSourceReports.objective_tradeoff_reports(
      source_report_family_callbacks()
    )
    |> ObjectiveConstraintSourceReports.objective_tradeoff_pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      objective_tradeoff_pressure_branch(row, source_path, index)
    end)
  end

  defp objective_tradeoff_pressure_branch(row, source_path, index) do
    row =
      row
      |> normalize_objective_tradeoff_row()
      |> normalize_objective_pressure_row()

    row
    |> objective_tradeoff_pressure_events(source_path)
    |> case do
      [] ->
        []

      events ->
        identity = row["branch_id"] || row["scenario_id"] || row["id"] || index

        [
          %{
            "id" => "derived_objective_tradeoff_pressure_#{branch_id_fragment(identity)}",
            "label" => "Derived objective tradeoff pressure #{identity}",
            "events" => events,
            "metadata" =>
              %{
                "derived_source" => source_path,
                "objective_tradeoff_rank" => row["rank"],
                "objective_tradeoff_selected" => row["selected"],
                "score_delta_from_selected" => row["score_delta_from_selected"]
              }
              |> compact_map()
          }
        ]
    end
  end

  defp disambiguate_objective_tradeoff_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if objective_tradeoff_pressure_branch_id?(branch_id) and
           Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> objective_tradeoff_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("objective_tradeoff_branch_base_id", branch_id)
          |> Map.put("objective_tradeoff_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_objective_tradeoff_suffixes()
  end

  defp objective_tradeoff_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_objective_tradeoff_pressure_")

  defp objective_tradeoff_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_objective_tradeoff_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "objective_tradeoff_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["objective_tradeoff_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["objective_tradeoff_branch_base_id"]}_#{suffix}")
        |> Map.update(
          "metadata",
          %{},
          &Map.put(&1, "objective_tradeoff_branch_identity", suffix)
        )
      else
        branch
      end
    end)
  end

  defp objective_tradeoff_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["feedback_source"],
        event["branch_id"],
        event["objective_id"],
        event["objective_type"],
        event["ground_station_id"],
        event["target_id"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["required_downlink_mb"],
        event["required_contacts"],
        event["required_observations"],
        event["starts_at_s"],
        event["ends_at_s"],
        event["trust_boundary"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp normalize_objective_tradeoff_row(%{"selected" => selected} = row) do
    case json_boolean_value(selected) do
      value when is_boolean(value) -> Map.put(row, "selected", value)
      _value -> row
    end
  end

  defp normalize_objective_tradeoff_row(row), do: row

  defp objective_tradeoff_pressure_events(row, source_path) do
    []
    |> Kernel.++(objective_tradeoff_downlink_gap_events(row, source_path))
    |> Kernel.++(objective_tradeoff_target_gap_events(row, source_path))
  end

  defp objective_tradeoff_downlink_gap_events(row, source_path) do
    required_downlink_mb = objective_tradeoff_required_downlink_mb(row)
    planned_downlink_mb = objective_tradeoff_planned_downlink_mb(row)
    required_contacts = objective_tradeoff_required_contacts(row)
    planned_contacts = objective_tradeoff_planned_contacts(row)
    latency_gap? = objective_tradeoff_collection_latency_gap?(row)

    volume_gap? =
      is_number(required_downlink_mb) and required_downlink_mb > planned_downlink_mb

    contact_gap? =
      objective_tradeoff_downlink_objective?(row) and is_number(required_contacts) and
        required_contacts > planned_contacts

    if volume_gap? or contact_gap? or latency_gap? do
      [
        %{
          "type" => "downlink_completion_gap",
          "objective_id" => row["id"] || row["objective_id"],
          "objective_type" => row["objective"] || row["objective_type"],
          "latency_objective" =>
            if(objective_tradeoff_collection_latency_objective?(row), do: true),
          "target_id" => objective_tradeoff_primary_target_id(row),
          "scenario_id" => objective_pressure_scenario_id(row),
          "branch_id" => row["branch_id"],
          "ground_station_id" => objective_pressure_station_id(row),
          "collection_id" => objective_pressure_collection_id(row),
          "product_id" => objective_pressure_product_id(row),
          "product_ids" => objective_pressure_product_ids(row),
          "payload_id" => objective_pressure_payload_id(row),
          "instrument_id" => objective_pressure_instrument_id(row),
          "required_contacts" => required_contacts || 1,
          "planned_contacts" => planned_contacts,
          "required_downlink_mb" => required_downlink_mb,
          "planned_downlink_mb" => planned_downlink_mb,
          "starts_at_s" => objective_tradeoff_latency_window_start_s(row),
          "ends_at_s" => objective_tradeoff_latency_window_end_s(row),
          "max_latency_s" => objective_tradeoff_max_latency_s(row),
          "planned_latency_s" => objective_tradeoff_planned_latency_s(row),
          "source_activity_id" => objective_tradeoff_source_activity_id(row),
          "source_activity_ids" => objective_tradeoff_source_activity_ids(row),
          "score" => numeric_or_nil(row["score"]),
          "score_delta_from_selected" => numeric_or_nil(row["score_delta_from_selected"]),
          "score_terms" => row["score_terms"],
          "derivation_reasons" =>
            objective_tradeoff_downlink_reasons(row, contact_gap?, volume_gap?, latency_gap?),
          "feedback_source" => source_path,
          "feedback_scope" => "objective_tradeoff",
          "trust_boundary" => objective_tradeoff_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
  end

  defp objective_tradeoff_target_gap_events(row, source_path) do
    target_ids = objective_tradeoff_gap_target_ids(row)
    required_observations = objective_tradeoff_required_observations(row)
    planned_observations = objective_tradeoff_planned_observations(row)

    target_gap? =
      target_ids != [] and
        (objective_tradeoff_has_missed_targets?(row) or
           (is_number(required_observations) and required_observations > planned_observations))

    if target_gap? do
      Enum.map(target_ids, fn target_id ->
        target_spec = objective_tradeoff_target_spec(row, target_id)

        %{
          "type" => "urgent_target",
          "objective_id" => row["id"] || row["objective_id"],
          "objective_type" =>
            row["objective"] || row["objective_type"] || "objective_tradeoff_target_gap",
          "target_id" => target_id,
          "scenario_id" => objective_pressure_scenario_id(row),
          "branch_id" => row["branch_id"],
          "priority" => objective_tradeoff_target_priority(row, target_spec),
          "latitude_deg" => objective_tradeoff_target_number(row, target_spec, "latitude_deg"),
          "longitude_deg" => objective_tradeoff_target_number(row, target_spec, "longitude_deg"),
          "minimum_elevation_deg" =>
            objective_tradeoff_target_number(row, target_spec, "minimum_elevation_deg"),
          "required_observations" => required_observations || 1,
          "planned_observations" => planned_observations,
          "source_activity_ids" => objective_tradeoff_source_activity_ids(row),
          "score" => numeric_or_nil(row["score"]),
          "score_delta_from_selected" => numeric_or_nil(row["score_delta_from_selected"]),
          "score_terms" => row["score_terms"],
          "derivation_reason" => "objective_tradeoff_target_gap",
          "derivation_reasons" => objective_tradeoff_target_reasons(row),
          "feedback_source" => source_path,
          "feedback_scope" => "objective_tradeoff",
          "trust_boundary" => objective_tradeoff_trust_boundary(row)
        }
        |> compact_map()
      end)
    else
      []
    end
  end

  defp objective_tradeoff_required_downlink_mb(row) do
    explicit =
      [
        row["required_downlink_mb"],
        row["target_downlink_mb"],
        row["downlink_requirement_mb"],
        row["required_volume_mb"],
        row["required_data_volume_mb"],
        row["target_volume_mb"],
        row["target_data_volume_mb"],
        row["min_downlink_mb"],
        row["missing_downlink_mb"],
        objective_pressure_observation_context_number(row, [
          "required_downlink_mb",
          "target_downlink_mb",
          "downlink_requirement_mb",
          "required_volume_mb",
          "required_data_volume_mb",
          "target_volume_mb",
          "target_data_volume_mb",
          "min_downlink_mb",
          "missing_downlink_mb"
        ])
      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    explicit || objective_tradeoff_required_downlink_mb_from_score_terms(row)
  end

  defp objective_tradeoff_planned_downlink_mb(row) do
    [
      row["planned_downlink_mb"],
      row["selected_downlink_mb"],
      row["actual_downlink_mb"],
      row["planned_data_volume_mb"],
      row["selected_data_volume_mb"],
      row["actual_data_volume_mb"],
      row["delivered_data_volume_mb"],
      row["received_data_volume_mb"],
      row["planned_volume_mb"],
      row["selected_volume_mb"],
      row["actual_volume_mb"],
      objective_pressure_observation_context_number(row, [
        "planned_downlink_mb",
        "selected_downlink_mb",
        "actual_downlink_mb",
        "planned_data_volume_mb",
        "selected_data_volume_mb",
        "actual_data_volume_mb",
        "delivered_data_volume_mb",
        "received_data_volume_mb",
        "planned_volume_mb",
        "selected_volume_mb",
        "actual_volume_mb"
      ])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> value
      _value -> 0.0
    end
  end

  defp objective_tradeoff_required_contacts(row) do
    explicit =
      [
        row["required_contacts"],
        row["required_contact_count"],
        row["expected_contact_count"]
      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    explicit ||
      objective_satisfaction_contact_count(row, [
        "required_contact_ids",
        "required_contact_id",
        "required_contacts",
        "required_contact",
        "required_downlink_contact_ids",
        "required_downlink_contact_id",
        "required_downlink_contacts",
        "required_downlink_contact",
        "candidate_contact_ids",
        "candidate_contact_id",
        "candidate_contacts",
        "candidate_contact"
      ]) ||
      objective_tradeoff_required_contacts_from_score_terms(row)
  end

  defp objective_tradeoff_planned_contacts(row) do
    [
      row["planned_contacts"],
      row["selected_contact_count"],
      row["satisfied_contact_count"],
      row["planned_contact_count"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) ->
        value

      _value ->
        objective_satisfaction_contact_count(row, [
          "planned_contact_ids",
          "planned_contact_id",
          "planned_contacts",
          "planned_contact",
          "selected_contact_ids",
          "selected_contact_id",
          "selected_contacts",
          "selected_contact",
          "satisfied_contact_ids",
          "satisfied_contact_id",
          "satisfied_contacts",
          "satisfied_contact"
        ]) || 0
    end
  end

  defp objective_tradeoff_downlink_objective?(row) do
    row["objective"] in ["downlink_completion", "collection_latency"] or
      row["objective_type"] in ["downlink_completion", "collection_latency"]
  end

  defp objective_tradeoff_collection_latency_objective?(row),
    do: row["objective"] == "collection_latency" or row["objective_type"] == "collection_latency"

  defp objective_tradeoff_collection_latency_gap?(row) do
    objective_tradeoff_collection_latency_objective?(row) and
      case {objective_tradeoff_max_latency_s(row), objective_tradeoff_planned_latency_s(row)} do
        {max_latency_s, planned_latency_s}
        when is_number(max_latency_s) and is_number(planned_latency_s) ->
          planned_latency_s > max_latency_s

        {max_latency_s, nil} when is_number(max_latency_s) ->
          true

        _latency ->
          false
      end
  end

  defp objective_tradeoff_primary_target_id(row) do
    [
      row["target_id"],
      score_term_entity_id(row["target"], ["target_id", "id"]),
      objective_satisfaction_observation_context_value(row, ["target_id", "id"])
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp objective_tradeoff_max_latency_s(row),
    do:
      numeric_or_nil(
        row["max_latency_s"] || row["required_latency_s"] || row["target_latency_s"] ||
          row["latency_limit_s"] || row["max_delivery_latency_s"] ||
          row["required_delivery_latency_s"] ||
          objective_pressure_observation_context_number(row, [
            "max_latency_s",
            "required_latency_s",
            "target_latency_s",
            "latency_limit_s",
            "max_delivery_latency_s",
            "required_delivery_latency_s"
          ])
      )

  defp objective_tradeoff_planned_latency_s(row),
    do:
      numeric_or_nil(
        row["planned_latency_s"] || row["actual_latency_s"] || row["delivery_latency_s"] ||
          row["planned_delivery_latency_s"] || row["actual_delivery_latency_s"] ||
          objective_pressure_observation_context_number(row, [
            "planned_latency_s",
            "actual_latency_s",
            "delivery_latency_s",
            "planned_delivery_latency_s",
            "actual_delivery_latency_s"
          ])
      )

  defp objective_tradeoff_latency_window_start_s(row) do
    numeric_or_nil(
      row["starts_at_s"] || row["window_starts_at_s"] || row["source_activity_ends_at_s"] ||
        row["observation_ends_at_s"] || row["collection_ends_at_s"] ||
        row["collection_end_s"] ||
        objective_pressure_observation_context_number(row, [
          "source_activity_ends_at_s",
          "observation_ends_at_s",
          "collection_ends_at_s",
          "collection_end_s",
          "ends_at_s",
          "end_s"
        ])
    )
  end

  defp objective_tradeoff_latency_window_end_s(row) do
    explicit_end =
      numeric_or_nil(
        row["ends_at_s"] || row["window_ends_at_s"] || row["deadline_s"] ||
          row["delivery_deadline_s"] || row["latency_deadline_s"] ||
          objective_pressure_observation_context_number(row, [
            "deadline_s",
            "delivery_deadline_s",
            "latency_deadline_s"
          ])
      )

    start_s = objective_tradeoff_latency_window_start_s(row)
    max_latency_s = objective_tradeoff_max_latency_s(row)

    cond do
      is_number(explicit_end) ->
        explicit_end

      objective_tradeoff_collection_latency_objective?(row) and is_number(start_s) and
          is_number(max_latency_s) ->
        start_s + max_latency_s

      true ->
        nil
    end
  end

  defp objective_tradeoff_downlink_reasons(row, contact_gap?, volume_gap?, latency_gap?) do
    []
    |> maybe_append_reason(true, "objective_tradeoff_downlink_gap")
    |> maybe_append_reason(latency_gap?, "collection_latency_gap")
    |> maybe_append_reason(latency_gap?, "objective_tradeoff_latency_gap")
    |> maybe_append_reason(contact_gap?, "objective_tradeoff_contact_count_gap")
    |> maybe_append_reason(volume_gap?, "objective_tradeoff_downlink_volume_gap")
    |> maybe_append_reason(
      objective_tradeoff_score_term_downlink_gap?(row),
      "objective_tradeoff_score_term_downlink_gap"
    )
    |> maybe_append_reason(
      objective_tradeoff_score_term_contact_gap?(row),
      "objective_tradeoff_score_term_contact_gap"
    )
    |> maybe_append_reason(row["selected"] == false, "objective_tradeoff_unselected")
    |> Enum.reverse()
  end

  defp objective_tradeoff_required_observations(row) do
    explicit =
      [
        row["required_observations"],
        row["required_observation_count"],
        row["required_count"],
        row["required_revisits"],
        row["required_revisit_count"],
        row["target_required_revisit_count"],
        row["required_coverage_count"],
        row["target_required_coverage_count"]
      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    explicit ||
      objective_tradeoff_required_observations_from_direct_gap(row) ||
      objective_tradeoff_required_observations_from_score_terms(row) ||
      objective_tradeoff_required_target_count(row)
  end

  defp objective_tradeoff_planned_observations(row) do
    [
      row["planned_observations"],
      row["selected_observation_count"],
      row["planned_observation_count"],
      row["selected_count"],
      row["planned_revisits"],
      row["selected_revisits"],
      row["satisfied_revisits"],
      row["planned_revisit_count"],
      row["selected_revisit_count"],
      row["satisfied_revisit_count"],
      row["target_planned_revisit_count"],
      row["planned_coverage_count"],
      row["selected_coverage_count"],
      row["satisfied_coverage_count"],
      row["target_planned_coverage_count"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) ->
        value

      _value ->
        if objective_tradeoff_requirement_universe_target_ids(row) == [] do
          0
        else
          objective_tradeoff_selected_target_count(row) || 0
        end
    end
  end

  defp objective_tradeoff_gap_target_ids(row) do
    selected_targets =
      row
      |> objective_tradeoff_target_id_values([
        "selected_targets",
        "satisfied_targets",
        "selected_revisit_targets",
        "satisfied_revisit_targets",
        "selected_coverage_targets",
        "satisfied_coverage_targets",
        "selected_target_ids",
        "satisfied_target_ids",
        "selected_revisit_target_ids",
        "satisfied_revisit_target_ids",
        "selected_coverage_target_ids",
        "satisfied_coverage_target_ids"
      ])
      |> MapSet.new()

    row
    |> objective_tradeoff_target_id_values([
      "target_id",
      "target",
      "target_ids",
      "targets",
      "target_spec",
      "target_specs",
      "required_target",
      "required_targets",
      "committed_target",
      "committed_targets",
      "priority_target",
      "priority_targets",
      "candidate_target",
      "candidate_targets",
      "uncovered_target",
      "uncovered_targets",
      "unsatisfied_target",
      "unsatisfied_targets",
      "missing_target",
      "missing_targets",
      "missed_target",
      "missed_targets",
      "missed_observation_target",
      "missed_observation_targets",
      "revisit_target",
      "revisit_targets",
      "required_revisit_target",
      "required_revisit_targets",
      "missing_revisit_target",
      "missing_revisit_targets",
      "coverage_target",
      "coverage_targets",
      "required_coverage_target",
      "required_coverage_targets",
      "missing_coverage_target",
      "missing_coverage_targets",
      "target_gap_target",
      "target_gap_targets",
      "missed_target_ids",
      "missed_observation_target_ids",
      "required_target_ids",
      "candidate_target_ids",
      "uncovered_target_ids",
      "unsatisfied_target_ids",
      "missing_target_ids",
      "revisit_target_ids",
      "required_revisit_target_ids",
      "missing_revisit_target_ids",
      "coverage_target_ids",
      "required_coverage_target_ids",
      "missing_coverage_target_ids",
      "target_gap_ids"
    ])
    |> Kernel.++(objective_pressure_gap_context_target_ids(row))
    |> Enum.reject(&MapSet.member?(selected_targets, &1))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp objective_tradeoff_has_missed_targets?(row) do
    row
    |> objective_tradeoff_target_id_values([
      "missed_target",
      "missed_targets",
      "missed_observation_target",
      "missed_observation_targets",
      "missed_target_ids",
      "missed_observation_target_ids"
    ])
    |> Enum.any?()
  end

  defp objective_tradeoff_required_target_count(row) do
    row
    |> objective_tradeoff_target_id_values([
      "required_target",
      "required_targets",
      "committed_target",
      "committed_targets",
      "priority_target",
      "priority_targets",
      "candidate_target",
      "candidate_targets",
      "uncovered_target",
      "uncovered_targets",
      "unsatisfied_target",
      "unsatisfied_targets",
      "missing_target",
      "missing_targets",
      "missed_target",
      "missed_targets",
      "missed_observation_target",
      "missed_observation_targets",
      "revisit_target",
      "revisit_targets",
      "required_revisit_target",
      "required_revisit_targets",
      "missing_revisit_target",
      "missing_revisit_targets",
      "coverage_target",
      "coverage_targets",
      "required_coverage_target",
      "required_coverage_targets",
      "missing_coverage_target",
      "missing_coverage_targets",
      "target_gap_target",
