    ])
    |> target_count_or_nil()
  end

  defp objective_tradeoff_requirement_universe_target_ids(row) do
    objective_tradeoff_target_id_values(row, [
      "required_target",
      "required_targets",
      "committed_target",
      "committed_targets",
      "priority_target",
      "priority_targets",
      "candidate_target",
      "candidate_targets",
      "revisit_target",
      "revisit_targets",
      "required_revisit_target",
