  defp timeline_diff_pressure_branch(row, source_path, index, policy \\ %{}) do
    row = normalize_timeline_diff_pressure_row(row)

    row
    |> timeline_diff_pressure_events(source_path, policy)
    |> Enum.map(fn event ->
      status = row["diff_status"] || "review"

      identity =
        row["source_activity_id"] || row["timeline_id"] || event["target_id"] || event["type"] ||
          index

      %{
        "id" =>
          "derived_timeline_diff_#{branch_id_fragment(status)}_#{branch_id_fragment(identity)}",
        "label" => "Derived timeline diff #{status} #{identity}",
        "events" => [event],
        "metadata" =>
          %{
            "derived_source" => source_path,
            "timeline_id" => row["timeline_id"],
            "diff_status" => row["diff_status"],
            "application_status" => row["application_status"],
            "selected_activity_source" => row["selected_activity_source"]
          }
          |> compact_map()
      }
    end)
  end

