  defp disambiguate_review_replay_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if review_replay_pressure_branch_id?(branch_id) and Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> review_replay_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("review_replay_branch_base_id", branch_id)
          |> Map.put("review_replay_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_review_replay_suffixes()
  end

  defp review_replay_pressure_branch_id?(id) when is_binary(id) do
    Enum.any?(
      [
        "derived_operational_timeline_feedback_",
        "derived_candidate_diff_replacement_",
        "derived_candidate_rejection_pressure_",
        "derived_provider_counteroffer_pressure_",
        "derived_schema_validation_pressure_",
        "derived_operational_readiness_pressure_",
        "derived_quality_gate_pressure_",
        "derived_model_acceptance_pressure_",
        "derived_validation_safety_case_pressure_",
        "derived_refresh_budget_pressure_",
        "derived_refresh_freshness_pressure_",
        "derived_command_window_feedback_",
        "derived_maneuver_review_feedback_",
        "derived_realized_feedback_",
        "derived_contact_intent_pressure_",
        "derived_station_calendar_pressure_",
        "derived_station_calendar_provider_contention_"
      ],
      &String.starts_with?(id, &1)
    )
  end

  defp review_replay_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_review_replay_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "review_replay_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["review_replay_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["review_replay_branch_base_id"]}_#{suffix}")
        |> Map.update("metadata", %{}, &Map.put(&1, "review_replay_branch_identity", suffix))
      else
        branch
      end
    end)
  end

  defp review_replay_pressure_branch_identity(branch, index) do
    metadata = Map.get(branch, "metadata", %{})

    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        metadata["derived_source"],
        event["feedback_source"],
        event["feedback_scope"],
        event["feedback_key"],
        event["derivation_reasons"],
        event["trust_boundary"],
        event["activity_id"],
        event["maneuver_id"],
        event["timeline_id"],
        event["replacement_candidate_id"],
        event["invalidated_candidate_id"],
        event["freshness_status"],
        event["relaxed_max_candidate_activities"],
        event["station_calendar_entry_id"],
        event["station_calendar_provider_id"],
        event["station_calendar_provider_entry_id"],
        event["station_calendar_status"],
        event["station_availability"],
        event["station_reservation_id"],
        event["station_reserved_by"],
        event["station_reservation_status"],
        event["station_reservation_match_status"],
        event["provider_calendar_contention_group_id"],
        event["provider_calendar_contention_status"],
        event["ground_station_id"],
        event["target_id"],
        event["direction"],
        event["starts_at_s"],
        event["ends_at_s"],
        event["contact_success_factor"],
        event["station_throughput_factor"],
        event["observation_success_factor"],
        event["command_success_factor"],
        event["maneuver_success_factor"],
        event["cadence_import_status"],
        event["required_operator_action"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp normalize_timeline_diff_pressure_row(row) do
    row
    |> normalize_timeline_diff_pressure_field("diff_status")
    |> normalize_timeline_diff_pressure_field("source_status")
    |> normalize_timeline_diff_pressure_field("replacement_status")
    |> normalize_timeline_diff_pressure_field("source_activity_type")
    |> normalize_timeline_diff_pressure_field("replacement_activity_type")
    |> normalize_timeline_diff_pressure_field("source_direction")
    |> normalize_timeline_diff_pressure_field("replacement_direction")
    |> normalize_timeline_diff_changed_fields()
    |> normalize_timeline_diff_activity_context("source_activity_context")
    |> normalize_timeline_diff_activity_context("replacement_activity_context")
  end

  defp normalize_timeline_diff_pressure_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, normalized_status_token(value))
    end
  end

  defp normalize_timeline_diff_changed_fields(%{"changed_fields" => fields} = row)
       when is_list(fields) do
    fields =
      fields
      |> Enum.map(&normalized_status_token/1)
      |> Enum.reject(&(&1 in [nil, ""]))

    Map.put(row, "changed_fields", fields)
  end

  defp normalize_timeline_diff_changed_fields(row), do: row

  defp normalize_timeline_diff_activity_context(row, field) do
    case Map.get(row, field) do
      %{} = context ->
        context =
          context
          |> stringify_keys()
          |> normalize_timeline_diff_pressure_field("type")
          |> normalize_timeline_diff_pressure_field("activity_type")
          |> normalize_timeline_diff_pressure_field("direction")
          |> normalize_timeline_diff_pressure_field("status")

        Map.put(row, field, context)

      _context ->
        row
    end
  end

  defp timeline_diff_pressure_events(row, source_path, policy) do
    events =
      cond do
        timeline_diff_removed_pressure_row?(row) ->
          row
          |> timeline_diff_removed_activity_type()
          |> case do
            "observe" ->
              [timeline_diff_removed_observation_event(row, source_path)]

            type
            when type in [
                   "downlink",
                   "tracking",
                   "command",
                   "health_check",
                   "maneuver",
                   "impulsive_burn",
                   "planned_contact",
                   "contact"
                 ] ->
              cond do
                timeline_diff_removed_downlink?(row) ->
                  [timeline_diff_removed_downlink_event(row, source_path)]

                timeline_diff_removed_command?(row) ->
                  [timeline_diff_removed_command_event(row, source_path)]

                timeline_diff_removed_contact?(row) ->
                  [timeline_diff_removed_contact_event(row, source_path)]

                timeline_diff_removed_maneuver?(row) ->
                  [timeline_diff_removed_maneuver_event(row, source_path)]

                true ->
                  []
              end

            _type ->
              []
          end

        timeline_diff_changed_downlink_pressure_row?(row) ->
          [timeline_diff_changed_downlink_event(row, source_path)] ++
            timeline_diff_changed_contact_identity_events(row, source_path) ++
            timeline_diff_changed_resource_identity_events(row, source_path) ++
            timeline_diff_changed_station_throughput_events(row, source_path, policy) ++
            timeline_diff_changed_link_quality_events(row, source_path) ++
            timeline_diff_changed_collection_latency_events(row, source_path) ++
            timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
            timeline_diff_changed_resource_availability_events(row, source_path)

        timeline_diff_changed_contact_pressure_row?(row) ->
          [timeline_diff_changed_contact_event(row, source_path)] ++
            timeline_diff_changed_contact_identity_events(row, source_path) ++
            timeline_diff_changed_resource_identity_events(row, source_path) ++
            timeline_diff_changed_station_throughput_events(row, source_path, policy) ++
            timeline_diff_changed_link_quality_events(row, source_path) ++
            timeline_diff_changed_collection_latency_events(row, source_path) ++
            timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
            timeline_diff_changed_resource_availability_events(row, source_path)

        timeline_diff_changed_observation_pressure_row?(row, policy) ->
          timeline_diff_changed_observation_events(row, source_path, policy) ++
            timeline_diff_changed_resource_identity_events(row, source_path) ++
            timeline_diff_changed_collection_latency_events(row, source_path) ++
            timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
            timeline_diff_changed_resource_availability_events(row, source_path)

        timeline_diff_changed_command_pressure_row?(row) ->
          [timeline_diff_changed_command_event(row, source_path)] ++
            timeline_diff_changed_command_identity_events(row, source_path) ++
            timeline_diff_changed_resource_identity_events(row, source_path) ++
            timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
            timeline_diff_changed_resource_availability_events(row, source_path)

        timeline_diff_changed_maneuver_pressure_row?(row) ->
          timeline_diff_changed_maneuver_events(row, source_path) ++
            timeline_diff_changed_resource_identity_events(row, source_path) ++
            timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
            timeline_diff_changed_resource_availability_events(row, source_path)

        timeline_diff_changed_resource_margin_pressure_row?(row, policy) ->
          timeline_diff_changed_resource_margin_events(row, source_path, policy)

        timeline_diff_changed_resource_availability_pressure_row?(row) ->
          timeline_diff_changed_resource_availability_events(row, source_path)

        timeline_diff_changed_command_identity_pressure_row?(row) ->
          timeline_diff_changed_command_identity_events(row, source_path) ++
            timeline_diff_changed_resource_identity_events(row, source_path)

        timeline_diff_changed_resource_identity_pressure_row?(row) ->
          timeline_diff_changed_resource_identity_events(row, source_path)

        timeline_diff_changed_station_throughput_pressure_row?(row, policy) ->
          timeline_diff_changed_station_throughput_events(row, source_path, policy)

        timeline_diff_changed_link_quality_pressure_row?(row) ->
          timeline_diff_changed_link_quality_events(row, source_path)

        timeline_diff_changed_contact_identity_pressure_row?(row) ->
          timeline_diff_changed_contact_identity_events(row, source_path)

        timeline_diff_changed_collection_latency_pressure_row?(row) ->
          timeline_diff_changed_collection_latency_events(row, source_path)

        true ->
          []
      end

    (events ++ timeline_transition_application_pressure_events(row, source_path))
    |> Enum.map(&Map.merge(&1, timeline_diff_application_context(row)))
    |> Enum.map(&compact_map/1)
  end

  defp timeline_transition_application_pressure_events(row, source_path) do
    TimelineDiffPressureEvents.timeline_transition_application_pressure_events(
      row,
      source_path,
      timeline_diff_pressure_event_callbacks()
    )
  end

  defp timeline_diff_application_context(row) do
    %{
      "approval_status" => row["approval_status"],
      "application_status" => row["application_status"],
      "selected_activity_source" => row["selected_activity_source"],
      "selected_activity" => row["selected_activity"],
      "source_timeline_application" => row["source_timeline_application"],
      "timeline_identity_collision" => row["timeline_identity_collision"],
      "duplicate_timeline_identity_scope" => row["duplicate_timeline_identity_scope"],
      "source_duplicate_activity_count" => row["source_duplicate_activity_count"],
      "replacement_duplicate_activity_count" => row["replacement_duplicate_activity_count"],
      "source_duplicate_activity_ids" => row["source_duplicate_activity_ids"],
      "replacement_duplicate_activity_ids" => row["replacement_duplicate_activity_ids"],
      "source_duplicate_activities" => row["source_duplicate_activities"],
      "replacement_duplicate_activities" => row["replacement_duplicate_activities"],
      "policy_classification" => row["policy_classification"],
      "policy_bundle_id" => row["policy_bundle_id"],
      "source_policy_decision" => row["source_policy_decision"],
      "approval_requirements" => row["approval_requirements"],
      "approval_rule_matches" => row["approval_rule_matches"]
    }
    |> compact_map()
  end

  defp timeline_diff_removed_pressure_row?(row) do
    row["diff_status"] == "removed" and row["source_status"] not in @realized_completion_statuses
  end

  defp timeline_diff_removed_activity_type(row) do
    row["source_activity_type"] ||
      get_in(row, ["source_activity_context", "activity_type"]) ||
      get_in(row, ["source_activity_context", "type"])
  end

  defp timeline_diff_removed_downlink?(row) do
    type = timeline_diff_removed_activity_type(row)
    direction = row["source_direction"] || get_in(row, ["source_activity_context", "direction"])

    type == "downlink" or (type in ["planned_contact", "contact"] and direction == "downlink")
  end

  defp timeline_diff_removed_contact?(row) do
    type = timeline_diff_removed_activity_type(row)
    direction = row["source_direction"] || get_in(row, ["source_activity_context", "direction"])

    type == "tracking" or (type in ["planned_contact", "contact"] and direction == "tracking")
  end

  defp timeline_diff_removed_command?(row) do
    type = timeline_diff_removed_activity_type(row)
    direction = row["source_direction"] || get_in(row, ["source_activity_context", "direction"])

    type in ["command", "health_check"] or
      (type in ["planned_contact", "contact"] and
         direction in ["command", "uplink", "health_check"])
  end

  defp timeline_diff_removed_maneuver?(row) do
    type = timeline_diff_removed_activity_type(row)

    operational_kind =
      row["source_operational_kind"] ||
        get_in(row, ["source_activity_context", "operational_kind"])

    type in ["maneuver", "impulsive_burn"] or operational_kind == "maneuver"
  end

  defp timeline_diff_changed_resource_margin_pressure_row?(row, policy) do
    TimelineDiffPressureEvents.timeline_diff_changed_resource_margin_pressure_row?(
      row,
      policy,
      timeline_diff_pressure_event_callbacks()
    )
  end

  defp timeline_diff_changed_resource_margin_events(row, source_path, policy) do
    TimelineDiffPressureEvents.timeline_diff_changed_resource_margin_events(
      row,
      source_path,
      policy,
      timeline_diff_pressure_event_callbacks()
    )
  end

  defp timeline_diff_changed_resource_availability_pressure_row?(row) do
    TimelineDiffPressureEvents.timeline_diff_changed_resource_availability_pressure_row?(
      row,
      timeline_diff_pressure_event_callbacks()
    )
  end

  defp timeline_diff_changed_resource_availability_events(row, source_path) do
    TimelineDiffPressureEvents.timeline_diff_changed_resource_availability_events(
      row,
      source_path,
      timeline_diff_pressure_event_callbacks()
    )
  end

  defp timeline_diff_changed_resource_identity_pressure_row?(row) do
    TimelineDiffPressureEvents.timeline_diff_changed_resource_identity_pressure_row?(
      row,
      timeline_diff_pressure_event_callbacks()
    )
  end

  defp timeline_diff_changed_resource_identity_events(row, source_path) do
    TimelineDiffPressureEvents.timeline_diff_changed_resource_identity_events(
      row,
      source_path,
      timeline_diff_pressure_event_callbacks()
    )
  end

  defp timeline_diff_removed_observation_event(row, source_path) do
    %{
      "type" => "urgent_target",
      "objective_type" => "target_revisit",
      "target_id" => timeline_diff_removed_target_id(row),
      "scenario_id" =>
        row["scenario_id"] || get_in(row, ["source_activity_context", "scenario_id"]),
      "required_observations" => 1,
      "planned_observations" => 0,
      "source_activity_id" => row["source_activity_id"],
      "source_activity_ids" => timeline_diff_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "required_operator_action" => row["required_operator_action"],
      "derivation_reason" => "timeline_diff_removed_observation",
      "derivation_reasons" => [
        "timeline_diff_removed_activity",
        "timeline_diff_removed_observation"
      ],
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
  end

  defp timeline_diff_removed_downlink_event(row, source_path) do
    %{
      "type" => "downlink_completion_gap",
      "scenario_id" =>
        row["scenario_id"] || get_in(row, ["source_activity_context", "scenario_id"]),
      "ground_station_id" => timeline_diff_removed_ground_station_id(row),
      "starts_at_s" => timeline_diff_removed_window_start_s(row),
      "ends_at_s" => timeline_diff_removed_window_end_s(row),
      "required_contacts" => timeline_diff_removed_required_contacts(row),
      "planned_contacts" => timeline_diff_removed_planned_contacts(row),
      "required_downlink_mb" => timeline_diff_removed_downlink_mb(row),
      "planned_downlink_mb" => 0.0,
      "source_activity_id" => row["source_activity_id"],
      "source_activity_ids" => timeline_diff_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "required_operator_action" => row["required_operator_action"],
      "derivation_reasons" => [
        "timeline_diff_removed_activity",
        "timeline_diff_removed_downlink"
      ],
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
  end

  defp timeline_diff_removed_contact_event(row, source_path) do
    %{
      "type" => "contact_success_feedback",
      "scenario_id" =>
        row["scenario_id"] || get_in(row, ["source_activity_context", "scenario_id"]),
      "ground_station_id" => timeline_diff_removed_ground_station_id(row),
      "starts_at_s" => timeline_diff_removed_window_start_s(row),
      "ends_at_s" => timeline_diff_removed_window_end_s(row),
      "contact_success_factor" => 0.0,
      "contact_result" => timeline_diff_removed_contact_result(row),
      "realized_status" => "missed",
      "source_activity_id" => row["source_activity_id"],
      "source_activity_ids" => timeline_diff_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "required_operator_action" => row["required_operator_action"],
      "derivation_reasons" => [
        "timeline_diff_removed_activity",
        "timeline_diff_removed_contact"
      ],
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" => timeline_diff_removed_ground_station_id(row),
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
  end

  defp timeline_diff_removed_contact_result(row) do
    [
      row["source_contact_result"],
      row["contact_result"],
      get_in(row, ["source_activity_context", "contact_result"])
    ]
    |> Enum.map(&provider_result_artifact_value/1)
    |> Enum.find(&provider_result_artifact_string?/1)
  end

  defp timeline_diff_removed_command_event(row, source_path) do
    %{
      "type" => "command_success_feedback",
      "activity_id" => row["source_activity_id"],
      "scenario_id" =>
        row["scenario_id"] || get_in(row, ["source_activity_context", "scenario_id"]),
      "starts_at_s" => timeline_diff_removed_window_start_s(row),
      "ends_at_s" => timeline_diff_removed_window_end_s(row),
      "command_success_factor" => 0.0,
      "command_result" => timeline_diff_removed_command_result(row),
      "realized_status" => "missed",
      "source_activity_id" => row["source_activity_id"],
      "source_activity_ids" => timeline_diff_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "required_operator_action" => row["required_operator_action"],
      "derivation_reasons" => [
        "timeline_diff_removed_activity",
        "timeline_diff_removed_command"
      ],
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" => row["source_activity_id"],
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
  end

  defp timeline_diff_removed_command_result(row) do
    [
      row["source_command_result"],
      row["command_result"],
      get_in(row, ["source_activity_context", "command_result"])
    ]
    |> Enum.map(&provider_result_artifact_value/1)
    |> Enum.find(&provider_result_artifact_string?/1)
  end

  defp timeline_diff_removed_maneuver_event(row, source_path) do
    %{
      "type" => "maneuver_success_feedback",
      "activity_id" => row["source_activity_id"],
      "scenario_id" =>
        row["scenario_id"] || get_in(row, ["source_activity_context", "scenario_id"]),
      "starts_at_s" => timeline_diff_removed_window_start_s(row),
      "ends_at_s" => timeline_diff_removed_window_end_s(row),
      "maneuver_success_factor" => 0.0,
      "maneuver_result" => timeline_diff_removed_maneuver_result(row),
      "realized_status" => "missed",
      "source_activity_id" => row["source_activity_id"],
      "source_activity_ids" => timeline_diff_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "required_operator_action" => row["required_operator_action"],
      "derivation_reasons" => [
        "timeline_diff_removed_activity",
        "timeline_diff_removed_maneuver"
      ],
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" => row["source_activity_id"],
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
  end

  defp timeline_diff_removed_maneuver_result(row) do
    [
      row["source_maneuver_result"],
      row["maneuver_result"],
      get_in(row, ["source_activity_context", "maneuver_result"])
    ]
    |> Enum.map(&provider_result_artifact_value/1)
    |> Enum.find(&provider_result_artifact_string?/1)
  end

  defp timeline_diff_removed_downlink_mb(row) do
    [
      row["source_estimated_throughput_mb"],
      row["required_downlink_mb"],
      get_in(row, ["source_activity_context", "estimated_throughput_mb"]),
      get_in(row, ["source_activity_context", "planned_estimated_throughput_mb"]),
      get_in(row, ["source_activity_context", "throughput_model", "required_downlink_mb"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
  end

  defp timeline_diff_removed_target_id(row) do
    source_context = Map.get(row, "source_activity_context", %{})

    [
      row["source_target_id"],
      score_term_entity_id(row["source_target"], ["target_id", "id"]),
      get_in(row, ["source_activity_context", "target_id"]),
      score_term_entity_id(source_context["target"], ["target_id", "id"])
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp timeline_diff_removed_ground_station_id(row) do
    source_context = Map.get(row, "source_activity_context", %{})

    [
      row["source_ground_station_id"],
      score_term_entity_id(row["source_ground_station"], [
        "ground_station_id",
        "station_id",
        "id"
      ]),
      get_in(row, ["source_activity_context", "ground_station_id"]),
      get_in(row, ["source_activity_context", "station_id"]),
      score_term_entity_id(source_context["ground_station"], [
        "ground_station_id",
        "station_id",
        "id"
      ]),
      score_term_entity_id(source_context["station"], ["ground_station_id", "station_id", "id"])
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp timeline_diff_removed_window_start_s(row) do
    [
      row["source_starts_at_s"],
      row["starts_at_s"],
      row["start_s"],
      get_in(row, ["source_activity_context", "starts_at_s"]),
      get_in(row, ["source_activity_context", "start_s"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
  end

  defp timeline_diff_removed_window_end_s(row) do
    [
      row["source_ends_at_s"],
      row["ends_at_s"],
      row["end_s"],
      get_in(row, ["source_activity_context", "ends_at_s"]),
      get_in(row, ["source_activity_context", "end_s"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
  end

  defp timeline_diff_removed_required_contacts(row) do
    [
      row["required_contacts"],
      row["required_contact_count"],
      get_in(row, ["source_activity_context", "required_contacts"]),
      get_in(row, ["source_activity_context", "required_contact_count"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> value
      _value -> 1
    end
  end

  defp timeline_diff_removed_planned_contacts(row) do
    [
      row["planned_contacts"],
      row["planned_contact_count"],
      get_in(row, ["source_activity_context", "planned_contacts"]),
      get_in(row, ["source_activity_context", "planned_contact_count"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> value
      _value -> 0
    end
  end

  defp timeline_diff_changed_downlink_pressure_row?(row) do
    row["diff_status"] == "changed" and timeline_diff_changed_downlink?(row) and
      timeline_diff_changed_downlink_gap?(row)
  end

  defp timeline_diff_changed_downlink?(row) do
    type =
      row["replacement_activity_type"] || row["source_activity_type"] ||
        get_in(row, ["replacement_activity_context", "activity_type"]) ||
        get_in(row, ["replacement_activity_context", "type"]) ||
        get_in(row, ["source_activity_context", "activity_type"]) ||
        get_in(row, ["source_activity_context", "type"])

    direction =
      row["replacement_direction"] || row["source_direction"] ||
        get_in(row, ["replacement_activity_context", "direction"]) ||
        get_in(row, ["source_activity_context", "direction"])

    type == "downlink" or (type in ["planned_contact", "contact"] and direction == "downlink")
  end

  defp timeline_diff_changed_downlink_gap?(row) do
    planned = timeline_diff_changed_planned_downlink_mb(row)
    required = timeline_diff_changed_required_downlink_mb(row)
    shortfall = timeline_diff_changed_downlink_shortfall_mb(row)

    positive_number?(shortfall) or
      (is_number(required) and is_number(planned) and planned < required)
  end

  defp timeline_diff_changed_downlink_event(row, source_path) do
    planned_downlink_mb = timeline_diff_changed_planned_downlink_mb(row)
    required_downlink_mb = timeline_diff_changed_required_downlink_mb(row)
    shortfall = timeline_diff_changed_downlink_shortfall_mb(row)

    required_downlink_mb =
      case {required_downlink_mb, planned_downlink_mb, shortfall} do
        {value, _planned, _shortfall} when is_number(value) ->
          value

        {_required, planned, value} when is_number(planned) and is_number(value) ->
          planned + value

        {_required, _planned, value} ->
          value
      end

    %{
      "type" => "downlink_completion_gap",
      "scenario_id" => timeline_diff_changed_scenario_id(row),
      "ground_station_id" => timeline_diff_changed_ground_station_id(row),
      "starts_at_s" => timeline_diff_changed_window_start_s(row),
      "ends_at_s" => timeline_diff_changed_window_end_s(row),
      "required_contacts" => timeline_diff_changed_required_contacts(row),
      "planned_contacts" => timeline_diff_changed_planned_contacts(row),
      "required_downlink_mb" => required_downlink_mb,
      "planned_downlink_mb" => planned_downlink_mb,
      "downlink_shortfall_mb" => shortfall,
      "downlink_demand_sources" => timeline_diff_changed_downlink_demand_sources(row),
      "downlink_completion_sources" => timeline_diff_changed_downlink_completion_sources(row),
      "source_activity_id" => row["source_activity_id"],
      "replacement_activity_id" => row["replacement_activity_id"],
      "source_activity_ids" => timeline_diff_changed_source_activity_ids(row),
