  defp cadence_import_pressure_branches(
         row,
         index,
         policy,
         source_prefix
       ) do
    source_review_row =
      case Map.get(row, "source_review_row") do
        %{} = source ->
          source
          |> stringify_keys()
          |> Map.put_new("approval_status", row["approval_status"])
          |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))

        _source ->
          %{}
      end

    source_review_branches =
      if source_review_row == %{} do
        []
      else
        operator_review_pressure_branches(
          source_review_row,
          index,
          policy,
          "#{source_prefix}.source_review_row"
        )
      end

    if source_review_branches != [] do
      source_review_branches
    else
      cadence_import_direct_pressure_branches(
        row,
        source_review_row,
        index,
        policy,
        source_prefix
      )
    end
  end

  defp cadence_import_direct_pressure_branches(
         row,
         source_review_row,
         index,
         policy,
         source_prefix
       ) do
    cond do
      is_map(timeline_application_source(row)) ->
        row
        |> timeline_application_source()
        |> timeline_transition_application_pressure_row()
        |> timeline_diff_review_row(row)
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> timeline_diff_pressure_branch(
          "#{source_prefix}.#{timeline_application_source_suffix(row)}",
          index
        )

      is_map(timeline_application_source(source_review_row)) ->
        source_review_row
        |> timeline_application_source()
        |> timeline_transition_application_pressure_row()
        |> timeline_diff_review_row(source_review_row)
        |> Map.put_new(
          "approval_status",
          row["approval_status"] || source_review_row["approval_status"]
        )
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> timeline_diff_pressure_branch(
          "#{source_prefix}.source_review_row.#{timeline_application_source_suffix(source_review_row)}",
          index
        )

      is_map(row["source_timeline_diff"]) ->
        row["source_timeline_diff"]
        |> stringify_keys()
        |> timeline_diff_review_row(row)
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> timeline_diff_pressure_branch(
          "#{source_prefix}.source_timeline_diff",
          index
        )

      is_map(source_review_row["source_timeline_diff"]) ->
        source_review_row["source_timeline_diff"]
        |> stringify_keys()
        |> timeline_diff_review_row(source_review_row)
        |> Map.put_new(
          "approval_status",
          row["approval_status"] || source_review_row["approval_status"]
        )
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> timeline_diff_pressure_branch(
          "#{source_prefix}.source_review_row.source_timeline_diff",
          index
        )

      timeline_diff_review_row?(row) ->
        row
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> timeline_diff_pressure_branch(
          "#{source_prefix}.timeline_diff_review",
          index
        )

      is_map(row["source_operational_timeline"]) ->
        row
        |> operational_timeline_review_source()
        |> elem(0)
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> operational_timeline_review_pressure_branch(
          "#{source_prefix}.source_operational_timeline",
