        |> Map.put_new("source_report", "cadence_import_manifest")
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> link_capacity_pressure_branch("#{source_prefix}.source_link_capacity")

      link_capacity_review_row?(row) ->
        row
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
