        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_allocation_pressure_branch("#{source_prefix}.contact_allocation_review")

      is_map(row["source_contact_allocation_capacity_pack"]) ->
        row
        |> contact_allocation_capacity_pack_review_source()
        |> elem(0)
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_allocation_capacity_pack_pressure_branches(
