        )

      contact_allocation_capacity_pack_review_row?(row) ->
        row
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_allocation_capacity_pack_pressure_branches(
          "#{source_prefix}.contact_allocation_capacity_pack_review"
        )

      is_map(row["source_contact_intent"]) ->
        row
        |> contact_intent_review_source()
        |> elem(0)
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_intent_pressure_branch("#{source_prefix}.source_contact_intent")

      contact_intent_review_row?(row) ->
        row
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_intent_pressure_branch("#{source_prefix}.contact_intent_review")

      is_map(row["source_station_calendar_review"]) ->
        station_calendar_review_pressure_branches(
          row,
          cadence_import_trust_boundary(row),
          source_prefix
        )

      is_map(row["source_station_calendar_provider_contention"]) ->
        station_calendar_review_pressure_branches(
          row,
          cadence_import_trust_boundary(row),
          source_prefix
        )

      station_calendar_review_row?(row) ->
        station_calendar_review_pressure_branches(
          row,
          cadence_import_trust_boundary(row),
          source_prefix
        )

      is_map(row["source_recommendation"]) ->
        row["source_recommendation"]
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put_new("review_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_contention_resolution_pressure_branches(
          "#{source_prefix}.source_recommendation"
        )

      contact_contention_recommendation_row?(row) ->
        row
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put_new("review_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_contention_resolution_pressure_branches(
          "#{source_prefix}.contact_contention_recommendation"
        )

      is_map(row["source_contact_suppression"]) ->
        row["source_contact_suppression"]
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_filter_pressure_branch("#{source_prefix}.source_contact_suppression")

      contact_suppression_review_row?(row) ->
        row
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> contact_filter_pressure_branch("#{source_prefix}.contact_suppression")

      is_map(row["source_resource_suppression"]) ->
        row["source_resource_suppression"]
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> resource_filter_pressure_branch("#{source_prefix}.source_resource_suppression")

      resource_suppression_review_row?(row) ->
        row
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> resource_filter_pressure_branch("#{source_prefix}.resource_suppression")

      is_map(row["source_objective_satisfaction"]) ->
        row["source_objective_satisfaction"]
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> objective_satisfaction_pressure_branch(
          "#{source_prefix}.source_objective_satisfaction",
          index
        )

      objective_satisfaction_review_row?(row) ->
        row
        |> flattened_objective_satisfaction_row()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> objective_satisfaction_pressure_branch(
          "#{source_prefix}.objective_satisfaction_review",
