        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
        |> objective_tradeoff_pressure_branch(
          "#{source_prefix}.source_objective_tradeoff",
          index
        )

      objective_tradeoff_review_row?(row) ->
        row
        |> stringify_keys()
        |> Map.put_new("approval_status", row["approval_status"])
        |> Map.put("_source_report_trust_boundary", cadence_import_trust_boundary(row))
