  end

  defp cadence_import_trust_boundary(row, fallback \\ nil) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_review_row", "trust_boundary"]) ||
      get_in(row, ["source_review_row", "provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"] ||
      fallback
  end

  defp contact_contention_recommendation_source(%{"source_recommendation" => %{} = source})
       when map_size(source) > 0,
       do: {source, "source_recommendation"}

  defp contact_contention_recommendation_source(row),
    do: {row, "contact_contention_recommendation"}

  defp contact_contention_recommendation_row?(row) do
    (row["source_review_type"] == "contact_contention_recommendation" or
       row["review_type"] == "contact_contention_recommendation" or
       row["import_action"] == "review_contact_contention_resolution") and
      row["deferred_contact_ids"] not in [nil, []]
  end

  defp timeline_diff_review_source(%{} = row) do
    case timeline_application_source(row) do
      %{} = source when map_size(source) > 0 ->
        {source
         |> timeline_transition_application_pressure_row()
         |> timeline_diff_review_row(row), timeline_application_source_suffix(row)}

      _source ->
        timeline_diff_source_review_source(row)
    end
  end

  defp timeline_diff_source_review_source(%{"source_timeline_diff" => %{} = source} = row)
       when map_size(source) > 0,
       do: {source |> stringify_keys() |> timeline_diff_review_row(row), "source_timeline_diff"}

  defp timeline_diff_source_review_source(row),
    do: {row |> stringify_keys() |> timeline_diff_review_row(row), "timeline_diff_review"}

  defp timeline_application_source(row) do
    cond do
      is_map(row["source_timeline_application"]) ->
        row["source_timeline_application"]

      is_map(row["source_timeline_transition_application"]) ->
        row["source_timeline_transition_application"]

      true ->
        nil
    end
  end

  defp timeline_application_source_suffix(row) do
    if is_map(row["source_timeline_application"]) do
      "source_timeline_application"
    else
      "source_timeline_transition_application"
    end
  end

  defp timeline_diff_review_row(source, row) do
    [
      "approval_status",
      "application_status",
      "selected_activity_source",
      "selected_activity",
      "policy_classification",
      "policy_bundle_id",
      "source_policy_decision",
      "approval_requirements",
      "approval_rule_matches",
      "required_operator_action",
      "trust_boundary",
      "provenance"
    ]
    |> Enum.reduce(stringify_keys(source), fn field, acc ->
      put_default_if_present(acc, field, row[field])
    end)
    |> put_default_if_present("source_policy_decision", row["policy_decision"])
  end

  defp operational_timeline_review_source(%{"source_operational_timeline" => %{} = source} = row)
       when map_size(source) > 0,
       do: {operator_review_operational_timeline_row(row), "source_operational_timeline"}

  defp operational_timeline_review_source(row),
    do: {operator_review_operational_timeline_row(row), "operational_timeline_review"}

  defp operational_timeline_review_row?(row) do
    (row["source_review_type"] == "operational_timeline_review" or
       row["review_type"] == "operational_timeline_review" or
       row["import_action"] == "review_operational_timeline") and
      operational_timeline_review_pressure_events(
        operator_review_operational_timeline_row(row),
        "candidate"
      ) != []
  end

  defp operational_timeline_review_pressure_branch(row, source_path, index) do
    case operational_timeline_review_pressure_events(row, source_path) do
      [] ->
        []

      events ->
        [
          %{
            "id" => operational_timeline_review_pressure_branch_id(row, index),
            "label" =>
              "Derived operational-timeline feedback #{operational_timeline_review_pressure_identity(row, index)}",
            "events" => events,
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp operational_timeline_review_pressure_events(row, source_path) do
    cond do
      not operator_review_feedback_row_usable?(row) ->
        []

      operator_review_command_feedback_row?(row) ->
        row
        |> command_window_pressure_event(source_path)
        |> operational_timeline_feedback_event("operational_timeline_command_feedback")

      operator_review_maneuver_feedback_row?(row) ->
        row
        |> operational_timeline_maneuver_feedback_events(source_path)

      operator_review_contact_feedback_row?(row) ->
        [
          row
          |> operational_timeline_contact_success_feedback_event(source_path)
          |> operational_timeline_feedback_event("operational_timeline_contact_feedback"),
          row
          |> realized_station_throughput_feedback_event(source_path)
          |> operational_timeline_feedback_event("operational_timeline_contact_throughput")
        ]

      operator_review_observation_feedback_row?(row) ->
        row
        |> operational_timeline_observation_feedback_event(source_path)
        |> operational_timeline_feedback_event("operational_timeline_observation_feedback")

      true ->
        []
    end
    |> List.wrap()
    |> Kernel.++([
      row
      |> operational_timeline_integrity_feedback_event(source_path)
      |> operational_timeline_feedback_event("operational_timeline_integrity_feedback")
    ])
    |> Enum.reject(&is_nil/1)
    |> Enum.map(&Map.merge(&1, operational_timeline_activity_integrity_context(row)))
  end

  defp operational_timeline_maneuver_feedback_events(row, source_path) do
    [
      row
      |> maneuver_review_pressure_event(source_path)
      |> operational_timeline_feedback_event("operational_timeline_maneuver_feedback"),
      row
      |> operational_timeline_maneuver_uncertainty_feedback_event(source_path)
      |> operational_timeline_feedback_event("operational_timeline_maneuver_uncertainty")
    ]
  end

  defp operational_timeline_feedback_event(nil, _reason), do: nil

  defp operational_timeline_feedback_event(event, reason) do
    event
    |> Map.put("derivation_reasons", [reason])
    |> Map.put("feedback_scope", "operational_timeline")
  end

  defp operational_timeline_integrity_feedback_event(row, source_path) do
    issue_context = operational_timeline_integrity_issue_context(row)
    activity_id = realized_feedback_activity_id(row)
    timeline_id = explicit_timeline_id(row)

    if issue_context == %{} or (activity_id in [nil, ""] and timeline_id in [nil, ""]) do
      nil
    else
      %{
        "type" => "timeline_integrity_feedback",
        "activity_id" => activity_id,
        "timeline_id" => timeline_id,
        "scenario_id" => row["scenario_id"],
        "required_operator_action" =>
          row["required_operator_action"] || "review_timeline_integrity",
        "feedback_source" => source_path,
        "feedback_key" => activity_id || timeline_id,
        "trust_boundary" => operator_review_trust_boundary(row)
      }
      |> Map.merge(operational_timeline_activity_integrity_context(row))
      |> compact_map()
    end
  end

  defp operational_timeline_activity_integrity_context(row) do
    %{
      "dependency_activity_ids" => row["dependency_activity_ids"],
      "dependency_timeline_ids" => row["dependency_timeline_ids"],
      "exclusive_with_activity_ids" => row["exclusive_with_activity_ids"],
      "exclusive_with_timeline_ids" => row["exclusive_with_timeline_ids"],
      "exclusivity_group" => row["exclusivity_group"]
    }
    |> Map.merge(operational_timeline_integrity_issue_context(row))
    |> reject_empty_values()
  end

  defp operational_timeline_integrity_issue_context(row) do
    %{
      "missing_dependency_activity_ids" => row["missing_dependency_activity_ids"],
      "missing_dependency_timeline_ids" => row["missing_dependency_timeline_ids"],
      "dependency_cycle_activity_ids" => row["dependency_cycle_activity_ids"],
      "dependency_cycle_timeline_ids" => row["dependency_cycle_timeline_ids"],
      "dependency_order_violation_activity_ids" => row["dependency_order_violation_activity_ids"],
      "dependency_order_violation_timeline_ids" => row["dependency_order_violation_timeline_ids"],
      "exclusivity_violation_activity_ids" => row["exclusivity_violation_activity_ids"],
      "exclusivity_violation_timeline_ids" => row["exclusivity_violation_timeline_ids"],
      "exclusivity_violation_group" => row["exclusivity_violation_group"]
    }
    |> reject_empty_values()
  end

  defp operational_timeline_contact_success_feedback_event(row, source_path) do
    case operator_review_operational_timeline_contact_success_value(row) do
      value when is_number(value) and value < 1.0 ->
        %{
          "type" => "contact_success_feedback",
          "ground_station_id" => Map.get(row, "ground_station_id") || Map.get(row, "station_id"),
          "activity_id" => realized_feedback_activity_id(row),
          "scenario_id" => row["scenario_id"],
          "starts_at_s" => activity_raw_start(row) || 0.0,
          "ends_at_s" => activity_raw_end(row),
          "contact_success_factor" => clamp_unit_interval(value),
          "contact_result" => provider_result_artifact_value(row["contact_result"]),
          "required_operator_action" => row["required_operator_action"],
          "timeline_id" => explicit_timeline_id(row),
          "feedback_source" => source_path,
          "feedback_scope" => "operational_timeline",
          "feedback_key" => Map.get(row, "ground_station_id") || Map.get(row, "station_id"),
          "trust_boundary" => operator_review_trust_boundary(row)
        }
        |> put_feedback_weight_fields(row)
        |> put_observation_quality_feedback_fields(row)
        |> compact_map()

      _value ->
        nil
    end
  end

  defp operational_timeline_maneuver_uncertainty_feedback_event(row, source_path) do
    entry = maneuver_review_execution_uncertainty_entry(row)
    activity_id = realized_feedback_activity_id(row)

    if entry == %{} or activity_id in [nil, ""] do
      nil
    else
      %{
        "type" => "maneuver_execution_uncertainty_feedback",
        "activity_id" => activity_id,
        "scenario_id" => row["scenario_id"],
        "starts_at_s" => activity_raw_start(row) || 0.0,
        "ends_at_s" => activity_raw_end(row),
        "execution_uncertainty_status" => entry["execution_uncertainty_status"],
        "execution_uncertainty" => entry["execution_uncertainty"],
        "timing_3sigma_s" => entry["timing_3sigma_s"],
        "delta_v_3sigma_km_s" => entry["delta_v_3sigma_km_s"],
        "delta_v_3sigma_magnitude_km_s" => entry["delta_v_3sigma_magnitude_km_s"],
        "execution_uncertainty_source" => entry["execution_uncertainty_source"],
        "required_operator_action" => row["required_operator_action"],
        "cadence_import_status" => row["cadence_import_status"],
        "timeline_id" => explicit_timeline_id(row),
        "maneuver_id" => row["maneuver_id"],
        "feedback_source" => source_path,
        "feedback_scope" => "operational_timeline",
        "feedback_key" => activity_id,
        "trust_boundary" => operator_review_trust_boundary(row)
      }
      |> compact_map()
    end
  end

  defp operational_timeline_observation_feedback_event(row, source_path) do
    case operator_review_operational_timeline_observation_success_value(row) do
      value when is_number(value) and value < 1.0 ->
        %{
          "type" => "observation_success_feedback",
          "target_id" => Map.get(row, "target_id") || Map.get(row, "id"),
          "activity_id" => realized_feedback_activity_id(row),
          "scenario_id" => row["scenario_id"],
          "starts_at_s" => activity_raw_start(row) || 0.0,
          "ends_at_s" => activity_raw_end(row),
          "observation_success_factor" => clamp_unit_interval(value),
          "observation_result" => provider_result_artifact_value(row["observation_result"]),
          "required_operator_action" => row["required_operator_action"],
          "timeline_id" => explicit_timeline_id(row),
          "feedback_source" => source_path,
          "feedback_scope" => "operational_timeline",
          "feedback_key" => Map.get(row, "target_id") || Map.get(row, "id"),
          "trust_boundary" => operator_review_trust_boundary(row)
        }
        |> put_feedback_weight_fields(row)
        |> put_observation_quality_feedback_fields(row)
        |> compact_map()

      _value ->
        nil
    end
  end

  defp operational_timeline_review_pressure_branch_id(row, index),
    do:
      "derived_operational_timeline_feedback_#{operational_timeline_review_pressure_identity(row, index)}"

  defp operational_timeline_review_pressure_identity(row, index) do
    [
      realized_feedback_activity_id(row),
      explicit_timeline_id(row),
      row["id"],
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp candidate_diff_review_source(%{"source_candidate_diff" => %{} = source} = row)
       when map_size(source) > 0,
       do: {candidate_diff_review_row(source, row), "source_candidate_diff"}

  defp candidate_diff_review_source(row),
    do: {candidate_diff_review_row(row, row), "candidate_diff_review"}

  defp candidate_diff_review_row(source, row) do
    candidate_diff =
      source
      |> stringify_keys()
      |> put_operator_review_row_fallback(row, "id", "activity_id")
      |> put_operator_review_row_fallback(row, "activity_id")
      |> put_operator_review_row_fallback(row, "activity_type")
      |> put_operator_review_row_fallback(row, "scenario_id")
      |> put_operator_review_row_fallback(row, "target_id")
      |> put_operator_review_row_fallback(row, "source_target_id")
      |> put_operator_review_row_fallback(row, "source_target")
      |> put_operator_review_row_fallback(row, "target_latitude_deg")
      |> put_operator_review_row_fallback(row, "target_longitude_deg")
      |> put_operator_review_row_fallback(row, "target_minimum_elevation_deg")
      |> put_operator_review_row_fallback(row, "target_priority")
      |> put_operator_review_row_fallback(row, "target_priority_source")
      |> put_operator_review_row_fallback(row, "target_priority_objective_ids")
      |> put_operator_review_row_fallback(row, "target_priority_objective_type")
      |> put_operator_review_row_fallback(row, "ground_station_id")
      |> put_operator_review_row_fallback(row, "direction")
      |> put_operator_review_row_fallback(row, "source_window_id")
      |> put_operator_review_row_fallback(row, "source_window_type")
      |> put_operator_review_row_fallback(row, "replacement_source_window_id")
      |> put_operator_review_row_fallback(row, "starts_at_s")
      |> put_operator_review_row_fallback(row, "ends_at_s")
      |> put_operator_review_row_fallback(row, "invalidated_candidate_id")
      |> put_operator_review_row_fallback(row, "replacement_candidate_id")
      |> put_operator_review_row_fallback(row, "invalidated_reason")
      |> put_operator_review_row_fallback(row, "semantic_change_reasons")
      |> put_operator_review_row_fallback(row, "semantic_change_details")
      |> put_operator_review_row_fallback(row, "changed_fields")
      |> put_operator_review_row_fallback(row, "candidate_diff_changed_fields")
      |> put_operator_review_row_fallback(row, "candidate_diff_changed_field_count")
      |> put_operator_review_row_fallback(row, "candidate_diff_match_status")
      |> put_operator_review_row_fallback(row, "candidate_budget_match_status")
      |> put_operator_review_row_fallback(row, "budget_dropped_candidate_ids")
      |> put_operator_review_row_fallback(row, "required_operator_action")
      |> put_candidate_diff_changed_fields()

    candidate_diff
    |> put_if_present(
      "source_candidate_diff",
      enriched_source_candidate_diff(row["source_candidate_diff"], candidate_diff)
    )
  end

  defp enriched_source_candidate_diff(%{} = source_candidate_diff, candidate_diff) do
    source_candidate_diff
    |> stringify_keys()
    |> Map.merge(Map.take(candidate_diff, candidate_diff_evidence_fields()))
    |> compact_map()
  end

  defp enriched_source_candidate_diff(_source_candidate_diff, _candidate_diff), do: nil

  defp put_candidate_diff_changed_fields(row) do
    case candidate_diff_changed_fields(row) do
      [] ->
        row

      fields ->
        row
        |> Map.put("changed_fields", fields)
        |> Map.put("candidate_diff_changed_fields", fields)
        |> Map.put("candidate_diff_changed_field_count", length(fields))
    end
  end

  defp candidate_diff_changed_fields(row) do
    row
    |> Map.get("candidate_diff_changed_fields", Map.get(row, "changed_fields"))
    |> List.wrap()
    |> Enum.concat(semantic_change_detail_fields(row["semantic_change_details"]))
    |> Enum.filter(&is_binary/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp semantic_change_detail_fields(details) do
    details
    |> List.wrap()
    |> Enum.map(&Map.get(&1, "field"))
  end

  defp candidate_diff_evidence_fields do
    [
      "id",
      "type",
      "activity_id",
      "activity_type",
      "scenario_id",
      "target_id",
      "source_target_id",
      "source_target",
      "target_latitude_deg",
      "target_longitude_deg",
      "target_minimum_elevation_deg",
      "target_priority",
      "target_priority_source",
      "target_priority_objective_ids",
      "target_priority_objective_type",
      "ground_station_id",
      "direction",
      "source_window_id",
      "source_window_type",
      "replacement_source_window_id",
      "starts_at_s",
      "ends_at_s",
      "invalidated_candidate_id",
      "replacement_candidate_id",
      "invalidated_reason",
      "semantic_change_reasons",
      "semantic_change_details",
      "changed_fields",
      "candidate_diff_changed_fields",
      "candidate_diff_changed_field_count",
      "candidate_diff_match_status",
      "candidate_budget_match_status",
      "budget_dropped_candidate_ids",
      "required_operator_action"
      | CandidateDiffMetadata.scoped_context_fields()
    ]
  end

  defp candidate_diff_review_row?(row) do
    (row["source_review_type"] == "candidate_diff_review" or
       row["review_type"] == "candidate_diff_review" or
       row["import_action"] == "review_candidate_diff") and
      stable_id_string?(candidate_diff_replacement_candidate_id(row))
  end

  defp candidate_diff_pressure_branch(row, source_path, index) do
    case candidate_diff_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        [
          %{
            "id" =>
              "derived_candidate_diff_replacement_#{candidate_diff_pressure_identity(row, index)}",
            "label" =>
              "Derived candidate-diff replacement #{candidate_diff_pressure_identity(row, index)}",
            "events" => [event],
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp candidate_diff_pressure_event(row, source_path) do
    replacement_id = candidate_diff_replacement_candidate_id(row)

    if stable_id_string?(replacement_id) do
      %{
        "type" => "candidate_diff_replacement",
        "replacement_candidate_id" => replacement_id,
        "invalidated_candidate_id" => row["invalidated_candidate_id"] || row["id"],
        "activity_id" => row["activity_id"] || row["id"],
        "activity_type" => row["activity_type"] || row["type"],
        "scenario_id" => row["scenario_id"],
        "target_id" => row["target_id"],
        "source_target_id" => row["source_target_id"],
        "source_target" => row["source_target"],
        "target_latitude_deg" => row["target_latitude_deg"],
        "target_longitude_deg" => row["target_longitude_deg"],
        "target_minimum_elevation_deg" => row["target_minimum_elevation_deg"],
        "target_priority" => row["target_priority"],
        "target_priority_source" => row["target_priority_source"],
        "target_priority_objective_ids" => row["target_priority_objective_ids"],
        "target_priority_objective_type" => row["target_priority_objective_type"],
        "ground_station_id" => row["ground_station_id"],
        "direction" => row["direction"],
        "starts_at_s" => activity_raw_start(row),
        "ends_at_s" => activity_raw_end(row),
        "source_window_id" => row["source_window_id"],
        "source_window_type" => row["source_window_type"],
        "replacement_source_window_id" => row["replacement_source_window_id"],
        "invalidated_reason" => row["invalidated_reason"],
        "semantic_change_reasons" => row["semantic_change_reasons"],
        "semantic_change_details" => row["semantic_change_details"],
        "changed_fields" => row["changed_fields"],
        "candidate_diff_changed_fields" => row["candidate_diff_changed_fields"],
        "candidate_diff_changed_field_count" => row["candidate_diff_changed_field_count"],
        "candidate_diff_match_status" => row["candidate_diff_match_status"],
        "candidate_budget_match_status" => row["candidate_budget_match_status"],
        "budget_dropped_candidate_ids" => row["budget_dropped_candidate_ids"],
        "required_operator_action" => row["required_operator_action"],
        "derivation_reasons" => ["candidate_diff_replacement"],
        "feedback_source" => source_path,
        "feedback_scope" => "candidate_diff",
        "feedback_key" => replacement_id,
        "trust_boundary" => operator_review_trust_boundary(row),
        "source_candidate_diff" => Map.get(row, "source_candidate_diff", row)
      }
      |> Map.merge(CandidateDiffMetadata.scoped_context(row))
      |> compact_map()
    end
  end

  defp candidate_diff_replacement_candidate_id(row) do
    row["replacement_candidate_id"] ||
      get_in(row, ["source_candidate_diff", "replacement_candidate_id"]) ||
      get_in(row, ["candidate_diff", "replacement_candidate_id"])
  end

  defp candidate_diff_pressure_identity(row, index) do
    [
      candidate_diff_replacement_candidate_id(row),
      row["invalidated_candidate_id"],
      row["activity_id"],
      row["id"],
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp derived_mission_state_candidate_diff_pressure_branches(mission_state) do
    mission_state
    |> CandidateReviewSourceReports.candidate_diff_reports(source_report_family_callbacks())
    |> CandidateReviewSourceReports.candidate_diff_pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      candidate_diff_pressure_branch(row, source_path, index)
    end)
  end

  defp candidate_rejection_pressure_branch(row, source_path, index) do
    case candidate_rejection_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        identity = candidate_rejection_pressure_identity(row, index)

        [
          %{
            "id" => "derived_candidate_rejection_pressure_#{identity}",
            "label" => "Derived candidate-rejection review #{identity}",
            "events" => [event],
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp candidate_rejection_pressure_event(row, source_path) do
    candidate_id = candidate_rejection_candidate_id(row)

    if stable_id_string?(candidate_id) and candidate_rejection_reviewable?(row) do
      %{
        "type" => "candidate_rejection_pressure",
        "candidate_id" => candidate_id,
        "activity_id" => row["activity_id"] || candidate_id,
        "activity_type" => row["activity_type"] || row["type"],
        "scenario_id" => row["scenario_id"] || get_in(row, ["activity_context", "scenario_id"]),
        "target_id" => row["target_id"] || get_in(row, ["activity_context", "target_id"]),
        "ground_station_id" =>
          row["ground_station_id"] || get_in(row, ["activity_context", "ground_station_id"]),
        "source_window_id" =>
          row["source_window_id"] || get_in(row, ["activity_context", "source_window_id"]),
        "source_window_type" =>
          row["source_window_type"] || get_in(row, ["activity_context", "source_window_type"]),
        "rejection_status" => row["rejection_status"],
        "primary_rejection_reason" => row["primary_rejection_reason"],
        "rejection_reasons" => row["rejection_reasons"],
        "violated_constraint" => row["violated_constraint"],
        "required_margin" => row["required_margin"],
        "actual_margin" => row["actual_margin"],
        "required_operator_action" => row["required_operator_action"],
        "derivation_reasons" => ["candidate_rejection_review"],
        "feedback_source" => source_path,
        "feedback_scope" => "candidate_rejection",
        "feedback_key" => candidate_id,
        "trust_boundary" => operator_review_trust_boundary(row),
        "source_candidate_rejection" => Map.get(row, "source_candidate_rejection", row)
      }
      |> compact_map()
    end
  end

  defp candidate_rejection_reviewable?(row) do
    row["rejection_status"] == "rejected" and
      row["reviewable"] == true and
      row["required_operator_action"] == "review_candidate_rejection"
  end

  defp candidate_rejection_candidate_id(row) do
    row["candidate_id"] ||
      row["activity_id"] ||
      get_in(row, ["source_candidate_rejection", "candidate_id"]) ||
      get_in(row, ["source_candidate_rejection", "activity_id"])
  end

  defp candidate_rejection_pressure_identity(row, index) do
    [
      candidate_rejection_candidate_id(row),
      row["activity_id"],
      row["id"],
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp derived_mission_state_candidate_rejection_pressure_branches(mission_state) do
    mission_state
    |> CandidateReviewSourceReports.candidate_rejection_reports(source_report_family_callbacks())
    |> CandidateReviewSourceReports.candidate_rejection_pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      candidate_rejection_pressure_branch(row, source_path, index)
    end)
  end

  defp provider_counteroffer_pressure_branch(row, source_path, index) do
