  defp provider_counteroffer_pressure_event(row, source_path) do
    counteroffer_id = provider_counteroffer_id(row)

    if stable_id_string?(counteroffer_id) and provider_counteroffer_reviewable?(row) do
      %{
        "type" => "provider_counteroffer_pressure",
