  defp refresh_budget_review_source(%{"source_refresh_budget_report" => %{} = source} = row)
       when map_size(source) > 0,
       do: {refresh_budget_pressure_row(source, row), "source_refresh_budget_report"}

  defp refresh_budget_review_source(row),
    do: {refresh_budget_pressure_row(row, row), "refresh_budget_review"}

  defp refresh_budget_pressure_row(source, row) do
    source
    |> stringify_keys()
    |> put_operator_review_row_fallback(row, "id")
    |> put_operator_review_row_fallback(row, "input_candidate_count")
    |> put_operator_review_row_fallback(row, "kept_candidate_count")
    |> put_operator_review_row_fallback(row, "dropped_candidate_count")
    |> put_operator_review_row_fallback(row, "max_candidate_activities")
    |> put_operator_review_row_fallback(row, "invalid_candidate_limit_policy")
    |> put_operator_review_row_fallback(row, "invalid_candidate_limit_policy_reason")
    |> put_operator_review_row_fallback(row, "selection_order")
    |> put_operator_review_row_fallback(row, "kept_candidate_ids")
    |> put_operator_review_row_fallback(row, "dropped_candidate_ids")
    |> put_operator_review_row_fallback(row, "required_operator_action")
    |> put_if_present("source_refresh_budget_report", row["source_refresh_budget_report"])
  end

  defp refresh_budget_review_row?(row) do
    (row["source_review_type"] == "refresh_budget_review" or
       row["review_type"] == "refresh_budget_review" or
       row["import_action"] == "review_refresh_budget") and
      refresh_budget_relaxed_limit(row) != nil
  end

  defp refresh_budget_pressure_branch(row, source_path, index) do
    case refresh_budget_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        [
          %{
            "id" =>
              "derived_refresh_budget_pressure_#{refresh_budget_pressure_identity(row, index)}",
            "label" =>
              "Derived refresh-budget pressure #{refresh_budget_pressure_identity(row, index)}",
            "events" => [event],
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp refresh_budget_pressure_event(row, source_path) do
    case refresh_budget_relaxed_limit(row) do
      relaxed_limit when is_integer(relaxed_limit) and relaxed_limit > 0 ->
        %{
          "type" => "refresh_budget_pressure",
          "input_candidate_count" => ceil_count(row["input_candidate_count"] || 0),
          "kept_candidate_count" => ceil_count(row["kept_candidate_count"] || 0),
          "dropped_candidate_count" => ceil_count(row["dropped_candidate_count"] || 0),
          "current_max_candidate_activities" => numeric_or_nil(row["max_candidate_activities"]),
          "relaxed_max_candidate_activities" => relaxed_limit,
          "invalid_candidate_limit_policy" => row["invalid_candidate_limit_policy"],
          "invalid_candidate_limit_policy_reason" => row["invalid_candidate_limit_policy_reason"],
          "selection_order" => row["selection_order"],
          "kept_candidate_ids" => row["kept_candidate_ids"],
          "dropped_candidate_ids" => row["dropped_candidate_ids"],
          "required_operator_action" => row["required_operator_action"],
          "derivation_reasons" => ["refresh_budget_candidate_limit_pressure"],
          "feedback_source" => source_path,
          "feedback_scope" => "refresh_budget",
          "feedback_key" => row["id"] || row["subject_id"] || "refresh_budget",
          "trust_boundary" => operator_review_trust_boundary(row),
          "source_refresh_budget_report" => Map.get(row, "source_refresh_budget_report", row)
        }
        |> compact_map()

      _limit ->
        nil
    end
  end

  defp refresh_budget_relaxed_limit(row) do
    dropped_count = ceil_count(row["dropped_candidate_count"] || 0)
    invalid_policy? = row["invalid_candidate_limit_policy"] == true

    if dropped_count > 0 or invalid_policy? do
      input_count = ceil_count(row["input_candidate_count"] || 0)
      kept_count = ceil_count(row["kept_candidate_count"] || 0)
      current_limit = ceil_count(row["max_candidate_activities"] || 0)

      [input_count, kept_count + dropped_count, current_limit + dropped_count]
      |> Enum.reject(&(&1 <= 0))
      |> Enum.max(fn -> nil end)
      |> case do
        limit when is_integer(limit) and limit > current_limit -> limit
        limit when is_integer(limit) and invalid_policy? -> limit
        _limit -> nil
      end
    end
  end

  defp refresh_budget_pressure_identity(row, index) do
    [
      row["id"],
      row["subject_id"],
      row["refresh_gate_status"],
      "limit_#{refresh_budget_relaxed_limit(row)}",
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

