        "required_operator_action" => validation_safety_case_pressure_action(row),
        "derivation_reasons" => ["validation_safety_case_review"],
        "feedback_source" => source_path,
        "feedback_scope" => "validation_safety_case",
        "feedback_key" =>
          row["evidence_ref"] || row["input_contract"] || row["report_id"] ||
            "validation_safety_case",
        "trust_boundary" => operator_review_trust_boundary(row),
        "source_validation_safety_case_evidence" => row["source_validation_safety_case_evidence"],
        "source_validation_safety_case_summary" => row["source_validation_safety_case_summary"]
      }
      |> compact_map()
    end
  end

  defp validation_safety_case_reviewable?(row),
    do:
      row["evidence_status"] in ["review_required", "blocked"] or
        row["validation_safety_case_status"] in ["review_required", "blocked"]

  defp validation_safety_case_pressure_identity(row, index) do
    [
      row["evidence_ref"],
      row["input_contract"],
      row["report_id"],
      row["evidence_status"],
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp derived_mission_state_validation_safety_case_pressure_branches(mission_state) do
    mission_state
    |> mission_state_validation_safety_case_summaries()
    |> ValidationSafetyCaseSourceReports.pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      validation_safety_case_pressure_branch(row, source_path, index)
    end)
  end

  defp validation_safety_case_pressure_action(%{"evidence_status" => "blocked"}),
    do: "review_blocked_validation_safety_case"

  defp validation_safety_case_pressure_action(%{
         "validation_safety_case_status" => "blocked"
       }),
       do: "review_blocked_validation_safety_case"

  defp validation_safety_case_pressure_action(_row), do: "review_validation_safety_case"

  defp mission_state_schema_validation_reports(mission_state) do
    SchemaValidationSourceReports.schema_validation_reports(
      mission_state,
      source_report_family_callbacks()
    )
  end

  defp schema_validation_pressure_branch(row, source_path, index) do
    case schema_validation_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        identity = schema_validation_pressure_identity(row, index)

        [
          %{
            "id" => "derived_schema_validation_pressure_#{identity}",
            "label" => "Derived schema-validation review #{identity}",
            "events" => [event],
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp schema_validation_pressure_event(row, source_path) do
    if schema_validation_reviewable?(row) do
      %{
        "type" => "schema_validation_pressure",
        "validation_status" => row["validation_status"],
        "validation_mode" => row["validation_mode"],
        "validated_contract" => row["validated_contract"],
        "validated_artifact_family" => row["validated_artifact_family"],
        "artifact_path" => row["artifact_path"],
        "issue_severity" => row["issue_severity"],
        "issue_path" => row["issue_path"],
        "issue_message" => row["issue_message"],
        "error_count" => row["error_count"],
        "warning_count" => row["warning_count"],
        "remediation_count" => row["remediation_count"],
        "remediation_category" => row["remediation_category"],
        "remediation_action" => row["remediation_action"],
        "required_operator_action" => "review_schema_validation",
        "derivation_reasons" => ["schema_validation_review"],
        "feedback_source" => source_path,
        "feedback_scope" => "schema_validation",
        "feedback_key" => row["issue_path"] || row["validated_contract"] || "schema_validation",
        "trust_boundary" => operator_review_trust_boundary(row),
        "source_validation_issue" => row["source_validation_issue"],
        "source_validation_remediation" => row["source_validation_remediation"],
        "source_schema_validation_report" => row["source_schema_validation_report"]
      }
      |> compact_map()
    end
  end

  defp schema_validation_reviewable?(row) do
    row["required_operator_action"] == "review_schema_validation" and
      row["issue_severity"] in ["error", "warning"]
  end

  defp schema_validation_pressure_identity(row, index) do
    [
      row["validated_contract"],
      row["issue_path"],
      row["artifact_path"],
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp derived_mission_state_schema_validation_pressure_branches(mission_state) do
    mission_state
    |> mission_state_schema_validation_reports()
    |> SchemaValidationSourceReports.pressure_rows()
    |> Enum.flat_map(fn {row, source_path, index} ->
      schema_validation_pressure_branch(row, source_path, index)
    end)
  end

  defp freshness_review_source(%{"source_freshness_report" => %{} = source} = row)
       when map_size(source) > 0,
       do: {freshness_pressure_row(source, row), "source_freshness_report"}

  defp freshness_review_source(row), do: {freshness_pressure_row(row, row), "freshness_review"}

  defp freshness_pressure_row(source, row) do
    source
    |> stringify_keys()
    |> put_operator_review_row_fallback(row, "id")
    |> put_operator_review_row_fallback(row, "freshness_status")
    |> put_operator_review_row_fallback(row, "status", "freshness_status")
    |> put_operator_review_row_fallback(row, "state_quality_status")
    |> put_operator_review_row_fallback(row, "accepted_snapshot_age_s")
    |> put_operator_review_row_fallback(row, "horizon_start_offset_s")
    |> put_operator_review_row_fallback(row, "max_snapshot_age_s")
    |> put_operator_review_row_fallback(row, "max_horizon_start_offset_s")
    |> put_operator_review_row_fallback(row, "stale_reasons")
    |> put_operator_review_row_fallback(row, "unknown_reasons")
    |> put_operator_review_row_fallback(row, "required_operator_action")
    |> put_if_present("source_freshness_report", row["source_freshness_report"])
  end

  defp freshness_review_row?(row) do
    (row["source_review_type"] == "freshness_review" or
       row["review_type"] == "freshness_review" or
       row["import_action"] == "review_refresh_freshness") and
      freshness_pressure_status(row) in ["stale", "unknown"]
  end

  defp freshness_pressure_branch(row, source_path, index) do
    case freshness_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        [
          %{
            "id" =>
              "derived_refresh_freshness_pressure_#{freshness_pressure_identity(row, index)}",
            "label" =>
              "Derived refresh-freshness pressure #{freshness_pressure_identity(row, index)}",
            "events" => [event],
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp freshness_pressure_event(row, source_path) do
    case freshness_pressure_status(row) do
      status when status in ["stale", "unknown"] ->
        %{
          "type" => "refresh_freshness_pressure",
          "freshness_status" => status,
          "state_quality_status" => row["state_quality_status"],
          "accepted_snapshot_age_s" => row["accepted_snapshot_age_s"],
          "horizon_start_offset_s" => row["horizon_start_offset_s"],
          "max_snapshot_age_s" => row["max_snapshot_age_s"],
          "max_horizon_start_offset_s" => row["max_horizon_start_offset_s"],
          "stale_reasons" => row["stale_reasons"],
          "unknown_reasons" => row["unknown_reasons"],
          "required_operator_action" => row["required_operator_action"],
          "derivation_reasons" => ["refresh_freshness_pressure"],
          "feedback_source" => source_path,
          "feedback_scope" => "refresh_freshness",
          "feedback_key" => row["id"] || row["subject_id"] || status,
          "trust_boundary" => operator_review_trust_boundary(row),
          "source_freshness_report" => Map.get(row, "source_freshness_report", row)
        }
        |> compact_map()

      _status ->
        nil
    end
  end

  defp freshness_pressure_status(row) do
    row["freshness_status"] ||
      row["status"] ||
      get_in(row, ["source_freshness_report", "freshness_status"]) ||
      get_in(row, ["source_freshness_report", "status"])
  end

  defp freshness_pressure_identity(row, index) do
    [
      row["id"],
      row["subject_id"],
      freshness_pressure_status(row),
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp derived_mission_state_refresh_freshness_pressure_branches(mission_state) do
    mission_state
    |> mission_state_freshness_reports()
    |> RefreshSourceReports.pressure_rows()
    |> Enum.flat_map(fn {report, source_path, index} ->
      freshness_pressure_branch(report, source_path, index)
    end)
  end

  defp mission_state_freshness_reports(mission_state) do
    RefreshSourceReports.freshness_reports(mission_state, source_report_family_callbacks())
  end

  defp plan_delta_review_source(%{"source_delta" => %{} = source} = row)
       when map_size(source) > 0,
       do: {plan_delta_timeline_diff_row(source, row), "source_delta"}

  defp plan_delta_review_source(row),
    do: {plan_delta_timeline_diff_row(row, row), "plan_delta_review"}

  defp plan_delta_timeline_diff_row(source, row) do
    source = stringify_keys(source)

    source_context =
      source["source_activity_context"] || row["source_activity_context"] ||
        source["planned"] || row["planned"] || %{}

    replacement_context =
      source["replacement_activity_context"] || row["replacement_activity_context"] ||
        source["replacement"] || row["replacement"] || %{}

    repair_action = source["repair_action"] || row["repair_action"]

    %{
      "id" => source["id"] || row["id"],
      "diff_status" => plan_delta_diff_status(repair_action),
      "repair_action" => repair_action,
      "timeline_id" => source["source_timeline_id"] || row["source_timeline_id"],
      "source_activity_id" => source["activity_id"] || row["activity_id"],
      "source_activity_type" => source["activity_type"] || row["activity_type"],
      "source_direction" => source["direction"] || source_context["direction"],
      "source_status" => source_context["status"] || source["source_status"],
      "source_activity_context" => source_context,
      "replacement_activity_id" =>
        source["replacement_activity_id"] || row["replacement_activity_id"],
      "replacement_activity_type" =>
        replacement_context["activity_type"] || replacement_context["type"],
      "replacement_direction" => replacement_context["direction"],
      "replacement_activity_context" => replacement_context,
      "required_operator_action" =>
        row["required_operator_action"] || source["required_operator_action"],
      "approval_status" => row["approval_status"] || source["approval_status"]
    }
    |> compact_map()
  end

  defp plan_delta_diff_status(action) when action in ["canceled", "cancelled", "suppressed"],
    do: "removed"

  defp plan_delta_diff_status(action) when action in ["moved", "replaced"], do: "changed"
  defp plan_delta_diff_status(_action), do: nil

  defp plan_delta_review_row?(row) do
    (row["source_review_type"] == "plan_delta_review" or
       row["review_type"] == "plan_delta_review" or row["import_action"] == "review_plan_delta") and
      plan_delta_diff_status(row["repair_action"]) != nil
  end

  defp timeline_diff_review_row?(row) do
    (row["source_review_type"] == "timeline_diff_review" or
       row["review_type"] == "timeline_diff_review" or
       row["import_action"] == "review_timeline_diff") and
      row["diff_status"] not in [nil, ""] and
      (row["source_activity_id"] not in [nil, ""] or
         row["replacement_activity_id"] not in [nil, ""] or row["timeline_id"] not in [nil, ""])
  end

  defp command_window_review_source(row),
    do: CommandWindowOperationalFeedback.source(row, command_window_row_shaping_callbacks())

  defp command_window_row_shaping_callbacks do
    [
      stringify_keys: &stringify_keys/1,
      put_default_if_present: &put_default_if_present/3,
      put_feedback_weight_fields: &put_feedback_weight_fields/2
    ]
  end

  defp command_window_review_row?(row) do
    (row["source_review_type"] == "command_window_review" or
       row["review_type"] == "command_window_review" or
       row["import_action"] == "review_command_window") and
      command_window_pressure_event(row, "candidate") != nil
  end

  defp command_window_pressure_branch(row, source_path, index) do
    CommandWindowOperationalFeedback.pressure_branch(
      row,
      source_path,
      index,
      command_window_pressure_callbacks()
    )
  end

  defp command_window_pressure_event(row, source_path) do
    CommandWindowOperationalFeedback.pressure_event(
      row,
      source_path,
      command_window_pressure_callbacks()
    )
  end

  defp command_window_pressure_callbacks do
    command_window_feedback_callbacks() ++
      [
        activity_raw_start: &activity_raw_start/1,
        activity_raw_end: &activity_raw_end/1,
        clamp_unit_interval: &clamp_unit_interval/1,
        provider_result_artifact_value: &provider_result_artifact_value/1,
        explicit_timeline_id: &explicit_timeline_id/1,
        operator_review_trust_boundary: &operator_review_trust_boundary/1,
        put_feedback_weight_fields: &put_feedback_weight_fields/2,
        compact_map: &compact_map/1,
        provider_result_values: &provider_result_values/1,
        branch_id_fragment: &branch_id_fragment/1
      ]
  end

  defp maneuver_review_source(row),
    do: ManeuverReviewOperationalFeedback.source(row, maneuver_review_row_shaping_callbacks())

  defp maneuver_review_row_shaping_callbacks do
    [
      stringify_keys: &stringify_keys/1,
      put_default_if_present: &put_default_if_present/3,
      put_feedback_weight_fields: &put_feedback_weight_fields/2,
      normalize_row: &normalize_maneuver_review_feedback_row/1
    ]
  end

  defp maneuver_review_row?(row) do
    (row["source_review_type"] == "maneuver_review" or row["review_type"] == "maneuver_review" or
       row["import_action"] == "review_maneuver") and
      maneuver_review_pressure_events(row, "candidate") != []
  end

  defp maneuver_review_pressure_branch(row, source_path, index) do
    ManeuverReviewOperationalFeedback.pressure_branch(
      row,
      source_path,
      index,
      maneuver_review_pressure_callbacks()
    )
  end

  defp maneuver_review_pressure_events(row, source_path) do
    ManeuverReviewOperationalFeedback.pressure_events(
      row,
      source_path,
      maneuver_review_pressure_callbacks()
    )
  end

  defp maneuver_review_pressure_event(row, source_path) do
    ManeuverReviewOperationalFeedback.pressure_event(
      row,
      source_path,
      maneuver_review_pressure_callbacks()
    )
  end

  defp maneuver_review_pressure_callbacks do
    [
      row_success_value: &maneuver_review_row_success_value/1,
      realized_feedback_activity_id: &realized_feedback_activity_id/1,
      execution_uncertainty_entry: &maneuver_review_execution_uncertainty_entry/1,
      activity_raw_start: &activity_raw_start/1,
      activity_raw_end: &activity_raw_end/1,
      clamp_unit_interval: &clamp_unit_interval/1,
      provider_result_artifact_value: &provider_result_artifact_value/1,
      explicit_timeline_id: &explicit_timeline_id/1,
      operator_review_trust_boundary: &operator_review_trust_boundary/1,
      put_feedback_weight_fields: &put_feedback_weight_fields/2,
      compact_map: &compact_map/1,
      branch_id_fragment: &branch_id_fragment/1
    ]
  end

  defp realized_feedback_review_source(%{"source_feedback" => %{} = source} = row)
       when map_size(source) > 0 do
    {realized_feedback_review_row(source, row), "source_feedback"}
  end

  defp realized_feedback_review_source(row),
    do: {realized_feedback_review_row(row, row), "realized_feedback"}

  defp realized_feedback_review_row(source, row) do
    source
    |> stringify_keys()
    |> put_if_present("feedback_status", row["feedback_status"])
    |> put_if_present("status", row["realized_status"] || row["status"])
    |> put_operator_review_row_fallback(row, "activity_id")
    |> put_operator_review_row_fallback(row, "id", "activity_id")
    |> put_operator_review_row_fallback(row, "timeline_id", "timeline_identity")
    |> put_operator_review_row_fallback(row, "scenario_id")
    |> put_operator_review_row_fallback(row, "ground_station_id")
    |> put_operator_review_row_fallback(row, "ground_station_id", "planned_ground_station_id")
    |> put_operator_review_row_fallback(row, "ground_station_id", "realized_ground_station_id")
    |> put_operator_review_row_fallback(row, "target_id")
    |> put_operator_review_row_fallback(row, "target_id", "planned_target_id")
    |> put_operator_review_row_fallback(row, "target_id", "realized_target_id")
    |> put_operator_review_row_fallback(row, "contact_success")
    |> put_operator_review_row_fallback(row, "contact_success_factor")
    |> put_operator_review_row_fallback(row, "contact_result")
    |> put_operator_review_row_fallback(row, "observation_success")
    |> put_operator_review_row_fallback(row, "observation_success_factor")
    |> put_operator_review_row_fallback(row, "observation_result")
    |> put_operator_review_row_fallback(row, "command_success")
    |> put_operator_review_row_fallback(row, "command_success_factor")
    |> put_operator_review_row_fallback(row, "command_result")
    |> put_operator_review_row_fallback(row, "maneuver_success")
    |> put_operator_review_row_fallback(row, "maneuver_success_factor")
    |> put_operator_review_row_fallback(row, "maneuver_result")
    |> put_operator_review_row_fallback(row, "execution_uncertainty")
    |> put_operator_review_row_fallback(row, "execution_uncertainty_status")
    |> put_operator_review_row_fallback(row, "timing_3sigma_s")
    |> put_operator_review_row_fallback(row, "delta_v_3sigma_km_s")
    |> put_operator_review_row_fallback(row, "delta_v_3sigma_magnitude_km_s")
    |> put_operator_review_row_fallback(row, "execution_uncertainty_source")
    |> put_operator_review_row_fallback(row, "actual_throughput_mb")
    |> put_operator_review_row_fallback(row, "estimated_throughput_mb")
    |> put_operator_review_row_fallback(row, "required_downlink_mb")
    |> put_operator_review_row_fallback(row, "completed_fraction")
    |> put_feedback_weight_fields(row)
    |> put_if_present("type", operator_review_realized_feedback_type(row, source))
    |> put_if_present("_operator_review_feedback_status", row["feedback_status"])
    |> put_if_present("_operator_review_match_strategy", row["match_strategy"])
    |> put_if_present("_operator_review_realized_match_count", row["realized_match_count"])
    |> put_if_present(
      "_operator_review_invalid_realized_feedback_input",
      row["invalid_realized_feedback_input"]
    )
    |> put_if_present("_operator_review_invalid_activity_input", row["invalid_activity_input"])
  end

  defp realized_feedback_review_row?(row) do
    (row["source_review_type"] == "realized_feedback" or
       row["review_type"] == "realized_feedback" or
       row["import_action"] in ["review_realized_feedback", "record_realized_feedback"]) and
      realized_feedback_pressure_events(row, "candidate") != []
  end

  defp realized_feedback_pressure_branch(row, source_path, index) do
    case realized_feedback_pressure_events(row, source_path) do
      [] ->
        []

      events ->
        [
          %{
            "id" => realized_feedback_pressure_branch_id(row, index),
            "label" =>
              "Derived realized-feedback #{realized_feedback_pressure_identity(row, index)}",
            "events" => events,
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp realized_feedback_pressure_events(row, source_path) do
    cond do
      not operator_review_feedback_row_usable?(row) ->
        []

      operator_review_command_feedback_row?(row) ->
        [realized_command_feedback_event(row, source_path)]

      operator_review_maneuver_feedback_row?(row) ->
        realized_maneuver_feedback_events(row, source_path)

      operator_review_contact_feedback_row?(row) ->
        realized_contact_feedback_events(row, source_path)

      operator_review_observation_feedback_row?(row) ->
        realized_observation_feedback_events(row, source_path)

      true ->
        []
    end
    |> Enum.reject(&is_nil/1)
  end

  defp realized_command_feedback_event(row, source_path) do
    case command_success_value(row) do
      value when is_number(value) and value < 1.0 ->
        row
        |> command_window_pressure_event(source_path)
        |> Map.put("derivation_reasons", ["realized_command_feedback"])
        |> Map.put("feedback_scope", "realized_feedback")

      _value ->
        nil
    end
  end

  defp realized_maneuver_feedback_event(row, source_path) do
    case maneuver_review_row_success_value(row) do
      value when is_number(value) and value < 1.0 ->
        row
        |> maneuver_review_pressure_event(source_path)
        |> Map.put("derivation_reasons", ["realized_maneuver_feedback"])
        |> Map.put("feedback_scope", "realized_feedback")

      _value ->
        nil
    end
  end

  defp realized_maneuver_feedback_events(row, source_path) do
    [
      realized_maneuver_feedback_event(row, source_path),
      realized_maneuver_uncertainty_feedback_event(row, source_path)
    ]
  end

  defp realized_maneuver_uncertainty_feedback_event(row, source_path) do
    entry = maneuver_review_execution_uncertainty_entry(row)
    activity_id = realized_feedback_activity_id(row)

    if entry == %{} or activity_id in [nil, ""] do
      nil
    else
      %{
        "type" => "maneuver_execution_uncertainty_feedback",
        "activity_id" => activity_id,
        "scenario_id" => row["scenario_id"],
        "starts_at_s" => activity_raw_start(row) || 0.0,
        "ends_at_s" => activity_raw_end(row),
        "execution_uncertainty_status" => entry["execution_uncertainty_status"],
        "execution_uncertainty" => entry["execution_uncertainty"],
        "timing_3sigma_s" => entry["timing_3sigma_s"],
        "delta_v_3sigma_km_s" => entry["delta_v_3sigma_km_s"],
        "delta_v_3sigma_magnitude_km_s" => entry["delta_v_3sigma_magnitude_km_s"],
        "execution_uncertainty_source" => entry["execution_uncertainty_source"],
        "required_operator_action" => row["required_operator_action"],
        "cadence_import_status" => row["cadence_import_status"],
        "timeline_id" => explicit_timeline_id(row),
        "maneuver_id" => row["maneuver_id"],
        "derivation_reasons" => ["realized_maneuver_uncertainty"],
        "feedback_source" => source_path,
        "feedback_scope" => "realized_feedback",
        "feedback_key" => activity_id,
        "trust_boundary" => operator_review_trust_boundary(row)
      }
      |> compact_map()
    end
  end

  defp realized_contact_feedback_events(row, source_path) do
    [
      realized_contact_success_feedback_event(row, source_path),
      realized_station_throughput_feedback_event(row, source_path)
    ]
    |> Enum.reject(&is_nil/1)
  end

  defp realized_contact_success_feedback_event(row, source_path) do
    case contact_success_value(row) do
      value when is_number(value) and value < 1.0 ->
        %{
          "type" => "contact_success_feedback",
          "ground_station_id" => Map.get(row, "ground_station_id") || Map.get(row, "station_id"),
          "activity_id" => realized_feedback_activity_id(row),
          "scenario_id" => row["scenario_id"],
          "starts_at_s" => activity_raw_start(row) || 0.0,
          "ends_at_s" => activity_raw_end(row),
          "contact_success_factor" => clamp_unit_interval(value),
          "contact_result" => provider_result_artifact_value(row["contact_result"]),
          "required_operator_action" => row["required_operator_action"],
          "timeline_id" => explicit_timeline_id(row),
          "derivation_reasons" => ["realized_contact_feedback"],
          "feedback_source" => source_path,
          "feedback_scope" => "realized_feedback",
          "feedback_key" => Map.get(row, "ground_station_id") || Map.get(row, "station_id"),
          "trust_boundary" => operator_review_trust_boundary(row)
        }
        |> put_feedback_weight_fields(row)
        |> compact_map()

      _value ->
        nil
    end
  end

