  defp operator_review_realized_feedback_rows(rows) do
    rows
    |> Enum.filter(&(&1["review_type"] == "realized_feedback"))
    |> Enum.map(fn row ->
      source =
        row
        |> Map.get("source_feedback", row)
        |> stringify_keys()

      feedback_status = row["feedback_status"] || source["status"]
      realized_status = row["realized_status"] || source["realized_status"] || row["status"]

      source
      |> put_if_present("feedback_status", feedback_status)
      |> put_if_present("status", realized_status)
      |> put_operator_review_row_fallback(row, "activity_id")
      |> put_operator_review_row_fallback(row, "id", "activity_id")
      |> put_operator_review_row_fallback(row, "timeline_id", "timeline_identity")
      |> put_operator_review_row_fallback(row, "scenario_id")
      |> put_operator_review_row_fallback(row, "ground_station_id")
      |> put_operator_review_row_fallback(row, "ground_station_id", "planned_ground_station_id")
      |> put_operator_review_row_fallback(row, "ground_station_id", "realized_ground_station_id")
      |> put_operator_review_row_fallback(row, "target_id")
      |> put_operator_review_row_fallback(row, "target_id", "planned_target_id")
      |> put_operator_review_row_fallback(row, "target_id", "realized_target_id")
      |> put_operator_review_row_fallback(row, "contact_success")
      |> put_operator_review_row_fallback(row, "contact_success_factor")
      |> put_operator_review_row_fallback(row, "contact_result")
      |> put_operator_review_row_fallback(row, "observation_success")
      |> put_operator_review_row_fallback(row, "observation_success_factor")
      |> put_operator_review_row_fallback(row, "observation_result")
      |> put_operator_review_row_fallback(row, "image_quality_score")
      |> put_operator_review_row_fallback(row, "product_quality_score")
      |> put_operator_review_row_fallback(row, "quality_score")
      |> put_operator_review_row_fallback(row, "image_quality_status")
      |> put_operator_review_row_fallback(row, "product_quality_status")
      |> put_operator_review_row_fallback(row, "quality_status")
      |> put_operator_review_row_fallback(row, "image_quality_source")
      |> put_operator_review_row_fallback(row, "product_quality_source")
      |> put_operator_review_row_fallback(row, "quality_source")
      |> put_operator_review_row_fallback(row, "cloud_cover_fraction")
      |> put_operator_review_row_fallback(row, "cloud_fraction")
      |> put_operator_review_row_fallback(row, "cloud_cover")
      |> put_operator_review_row_fallback(row, "blur_score")
      |> put_operator_review_row_fallback(row, "image_blur_score")
      |> put_operator_review_row_fallback(row, "sharpness_loss_fraction")
      |> put_operator_review_row_fallback(row, "command_success")
      |> put_operator_review_row_fallback(row, "command_success_factor")
      |> put_operator_review_row_fallback(row, "command_result")
      |> put_operator_review_row_fallback(row, "maneuver_success")
      |> put_operator_review_row_fallback(row, "maneuver_success_factor")
      |> put_operator_review_row_fallback(row, "maneuver_result")
      |> put_operator_review_row_fallback(row, "execution_uncertainty")
      |> put_operator_review_row_fallback(row, "execution_uncertainty_status")
      |> put_operator_review_row_fallback(row, "timing_3sigma_s")
      |> put_operator_review_row_fallback(row, "delta_v_3sigma_km_s")
      |> put_operator_review_row_fallback(row, "delta_v_3sigma_magnitude_km_s")
      |> put_operator_review_row_fallback(row, "execution_uncertainty_source")
      |> put_operator_review_row_fallback(row, "actual_throughput_mb")
      |> put_operator_review_row_fallback(row, "estimated_throughput_mb")
      |> put_operator_review_row_fallback(row, "required_downlink_mb")
      |> put_operator_review_row_fallback(row, "completed_fraction")
      |> put_operator_review_row_fallback(row, "feedback_weight")
      |> put_operator_review_row_fallback(row, "feedback_weight_source")
      |> put_operator_review_row_fallback(row, "feedback_sample_weight")
      |> put_operator_review_row_fallback(row, "feedback_sample_weight_source")
      |> put_operator_review_row_fallback(row, "sample_weight")
      |> put_operator_review_row_fallback(row, "sample_weight_source")
      |> put_operator_review_row_fallback(row, "confidence_weight")
      |> put_operator_review_row_fallback(row, "confidence_weight_source")
      |> put_if_present("type", operator_review_realized_feedback_type(row, source))
      |> put_if_present("_operator_review_feedback_status", feedback_status)
      |> put_if_present(
        "_operator_review_match_strategy",
        row["match_strategy"] || source["match_strategy"]
      )
      |> put_if_present(
        "_operator_review_realized_match_count",
        row["realized_match_count"] || source["realized_match_count"]
      )
      |> put_if_present(
        "_operator_review_invalid_realized_feedback_input",
        row["invalid_realized_feedback_input"] || source["invalid_realized_feedback_input"]
      )
      |> put_if_present(
        "_operator_review_invalid_activity_input",
        row["invalid_activity_input"] || source["invalid_activity_input"]
      )
    end)
  end

  defp operator_review_realized_feedback_type(row, source) do
    row["activity_type"] || source["activity_type"] || source["planned_type"] ||
      source["realized_type"] ||
      feedback_kind_activity_type(row["feedback_kind"] || source["feedback_kind"])
  end

  defp feedback_kind_activity_type("observation"), do: "observe"
  defp feedback_kind_activity_type("contact"), do: "contact"
  defp feedback_kind_activity_type("command"), do: "command"
  defp feedback_kind_activity_type("maneuver"), do: "maneuver"
  defp feedback_kind_activity_type(_kind), do: nil

  defp put_operator_review_row_fallback(source, row, field, row_field \\ nil) do
    row_field = row_field || field

    case Map.get(source, field) do
      value when value in [nil, ""] -> put_if_present(source, field, row[row_field])
      _value -> source
    end
  end

  defp operator_review_contact_feedback_row?(row) do
    operator_review_feedback_row_usable?(row) and
      (realized_contact_feedback?(row) or
         (realized_feedback_activity_id(row) not in [nil, ""] and
            (Map.get(row, "ground_station_id") || Map.get(row, "station_id")) not in [nil, ""] and
            not is_nil(unit_interval_number_or_nil(row["contact_success_factor"]))))
  end

  defp operator_review_observation_feedback_row?(row) do
    operator_review_feedback_row_usable?(row) and
      (realized_observation_feedback?(row) or
         ((Map.get(row, "target_id") || Map.get(row, "id")) not in [nil, ""] and
            not is_nil(unit_interval_number_or_nil(row["observation_success_factor"]))))
  end

  defp operator_review_command_feedback_row?(row) do
    operator_review_feedback_row_usable?(row) and
      (realized_command_feedback?(row) or
         (realized_feedback_activity_id(row) not in [nil, ""] and
            not is_nil(unit_interval_number_or_nil(row["command_success_factor"]))))
  end

  defp operator_review_maneuver_feedback_row?(row) do
    operator_review_feedback_row_usable?(row) and
      (realized_maneuver_feedback?(row) or
         (realized_feedback_activity_id(row) not in [nil, ""] and
            (not is_nil(unit_interval_number_or_nil(row["maneuver_success_factor"])) or
               maneuver_review_execution_uncertainty_entry(row) != %{})))
  end

  defp operator_review_feedback_row_usable?(%{
         "_operator_review_invalid_realized_feedback_input" => true
       }),
       do: false

  defp operator_review_feedback_row_usable?(%{"_operator_review_invalid_activity_input" => true}),
    do: false

  defp operator_review_feedback_row_usable?(%{
         "_operator_review_match_strategy" => "ambiguous_timeline_id"
       }),
       do: false

  defp operator_review_feedback_row_usable?(%{"_operator_review_realized_match_count" => count})
       when is_integer(count) and count > 1,
       do: false

  defp operator_review_feedback_row_usable?(%{"_operator_review_feedback_status" => status})
       when status in ["planned_only", "realized_only"],
       do: false

  defp operator_review_feedback_row_usable?(_row), do: true

  defp operator_review_operational_timeline_contact_success_value(row) do
    case unit_interval_number_or_nil(row["contact_success_factor"]) do
      value when is_number(value) -> value
      _value -> contact_success_value(row)
    end
  end

  defp operator_review_operational_timeline_observation_success_value(row) do
    case unit_interval_number_or_nil(row["observation_success_factor"]) do
      value when is_number(value) -> value
      _value -> observation_success_value(row)
    end
  end

  defp strategy_operational_feedback_provenance(
         prior_plan,
         mission_state,
         candidate_refresh,
         explicit_operational_feedback,
         realized_activities_operational_feedback,
         operational_feedback
       ) do
    prior_source_feedback = prior_plan_timeline_feedback_operational_feedback(prior_plan)

    prior_planned_activity_feedback =
      prior_plan_planned_activity_operational_feedback(prior_plan)

    prior_proposed_contact_feedback =
      prior_plan_proposed_contact_operational_feedback(prior_plan)

    prior_realized_activity_feedback =
      prior_plan_realized_activity_operational_feedback(prior_plan)

    prior_operational_timeline_feedback =
      prior_plan_operational_timeline_operational_feedback(prior_plan)

    prior_command_window_feedback = prior_plan_command_window_operational_feedback(prior_plan)
    prior_maneuver_review_feedback = prior_plan_maneuver_review_operational_feedback(prior_plan)

    prior_cadence_import_source_feedback =
      prior_plan_cadence_import_source_operational_feedback(prior_plan)

    prior_cadence_import_feedback = prior_plan_cadence_import_operational_feedback(prior_plan)

    prior_operator_review_source_feedback =
      prior_plan_operator_review_source_operational_feedback(prior_plan)

    prior_operator_review_feedback = prior_plan_operator_review_operational_feedback(prior_plan)
    mission_source_feedback = mission_state_timeline_feedback_operational_feedback(mission_state)

    mission_planned_activity_feedback =
      mission_state_planned_activity_operational_feedback(mission_state)

    mission_proposed_contact_feedback =
      mission_state_proposed_contact_operational_feedback(mission_state)

    mission_realized_activity_feedback =
      mission_state_realized_activity_operational_feedback(mission_state, prior_plan)

    mission_operational_timeline_feedback =
      mission_state_operational_timeline_operational_feedback(mission_state)

    mission_command_window_feedback =
      mission_state_command_window_operational_feedback(mission_state)

    mission_maneuver_review_feedback =
      mission_state_maneuver_review_operational_feedback(mission_state)

    mission_cadence_import_source_feedback =
      mission_state_cadence_import_source_operational_feedback(mission_state)

    mission_cadence_import_feedback =
      mission_state_cadence_import_operational_feedback(mission_state)

    mission_operator_review_source_feedback =
      mission_state_operator_review_source_operational_feedback(mission_state)

    mission_operator_review_feedback =
      mission_state_operator_review_operational_feedback(mission_state)

    prior_feedback = prior_plan_direct_operational_feedback(prior_plan)
    mission_feedback = mission_state_direct_operational_feedback(mission_state)
    candidate_refresh_feedback = candidate_refresh_operational_feedback(candidate_refresh)
    realized_activities = Map.get(mission_state, "realized_activities", [])

    sources =
      [
        operational_feedback_source(
          "prior_plan.source_timeline_feedback_report.operational_feedback",
          prior_source_feedback,
          prior_plan_timeline_feedback_source_metadata(prior_plan)
        ),
        operational_feedback_source(
          "prior_plan.planned_activity",
          prior_planned_activity_feedback,
          prior_plan_planned_activity_source_metadata(prior_plan)
        ),
        operational_feedback_source(
          "prior_plan.proposed_contact",
          prior_proposed_contact_feedback,
          prior_plan_proposed_contact_source_metadata(prior_plan)
        ),
        operational_feedback_source(
          "prior_plan.realized_activity",
          prior_realized_activity_feedback,
          prior_plan_realized_activity_source_metadata(prior_plan)
        ),
        operational_feedback_source(
          "prior_plan.operational_timeline_report.rows",
          prior_operational_timeline_feedback,
          prior_plan_operational_timeline_source_metadata(prior_plan)
        ),
        operational_feedback_source(
          "prior_plan.command_window_report.rows",
          prior_command_window_feedback,
          prior_plan_command_window_source_metadata(prior_plan)
