  defp operational_timeline_feedback_trust_boundaries(rows) do
    rows
    |> Enum.reduce(%{}, fn row, boundaries ->
      trust_boundary = operator_review_trust_boundary(row)

      if trust_boundary in [nil, ""] do
        boundaries
      else
        boundaries
        |> put_timeline_feedback_trust_boundary(
          "command_success_rate",
          realized_feedback_activity_id(row),
          trust_boundary,
          operator_review_command_feedback_row?(row)
        )
        |> put_timeline_feedback_trust_boundary(
          "maneuver_success_rate",
          realized_feedback_activity_id(row),
          trust_boundary,
          operator_review_maneuver_feedback_row?(row)
        )
        |> put_timeline_feedback_trust_boundary(
          "contact_success_rate",
          Map.get(row, "ground_station_id") || Map.get(row, "station_id"),
          trust_boundary,
          operator_review_contact_feedback_row?(row)
        )
        |> put_timeline_feedback_trust_boundary(
          "station_throughput_factor",
          Map.get(row, "ground_station_id") || Map.get(row, "station_id"),
          trust_boundary,
          operator_review_contact_feedback_row?(row) and
            not is_nil(station_throughput_value(row))
        )
        |> put_timeline_feedback_trust_boundary(
          "observation_success_rate",
          Map.get(row, "target_id"),
          trust_boundary,
          operator_review_observation_feedback_row?(row)
        )
      end
    end)
    |> case do
      boundaries when boundaries == %{} -> nil
      boundaries -> boundaries
    end
  end

  defp put_timeline_feedback_trust_boundary(boundaries, _field, _key, _trust_boundary, false),
    do: boundaries

  defp put_timeline_feedback_trust_boundary(boundaries, _field, key, _trust_boundary, _include?)
       when key in [nil, ""],
       do: boundaries

  defp put_timeline_feedback_trust_boundary(boundaries, field, key, trust_boundary, _include?) do
    put_feedback_trust_boundary(boundaries, field, key, [trust_boundary])
  end

