  defp merge_feedback_trust_boundary_maps(boundary_maps) do
    boundary_maps
    |> List.wrap()
    |> Enum.filter(&is_map/1)
    |> Enum.reduce(%{}, fn boundaries, merged ->
      boundaries
      |> stringify_keys()
      |> Enum.reduce(merged, fn {field, key_boundaries}, merged ->
        if is_map(key_boundaries) do
          Enum.reduce(key_boundaries, merged, fn {key, trust_boundaries}, merged ->
            put_feedback_trust_boundary(merged, field, key, List.wrap(trust_boundaries))
          end)
        else
          merged
        end
      end)
    end)
  end

