  defp operational_feedback_provenance_trust_boundaries(%{} = provenance) do
    provenance = stringify_keys(provenance)

    direct_boundaries = [
      Map.get(provenance, "trust_boundary"),
      Map.get(provenance, "trust_boundaries")
    ]

    nested_boundaries =
      provenance
      |> Map.get("sources", [])
      |> List.wrap()
      |> Enum.flat_map(fn
        %{} = source ->
          source = stringify_keys(source)

          [
            source["trust_boundary"],
            source["trust_boundaries"]
          ]
          |> List.flatten()

        _source ->
          []
      end)

    (direct_boundaries ++ nested_boundaries)
    |> List.flatten()
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp operator_review_feedback_weight_evidence(row) do
    row = stringify_keys(row)

    source =
      [
        "source_feedback",
        "source_operational_timeline",
        "source_command_window",
        "source_maneuver_review"
      ]
      |> Enum.find_value(fn field ->
        case Map.get(row, field) do
          %{} = source -> stringify_keys(source)
          _source -> nil
        end
      end)

    Map.merge(row, source || %{})
  end

  defp operator_review_rows_invalid_unit_interval_feedback_sections(rows) do
    rows
    |> Enum.map(&operator_review_feedback_weight_evidence/1)
    |> Enum.with_index(1)
    |> Enum.flat_map(fn {row, row_index} ->
      row
      |> operator_review_unit_interval_feedback_values()
      |> Enum.flat_map(fn {field, value} ->
        case unit_interval_number_status(value) do
          {:ok, _value} ->
            []

          :missing ->
            []

          {:invalid_number, number} ->
            [
              operator_review_invalid_unit_interval_section(
                row,
                row_index,
                field,
                "value_must_be_between_0_and_1",
                "invalid_feedback_value",
                number
              )
            ]

          {:invalid_shape, shape} ->
            [
              operator_review_invalid_unit_interval_section(
                row,
                row_index,
                field,
                "entry_must_be_unit_interval_number",
                "invalid_feedback_shape",
                stringify_keys(shape)
              )
            ]
        end
      end)
    end)
    |> Enum.uniq()
  end

  defp operator_review_invalid_unit_interval_section(
         row,
         row_index,
         field,
         reason,
         invalid_key,
         invalid_value
       ) do
    %{
      "field" => "operator_review.rows.#{field}",
      "reason" => reason,
      invalid_key => invalid_value,
      "row_id" => row["id"] || row["activity_id"] || row["timeline_id"],
      "row_index" => row_index
    }
    |> compact_map()
  end

  defp operator_review_unit_interval_feedback_values(row) do
    [
      {"contact_success_factor", row["contact_success_factor"]},
      {"observation_success_factor", row["observation_success_factor"]},
