  defp mission_state_source_reports_or_reports(mission_state, report_fun) do
    mission_state
    |> report_fun.()
    |> mission_state_report_or_reports()
  end

  defp mission_state_source_report_key_entries(mission_state, key) do
    mission_state = stringify_keys(mission_state || %{})

    mission_state
    |> Map.get(key)
    |> mission_state_source_report_entries("mission_state.#{key}")
  end

  defp mission_state_source_reports_with_result_artifact_reports(
         mission_state,
         direct_source_fun,
         report_keys
       ) do
    case direct_source_fun.(mission_state) do
      [] ->
        Enum.flat_map(
          report_keys,
          &mission_state_result_artifact_embedded_reports(mission_state, &1)
        )

      reports ->
        reports
    end
  end

  defp put_missing_candidate_refresh_result_artifact_source_aliases(source_reports, mission_state) do
    candidate_refresh_source_report_input_fields()
    |> Enum.reject(fn {source_key, _canonical_key} ->
      source_key in [
        "source_timeline_feedback_report",
        "source_operational_timeline_report"
      ]
    end)
    |> Enum.reduce(source_reports, fn {source_key, canonical_key}, acc ->
      if source_report_input_present?(Map.get(acc, source_key)) do
        acc
      else
        reports =
          [source_key, canonical_key]
          |> Enum.flat_map(&mission_state_result_artifact_embedded_reports(mission_state, &1))

        case mission_state_report_or_reports(reports) do
          nil -> acc
          value -> Map.put(acc, source_key, value)
        end
      end
    end)
  end

  defp mission_state_report_or_reports(reports_with_sources) do
    reports =
      reports_with_sources
      |> List.wrap()
      |> Enum.map(fn {report, _source_path} -> stringify_keys(report) end)

    case reports do
      [] -> nil
      [report] -> report
      reports -> reports
    end
  end

  defp non_empty_report(%{} = report) when map_size(report) > 0, do: report
  defp non_empty_report(_report), do: nil

  defp operational_feedback_source(source, feedback, extra \\ %{})

  defp operational_feedback_source(_source, nil, _extra), do: nil

  defp operational_feedback_source(source, feedback, extra) when not is_map(feedback) do
    extra
    |> Map.merge(%{
      "source" => source,
      "input_keys" => ["invalid_operational_feedback_input"],
      "invalid_operational_feedback_input" => true,
      "invalid_operational_feedback_input_reason" =>
        "strategy_operational_feedback_must_be_object",
      "source_operational_feedback" => %{"invalid_feedback_shape" => stringify_keys(feedback)}
    })
    |> compact_map()
  end

  defp operational_feedback_source(source, feedback, extra) do
    feedback = stringify_keys(feedback)
    input_keys = operational_feedback_data_keys(feedback)

    invalid_sections =
      (invalid_operational_feedback_sections(feedback) ++
         Map.get(extra, "invalid_operational_feedback_sections", []))
      |> Enum.uniq()

    if input_keys == [] and invalid_sections == [] do
      nil
    else
      feedback
      |> trust_boundary_summary()
      |> Map.merge(extra)
      |> Map.merge(%{
        "source" => source,
        "input_keys" => input_keys
      })
      |> maybe_put_invalid_operational_feedback_sections(invalid_sections)
      |> compact_map()
    end
  end

  defp operational_feedback_replay_source(source, feedback, extra, rows) do
    invalid_sections = replay_operational_feedback_invalid_sections(rows)

    source
    |> operational_feedback_source(feedback, extra)
    |> case do
      nil when invalid_sections == [] ->
        nil

      nil ->
        extra
        |> Map.merge(%{"source" => source, "input_keys" => []})
        |> put_replay_invalid_operational_feedback_sections(invalid_sections)
        |> compact_map()

      source_map when invalid_sections == [] ->
        source_map

      source_map ->
        source_map
        |> put_replay_invalid_operational_feedback_sections(invalid_sections)
        |> compact_map()
    end
  end

  defp replay_operational_feedback_invalid_sections(rows) do
    rows
    |> Enum.map(&stringify_keys/1)
    |> Enum.flat_map(&replay_row_invalid_operational_feedback_sections/1)
  end

  defp replay_row_invalid_operational_feedback_sections(row) do
    feedback = Map.get(row, "source_operational_feedback")
    context = replay_operational_feedback_row_context(row)

    case feedback do
      %{} = feedback ->
        feedback
        |> replay_source_operational_feedback_invalid_sections()
        |> Enum.map(&Map.merge(&1, context))

      feedback ->
        [
          %{
            "field" => "source_operational_feedback",
            "reason" => "strategy_operational_feedback_must_be_object",
            "invalid_feedback_shape" => stringify_keys(feedback)
          }
          |> Map.merge(context)
        ]
    end
  end

  defp replay_source_operational_feedback_invalid_sections(feedback) do
    feedback = stringify_keys(feedback)

    wrapped_sections =
      feedback
      |> Map.get("invalid_feedback_sections", [])
      |> List.wrap()
      |> Enum.filter(&is_map/1)
      |> Enum.map(&stringify_keys/1)

    wrapped_shape_sections =
      case Map.get(feedback, "invalid_feedback_shape") do
        nil ->
          []

        invalid_feedback_shape ->
          [
            %{
              "field" => "source_operational_feedback",
              "reason" => "strategy_operational_feedback_must_be_object",
              "invalid_feedback_shape" => stringify_keys(invalid_feedback_shape)
            }
          ]
      end

    (wrapped_sections ++ wrapped_shape_sections ++ invalid_operational_feedback_sections(feedback))
    |> Enum.uniq()
  end

  defp replay_operational_feedback_row_context(row) do
    %{
      "row_id" => row["id"] || row["source_review_row_id"],
      "source_review_row_id" => row["source_review_row_id"],
      "review_type" => row["review_type"],
      "source_review_type" => row["source_review_type"],
      "action" => row["action"] || row["required_operator_action"],
      "import_action" => row["import_action"]
    }
    |> compact_map()
  end

  defp single_operational_feedback_trust_boundary(%{} = provenance) do
    provenance
    |> operational_feedback_provenance_trust_boundaries()
    |> case do
      [trust_boundary] -> trust_boundary
      _boundaries -> nil
    end
  end

  defp operational_feedback_trust_boundary_context(%{} = provenance) do
    %{
      "default" => single_operational_feedback_trust_boundary(provenance),
      "field_keys" => operational_feedback_trust_boundary_field_keys(provenance)
    }
  end

  defp operational_feedback_trust_boundary_context(_provenance), do: %{}

  defp operational_feedback_trust_boundary_field_keys(%{} = provenance) do
    effective_sources = Map.get(provenance, "effective_sources", %{})

    provenance
    |> Map.get("sources", [])
    |> Enum.reduce(%{}, fn source, field_keys ->
      source = stringify_keys(source)
      source_name = Map.get(source, "source")

      source
      |> source_feedback_trust_boundaries()
      |> Enum.reduce(field_keys, fn boundaries, field_keys ->
        merge_feedback_trust_boundaries(field_keys, boundaries, source_name, effective_sources)
      end)
    end)
  end

  defp source_feedback_trust_boundaries(source) do
    direct =
      case Map.get(source, "feedback_trust_boundaries") do
        %{} = boundaries -> [boundaries]
        _boundaries -> []
      end

    provenance_direct =
      source
      |> Map.get("source_operational_feedback_provenance", %{})
      |> stringify_keys()
      |> Map.get("feedback_trust_boundaries")
      |> case do
        %{} = boundaries -> [boundaries]
        _boundaries -> []
      end

    nested =
      source
      |> Map.get("source_operational_feedback_provenance", %{})
      |> stringify_keys()
      |> Map.get("sources", [])
      |> Enum.flat_map(fn nested_source ->
        case nested_source |> stringify_keys() |> Map.get("feedback_trust_boundaries") do
          %{} = boundaries -> [boundaries]
          _boundaries -> []
        end
      end)

    direct ++ provenance_direct ++ nested
  end

  defp merge_feedback_trust_boundaries(field_keys, boundaries, source_name, effective_sources) do
    boundaries
    |> stringify_keys()
    |> Enum.reduce(field_keys, fn {field, key_boundaries}, field_keys ->
      if effective_feedback_source?(field, source_name, effective_sources) and
           is_map(key_boundaries) do
        normalized_key_boundaries =
          key_boundaries
          |> stringify_keys()
          |> Enum.reduce(%{}, fn {key, trust_boundaries}, normalized ->
            case unique_feedback_trust_boundary(trust_boundaries) do
              trust_boundary when is_binary(trust_boundary) ->
                Map.put(normalized, key, trust_boundary)

              _trust_boundary ->
                normalized
            end
          end)

        if map_size(normalized_key_boundaries) == 0 do
          field_keys
        else
          Map.update(field_keys, field, normalized_key_boundaries, fn existing ->
            Map.merge(existing, normalized_key_boundaries)
          end)
        end
      else
        field_keys
      end
    end)
  end

  defp effective_feedback_source?(_field, _source_name, effective_sources)
       when not is_map(effective_sources),
       do: true

  defp effective_feedback_source?(field, source_name, effective_sources) do
    case Map.get(effective_sources, field) do
      nil -> true
      ^source_name -> true
      _other_source -> false
    end
  end

  defp unique_feedback_trust_boundary(trust_boundaries) do
    trust_boundaries
    |> List.wrap()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [trust_boundary] -> trust_boundary
      _trust_boundaries -> nil
    end
  end

  defp feedback_event_trust_boundary(
         %{"field_keys" => field_keys, "default" => default},
         field,
         key
       ) do
    encoded_key = encode_value(key) || "default"

    case get_in(field_keys, [field, encoded_key]) do
      trust_boundary when is_binary(trust_boundary) and trust_boundary != "" -> trust_boundary
      _trust_boundary -> default
    end
  end

  defp feedback_event_trust_boundary(trust_boundary, _field, _key)
       when is_binary(trust_boundary) and trust_boundary != "",
       do: trust_boundary

  defp feedback_event_trust_boundary(_trust_boundary, _field, _key), do: nil

  defp operational_feedback_field_from_source("operational_feedback." <> field), do: field
  defp operational_feedback_field_from_source(field), do: field

  defp operational_feedback_override?(nil), do: false
  defp operational_feedback_override?(feedback) when not is_map(feedback), do: true

  defp operational_feedback_override?(feedback),
    do:
      operational_feedback_data_keys(feedback) != [] or
        invalid_operational_feedback_sections(feedback) != []

  defp maybe_put_invalid_operational_feedback_sections(source, []), do: source

  defp maybe_put_invalid_operational_feedback_sections(source, invalid_sections) do
    put_replay_invalid_operational_feedback_sections(source, invalid_sections)
  end

  defp put_replay_invalid_operational_feedback_sections(source, invalid_sections) do
    invalid_sections =
      (Map.get(source, "invalid_operational_feedback_sections", []) ++ invalid_sections)
      |> Enum.uniq()

    source_operational_feedback =
      source
      |> Map.get("source_operational_feedback", %{})
      |> Map.merge(%{"invalid_feedback_sections" => invalid_sections})

    source
    |> Map.put(
      "input_keys",
      (Map.get(source, "input_keys", []) ++ ["invalid_operational_feedback_input"])
      |> Enum.uniq()
    )
    |> Map.put("invalid_operational_feedback_input", true)
    |> Map.put(
      "invalid_operational_feedback_input_reason",
      "operational_feedback_sections_invalid"
    )
    |> Map.put("invalid_operational_feedback_sections", invalid_sections)
    |> Map.put("source_operational_feedback", source_operational_feedback)
  end

  defp invalid_operational_feedback_sections(feedback) when is_map(feedback) do
    feedback = stringify_keys(feedback)

    unit_interval_map_fields = unit_interval_operational_feedback_fields()

    nonnegative_map_fields = [
      "downlink_demand_mb",
      "target_priority_overrides"
    ]

    scalar_map_fields =
      unit_interval_map_fields ++ nonnegative_map_fields

    string_list_map_fields = ["downlink_demand_sources"]
    string_map_fields = ["image_quality_status", "image_quality_source"]

    nested_map_fields = [
      "maneuver_execution_uncertainty",
      "resource_margin_overrides",
      "resource_availability_overrides",
      "availability_overrides"
    ]

    map_fields =
      scalar_map_fields ++ string_list_map_fields ++ string_map_fields ++ nested_map_fields

    invalid_key_sections =
      map_fields
      |> Enum.flat_map(&invalid_operational_feedback_key_sections(feedback, &1))

    scalar_sections =
      scalar_map_fields
      |> Enum.flat_map(&invalid_operational_feedback_field_sections(feedback, &1))

    unit_interval_entry_sections =
      unit_interval_map_fields
      |> Enum.flat_map(&invalid_unit_interval_operational_feedback_sections(feedback, &1))

    nonnegative_entry_sections =
      nonnegative_map_fields
      |> Enum.flat_map(&invalid_nonnegative_operational_feedback_sections(feedback, &1))

    string_list_sections =
      string_list_map_fields
      |> Enum.flat_map(&invalid_string_list_operational_feedback_sections(feedback, &1))

    string_sections =
      string_map_fields
      |> Enum.flat_map(&invalid_string_operational_feedback_sections(feedback, &1))

    nested_sections =
      nested_map_fields
      |> Enum.flat_map(&invalid_nested_operational_feedback_sections(feedback, &1))

    (invalid_key_sections ++
       scalar_sections ++
       unit_interval_entry_sections ++
       nonnegative_entry_sections ++
       string_list_sections ++
       string_sections ++
       nested_sections)
    |> Enum.sort_by(&{&1["field"], Map.get(&1, "key", ""), &1["reason"]})
  end

  defp invalid_operational_feedback_sections(_feedback), do: []

  defp unit_interval_operational_feedback_fields do
    [
      "contact_success_rate",
      "observation_success_rate",
      "image_quality_score",
      "cloud_cover_fraction",
      "blur_score",
      "maneuver_success_rate",
      "command_success_rate",
      "station_throughput_factor"
    ]
  end

  defp invalid_operational_feedback_key_sections(feedback, field) do
    case Map.get(feedback, field) do
      %{} = entries ->
        entries
        |> stringify_keys()
        |> Enum.flat_map(fn {key, _value} ->
          if operational_feedback_key?(key) do
            []
          else
            [
              %{
                "field" => field,
                "key" => invalid_operational_feedback_key_label(key),
                "reason" => "key_must_be_stable_id"
              }
            ]
          end
        end)

      _entries ->
        []
    end
  end

  defp invalid_operational_feedback_key_label(key) when is_binary(key), do: key
  defp invalid_operational_feedback_key_label(key), do: inspect(key)

  defp invalid_unit_interval_operational_feedback_sections(feedback, field) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        []

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn {key, value} ->
          case numeric_or_nil(value) do
            number when is_number(number) and number >= 0.0 and number <= 1.0 ->
              []

            number when is_number(number) ->
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "value_must_be_between_0_and_1",
                  "invalid_feedback_value" => number
                }
              ]

            _value ->
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "entry_must_be_unit_interval_number",
                  "invalid_feedback_shape" => stringify_keys(value)
                }
              ]
          end
        end)
    end
  end

  defp invalid_operational_feedback_field_sections(feedback, field) do
    if Map.has_key?(feedback, field) and not is_map(Map.get(feedback, field)) do
      [
        %{
          "field" => field,
          "reason" => "field_must_be_object",
          "invalid_feedback_shape" => stringify_keys(Map.get(feedback, field))
        }
      ]
    else
      []
    end
  end

  defp invalid_nonnegative_operational_feedback_sections(feedback, field) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        []

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn {key, value} ->
          case numeric_or_nil(value) do
            number when is_number(number) and number >= 0.0 ->
              []

            number when is_number(number) ->
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "entry_must_be_nonnegative_number",
                  "invalid_feedback_shape" => number
                }
              ]

            _value ->
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "entry_must_be_number",
                  "invalid_feedback_shape" => stringify_keys(value)
                }
              ]
          end
        end)
    end
  end

  defp invalid_string_list_operational_feedback_sections(feedback, field) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        [
          %{
            "field" => field,
            "reason" => "field_must_be_object",
            "invalid_feedback_shape" => stringify_keys(Map.get(feedback, field))
          }
        ]

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn
          {key, values} when is_list(values) ->
            if Enum.all?(values, &valid_feedback_source_string?/1) do
              []
            else
              [
                %{
                  "field" => field,
                  "key" => key,
                  "reason" => "entry_must_be_string_array",
                  "invalid_feedback_shape" => stringify_keys(values)
                }
              ]
            end

          {key, value} ->
            [
              %{
                "field" => field,
                "key" => key,
                "reason" => "entry_must_be_string_array",
                "invalid_feedback_shape" => stringify_keys(value)
              }
            ]
        end)
    end
  end

  defp invalid_string_operational_feedback_sections(feedback, field) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        [
          %{
            "field" => field,
            "reason" => "field_must_be_object",
            "invalid_feedback_shape" => stringify_keys(Map.get(feedback, field))
          }
        ]

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn
          {_key, value} when is_binary(value) and value != "" ->
            []

          {_key, value} when is_atom(value) and not is_nil(value) ->
            []

          {key, value} ->
            [
              %{
                "field" => field,
                "key" => key,
                "reason" => "entry_must_be_string",
                "invalid_feedback_shape" => stringify_keys(value)
              }
            ]
        end)
    end
  end

  defp valid_feedback_source_string?(value) when is_binary(value), do: value != ""
  defp valid_feedback_source_string?(value) when is_atom(value), do: not is_nil(value)
  defp valid_feedback_source_string?(_value), do: false

  defp invalid_nested_operational_feedback_sections(feedback, field) do
    cond do
      not Map.has_key?(feedback, field) ->
        []

      not is_map(Map.get(feedback, field)) ->
        [
          %{
            "field" => field,
            "reason" => "field_must_be_object",
            "invalid_feedback_shape" => stringify_keys(Map.get(feedback, field))
          }
        ]

      true ->
        feedback
        |> Map.fetch!(field)
        |> stringify_keys()
        |> Enum.flat_map(fn
          {_key, %{}} ->
            []

          {key, value} ->
            [
              %{
                "field" => field,
                "key" => key,
                "reason" => "entry_must_be_object",
                "invalid_feedback_shape" => stringify_keys(value)
              }
            ]
        end)
    end
  end

  defp realized_activities_feedback_source(realized_activities, feedback, prior_plan)
       when is_list(realized_activities) do
    if realized_activities == [] do
      nil
    else
      realized_activities = Enum.map(realized_activities, &stringify_keys/1)

      feedback_realized_activities =
        Enum.reject(realized_activities, &invalid_realized_activity_feedback_input?/1)

      enriched_realized_activities =
        enrich_realized_activities_with_planned_context(feedback_realized_activities, prior_plan)

      input_keys = operational_feedback_data_keys(feedback)
      invalid_sections = invalid_realized_activity_feedback_sections(realized_activities)

      trust_boundaries =
        realized_activities
        |> Enum.flat_map(&realized_activity_trust_boundaries/1)
        |> Enum.uniq()
        |> Enum.sort()

      feedback_trust_boundaries =
        realized_activities_feedback_trust_boundaries(enriched_realized_activities)

      weighted_feedback_row_count = weighted_realized_feedback_row_count(realized_activities)
      feedback_weight_sources = realized_feedback_weight_sources(realized_activities)

      %{
        "source" => "mission_state.realized_activities",
        "input_keys" => input_keys,
        "realized_activity_count" => length(realized_activities),
        "trust_boundary_status" => if(trust_boundaries == [], do: "missing", else: "declared"),
        "trust_boundaries" => trust_boundaries,
        "feedback_trust_boundaries" =>
          if(feedback_trust_boundaries == %{}, do: nil, else: feedback_trust_boundaries),
        "weighted_feedback_row_count" =>
          if(weighted_feedback_row_count > 0, do: weighted_feedback_row_count),
        "feedback_weight_sources" =>
          if(feedback_weight_sources == [], do: nil, else: feedback_weight_sources)
      }
      |> maybe_put_invalid_operational_feedback_sections(invalid_sections)
      |> compact_map()
    end
  end

  defp realized_activities_feedback_source(_realized_activities, _feedback, _prior_plan), do: nil

  defp realized_activity_trust_boundaries(%{} = activity) do
    [
      Map.get(activity, "trust_boundary"),
      Map.get(activity, "trust_boundaries"),
      get_in(activity, ["provenance", "trust_boundary"]),
      get_in(activity, ["provenance", "trust_boundaries"])
    ]
    |> List.flatten()
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
  end

  defp realized_activity_trust_boundaries(_activity), do: []

  defp realized_activities_feedback_trust_boundaries(realized_activities) do
    Enum.reduce(realized_activities, %{}, fn activity, boundaries ->
      activity_boundaries = realized_activity_trust_boundaries(activity)

      if activity_boundaries == [] do
        boundaries
      else
        boundaries
        |> put_realized_contact_feedback_trust_boundaries(activity, activity_boundaries)
        |> put_realized_observation_feedback_trust_boundaries(activity, activity_boundaries)
        |> put_realized_maneuver_feedback_trust_boundaries(activity, activity_boundaries)
        |> put_realized_command_feedback_trust_boundaries(activity, activity_boundaries)
        |> put_realized_resource_feedback_trust_boundaries(activity, activity_boundaries)
      end
    end)
  end

  defp put_realized_contact_feedback_trust_boundaries(boundaries, activity, trust_boundaries) do
    station_id = Map.get(activity, "ground_station_id") || Map.get(activity, "station_id")

    boundaries =
      if station_id not in [nil, ""] and not is_nil(contact_success_value(activity)) do
        put_feedback_trust_boundary(
          boundaries,
          "contact_success_rate",
          station_id,
          trust_boundaries
        )
      else
        boundaries
      end

    boundaries =
      if station_id not in [nil, ""] and not is_nil(station_throughput_value(activity)) do
        put_feedback_trust_boundary(
          boundaries,
          "station_throughput_factor",
          station_id,
          trust_boundaries
        )
      else
        boundaries
      end

    case {downlink_activity?(activity), realized_downlink_demand_mb(activity)} do
      {true, value} when is_number(value) and value > 0.0 ->
        put_feedback_trust_boundary(
          boundaries,
          "downlink_demand_mb",
          station_id || "default",
          trust_boundaries
        )

      _value ->
        boundaries
    end
  end

  defp put_realized_observation_feedback_trust_boundaries(boundaries, activity, trust_boundaries) do
    target_id = Map.get(activity, "target_id")

    boundaries =
      [
        {"observation_success_rate", observation_success_value(activity)},
        {"image_quality_score", image_quality_score_value(activity)},
        {"image_quality_status", image_quality_status_value(activity)},
        {"image_quality_source", image_quality_source_value(activity)},
        {"cloud_cover_fraction", cloud_cover_fraction_value(activity)},
        {"blur_score", blur_score_value(activity)},
        {"target_priority_overrides", target_priority_override_value(activity)}
      ]
      |> Enum.reduce(boundaries, fn {field, value}, boundaries ->
        if target_id not in [nil, ""] and not is_nil(value) do
          put_feedback_trust_boundary(boundaries, field, target_id, trust_boundaries)
        else
          boundaries
        end
      end)

    case observation_downlink_demand_mb(activity) do
      value when is_number(value) and value > 0.0 ->
        put_feedback_trust_boundary(boundaries, "downlink_demand_mb", "default", trust_boundaries)

      _value ->
        boundaries
    end
  end

  defp put_realized_maneuver_feedback_trust_boundaries(boundaries, activity, trust_boundaries) do
    activity_id = realized_feedback_activity_id(activity)

    if activity_id not in [nil, ""] and not is_nil(maneuver_success_value(activity)) do
      put_feedback_trust_boundary(
        boundaries,
        "maneuver_success_rate",
        activity_id,
        trust_boundaries
      )
    else
      boundaries
    end
  end

  defp put_realized_command_feedback_trust_boundaries(boundaries, activity, trust_boundaries) do
    activity_id = realized_feedback_activity_id(activity)

    if activity_id not in [nil, ""] and not is_nil(command_success_value(activity)) do
      put_feedback_trust_boundary(
        boundaries,
        "command_success_rate",
        activity_id,
        trust_boundaries
      )
    else
      boundaries
    end
  end

  defp put_realized_resource_feedback_trust_boundaries(boundaries, activity, trust_boundaries) do
    spacecraft_id = resource_feedback_spacecraft_id(activity)

    if spacecraft_id in [nil, ""] do
      boundaries
    else
      boundaries =
        if realized_activity_resource_margins(activity) == %{} do
          boundaries
        else
          put_feedback_trust_boundary(
            boundaries,
            "resource_margin_overrides",
            spacecraft_id,
            trust_boundaries
          )
        end

      if realized_activity_resource_availability(activity) == %{} do
        boundaries
      else
        put_feedback_trust_boundary(
          boundaries,
          "resource_availability_overrides",
          spacecraft_id,
          trust_boundaries
        )
      end
    end
  end

  defp put_feedback_trust_boundary(boundaries, field, key, trust_boundaries) do
    encoded_key = encode_value(key) || "default"

    Map.update(boundaries, field, %{encoded_key => trust_boundaries}, fn field_boundaries ->
      Map.update(field_boundaries, encoded_key, trust_boundaries, fn existing ->
        (List.wrap(existing) ++ trust_boundaries)
        |> Enum.uniq()
        |> Enum.sort()
      end)
    end)
  end

  defp weighted_realized_feedback_row_count(realized_activities) do
    Enum.count(realized_activities, fn activity ->
      activity
      |> stringify_keys()
      |> realized_feedback_weight()
      |> is_number()
    end)
  end

  defp realized_feedback_weight_sources(realized_activities) do
    realized_activities
    |> Enum.flat_map(fn activity ->
      activity = stringify_keys(activity)

      if is_number(realized_feedback_weight(activity)) do
        activity
        |> realized_feedback_weight_source()
        |> List.wrap()
      else
        []
      end
    end)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp realized_feedback_weight(%{} = activity) do
    Enum.find_value(
      realized_feedback_weight_fields(),
      fn key ->
        case numeric_or_nil(Map.get(activity, key)) do
          weight when is_number(weight) and weight > 0.0 -> weight * 1.0
          _weight -> nil
        end
      end
    )
  end

  defp realized_feedback_weight_fields do
    ["feedback_weight", "feedback_sample_weight", "sample_weight", "confidence_weight"]
  end

  defp realized_feedback_weight_source(%{} = activity) do
    Enum.find_value(
      [
        "feedback_weight_source",
        "feedback_sample_weight_source",
        "sample_weight_source",
        "confidence_weight_source"
      ],
      fn key ->
        case Map.get(activity, key) do
          source when is_binary(source) and source != "" -> source
          _source -> nil
        end
      end
    )
  end

  defp operational_feedback_data_keys(feedback) do
    feedback
    |> normalize_operational_feedback()
    |> Enum.filter(fn {_key, value} -> operational_feedback_value_present?(value) end)
    |> Enum.map(fn {key, _value} -> key end)
    |> Enum.sort()
  end

  defp operational_feedback_value_present?(%{} = value), do: map_size(value) > 0
  defp operational_feedback_value_present?(_value), do: false

  defp trust_boundary_summary(%{} = source) do
    source = stringify_keys(source)

    trust_boundary =
      Map.get(source, "trust_boundary") || get_in(source, ["provenance", "trust_boundary"])

    feedback_trust_boundaries =
      case Map.get(source, "feedback_trust_boundaries") ||
             get_in(source, ["provenance", "feedback_trust_boundaries"]) do
        %{} = boundaries -> stringify_keys(boundaries)
        _boundaries -> nil
      end

    trust_boundaries =
      [
        trust_boundary,
        Map.get(source, "trust_boundaries"),
        get_in(source, ["provenance", "trust_boundaries"]),
        feedback_trust_boundary_values(feedback_trust_boundaries)
      ]
      |> List.flatten()
      |> Enum.filter(&(is_binary(&1) and &1 != ""))
      |> Enum.uniq()
      |> Enum.sort()

    singular_trust_boundary =
      case {trust_boundary, trust_boundaries} do
        {trust_boundary, _boundaries} when is_binary(trust_boundary) and trust_boundary != "" ->
          trust_boundary

        {_trust_boundary, [single_boundary]} ->
          single_boundary

        _trust_boundary ->
          nil
      end

    %{
      "trust_boundary_status" => if(trust_boundaries == [], do: "missing", else: "declared"),
      "trust_boundary" => singular_trust_boundary,
      "trust_boundaries" => if(trust_boundaries == [], do: nil, else: trust_boundaries),
      "feedback_trust_boundaries" => feedback_trust_boundaries
    }
  end

  defp inferred_feedback_trust_boundaries(%{} = feedback) do
    feedback = stringify_keys(feedback)

    trust_boundary =
      Map.get(feedback, "trust_boundary") || get_in(feedback, ["provenance", "trust_boundary"])

    if is_binary(trust_boundary) and trust_boundary != "" do
      feedback
      |> normalize_operational_feedback()
      |> Enum.reduce(%{}, fn {field, values}, boundaries ->
        if is_map(values) and map_size(values) > 0 do
          field_boundaries =
            values
            |> Map.keys()
            |> Map.new(fn key -> {key, [trust_boundary]} end)

          Map.put(boundaries, field, field_boundaries)
        else
          boundaries
        end
      end)
    else
      %{}
    end
  end

  defp feedback_trust_boundary_values(nil), do: []

  defp feedback_trust_boundary_values(%{} = feedback_trust_boundaries) do
    feedback_trust_boundaries
    |> stringify_keys()
    |> Enum.flat_map(fn
      {_field, %{} = key_boundaries} ->
        key_boundaries
        |> Enum.flat_map(fn {_key, trust_boundaries} -> List.wrap(trust_boundaries) end)

      {_field, trust_boundaries} ->
        List.wrap(trust_boundaries)
    end)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp feedback_trust_boundary_values(_feedback_trust_boundaries), do: []

  defp mission_state_operational_feedback(
         mission_state,
         prior_plan,
         realized_activities_feedback
       ) do
    mission_report_feedback =
      mission_state
      |> mission_state_timeline_feedback_report()
      |> Map.get("operational_feedback", %{})

    mission_planned_activity_feedback =
      mission_state_planned_activity_operational_feedback(mission_state)

    mission_proposed_contact_feedback =
      mission_state_proposed_contact_operational_feedback(mission_state)

    mission_realized_activity_feedback =
      mission_state_realized_activity_operational_feedback(mission_state, prior_plan)

    mission_operational_timeline_feedback =
      mission_state_operational_timeline_operational_feedback(mission_state)

    mission_command_window_feedback =
      mission_state_command_window_operational_feedback(mission_state)

    mission_maneuver_review_feedback =
      mission_state_maneuver_review_operational_feedback(mission_state)

    mission_cadence_import_source_feedback =
      mission_state_cadence_import_source_operational_feedback(mission_state)

    mission_cadence_import_feedback =
      mission_state_cadence_import_operational_feedback(mission_state)

    mission_operator_review_source_feedback =
      mission_state_operator_review_source_operational_feedback(mission_state)

    mission_operator_review_feedback =
      mission_state_operator_review_operational_feedback(mission_state)

    realized_activities_feedback
    |> merge_operational_feedback(mission_realized_activity_feedback)
    |> merge_operational_feedback(mission_planned_activity_feedback)
    |> merge_operational_feedback(mission_proposed_contact_feedback)
    |> merge_operational_feedback(mission_operational_timeline_feedback)
    |> merge_operational_feedback(mission_command_window_feedback)
    |> merge_operational_feedback(mission_maneuver_review_feedback)
    |> merge_operational_feedback(mission_cadence_import_source_feedback)
    |> merge_operational_feedback(mission_cadence_import_feedback)
    |> merge_operational_feedback(mission_operator_review_source_feedback)
    |> merge_operational_feedback(mission_operator_review_feedback)
    |> merge_operational_feedback(mission_report_feedback)
    |> merge_operational_feedback(mission_state_direct_operational_feedback(mission_state))
  end

  defp candidate_refresh_operational_feedback(%{} = candidate_refresh) do
    candidate_refresh
    |> Map.get("operational_feedback", %{})
    |> normalize_operational_feedback()
  end

  defp candidate_refresh_operational_feedback(_candidate_refresh),
    do: normalize_operational_feedback(%{})

  defp candidate_refresh_operational_feedback_metadata(%{} = candidate_refresh) do
    %{
      "source_report_contract" => "candidate_refresh.v1",
      "source_report_count" => 1,
      "source_refresh_id" => Map.get(candidate_refresh, "refresh_id"),
      "source_snapshot_id" => Map.get(candidate_refresh, "snapshot_id"),
      "source_candidate_count" => length(Map.get(candidate_refresh, "candidate_activities", [])),
      "source_invalidated_candidate_count" =>
        length(Map.get(candidate_refresh, "invalidated_candidates", [])),
      "source_operational_feedback_provenance" =>
        get_in(candidate_refresh, ["provenance", "operational_feedback"])
    }
    |> compact_map()
  end

  defp candidate_refresh_operational_feedback_metadata(_candidate_refresh), do: %{}

  defp realized_activities_operational_feedback(mission_state, prior_plan) do
    raw_realized_activities =
      mission_state
      |> Map.get("realized_activities", [])
      |> Enum.map(&stringify_keys/1)

    feedback_realized_activities =
      Enum.reject(raw_realized_activities, &invalid_realized_activity_feedback_input?/1)

    realized_activities =
      feedback_realized_activities
      |> enrich_realized_activities_with_planned_context(prior_plan)

    realized_contacts =
      realized_activities
      |> Enum.filter(&realized_contact_feedback?/1)

    realized_observations =
      realized_activities
      |> Enum.filter(&realized_observation_feedback?/1)

    realized_maneuvers =
      realized_activities
      |> Enum.filter(&realized_maneuver_feedback?/1)

    realized_commands =
      realized_activities
      |> Enum.filter(&realized_command_feedback?/1)

    %{
      "contact_success_rate" =>
        station_feedback_average(realized_contacts, &contact_success_value/1),
      "observation_success_rate" =>
        target_feedback_average(realized_observations, &observation_success_value/1),
      "image_quality_score" =>
        target_feedback_average(realized_observations, &image_quality_score_value/1),
      "image_quality_status" =>
        target_feedback_text(realized_observations, &image_quality_status_value/1),
      "image_quality_source" =>
        target_feedback_text(realized_observations, &image_quality_source_value/1),
      "cloud_cover_fraction" =>
        target_feedback_average(realized_observations, &cloud_cover_fraction_value/1),
      "blur_score" => target_feedback_average(realized_observations, &blur_score_value/1),
      "maneuver_success_rate" =>
        activity_feedback_average(realized_maneuvers, &maneuver_success_value/1),
      "command_success_rate" =>
        activity_feedback_average(realized_commands, &command_success_value/1),
      "station_throughput_factor" =>
        station_feedback_average(realized_contacts, &station_throughput_value/1),
      "downlink_demand_mb" =>
        merge_downlink_demand_feedback(
          observation_downlink_demand_feedback(realized_observations),
          station_downlink_demand_feedback(realized_contacts)
        ),
      "downlink_demand_sources" =>
        merge_downlink_demand_source_feedback(
          observation_downlink_demand_sources(realized_observations),
          station_downlink_demand_sources(realized_contacts)
        ),
      "target_priority_overrides" => target_priority_feedback_average(realized_observations),
      "resource_margin_overrides" =>
        realized_resource_margin_feedback(feedback_realized_activities),
      "resource_availability_overrides" =>
        realized_resource_availability_feedback(feedback_realized_activities)
    }
  end

  defp invalid_realized_activity_feedback_input?(%{} = activity) do
    activity
    |> invalid_realized_activity_feedback_identity_sections()
    |> Kernel.!=([])
  end

  defp invalid_realized_activity_feedback_input?(_activity), do: true

  defp invalid_realized_activity_feedback_sections(realized_activities) do
    realized_activities
    |> Enum.with_index(1)
    |> Enum.flat_map(fn {activity, row_index} ->
      case stringify_keys(activity) do
        %{} = activity ->
          (invalid_realized_activity_feedback_identity_sections(activity) ++
             invalid_realized_activity_feedback_unit_interval_sections(activity) ++
             invalid_realized_activity_feedback_nonnegative_number_sections(activity))
          |> Enum.map(&Map.put(&1, "row_index", row_index))

        invalid_shape ->
          [
            %{
              "field" => "realized_activities",
              "row_index" => row_index,
              "reason" => "entry_must_be_object",
              "invalid_feedback_shape" => invalid_shape
            }
          ]
      end
    end)
  end

  defp invalid_realized_activity_feedback_unit_interval_sections(activity) do
    activity
    |> realized_activity_feedback_unit_interval_values()
    |> Enum.flat_map(fn {field, value} ->
      case unit_interval_number_status(value) do
        {:ok, _value} ->
          []

        :missing ->
          []

        {:invalid_number, number} ->
          [
            %{
              "field" => "realized_activities.#{field}",
              "reason" => "value_must_be_between_0_and_1",
              "invalid_feedback_value" => number,
              "row_id" =>
                raw_feedback_identifier(activity["id"]) ||
                  raw_feedback_identifier(activity["realized_activity_id"]) ||
                  raw_feedback_identifier(activity["activity_id"])
            }
            |> compact_map()
          ]

        {:invalid_shape, shape} ->
          [
            %{
              "field" => "realized_activities.#{field}",
              "reason" => "entry_must_be_unit_interval_number",
              "invalid_feedback_shape" => stringify_keys(shape),
              "row_id" =>
                raw_feedback_identifier(activity["id"]) ||
                  raw_feedback_identifier(activity["realized_activity_id"]) ||
                  raw_feedback_identifier(activity["activity_id"])
            }
            |> compact_map()
          ]
      end
    end)
  end

  defp invalid_realized_activity_feedback_nonnegative_number_sections(activity) do
    activity
    |> realized_activity_feedback_nonnegative_number_values()
    |> Enum.flat_map(fn {field, value} ->
      case nonnegative_number_status(value) do
        {:ok, _value} ->
          []

        :missing ->
          []

        {:invalid_number, number} ->
          [
            %{
              "field" => "realized_activities.#{field}",
              "reason" => "entry_must_be_nonnegative_number",
              "invalid_feedback_shape" => number,
              "row_id" => realized_activity_feedback_row_id(activity)
            }
            |> compact_map()
          ]

        {:invalid_shape, shape} ->
          [
            %{
              "field" => "realized_activities.#{field}",
              "reason" => "entry_must_be_nonnegative_number",
              "invalid_feedback_shape" => stringify_keys(shape),
              "row_id" => realized_activity_feedback_row_id(activity)
            }
            |> compact_map()
          ]
      end
    end)
  end

  defp realized_activity_feedback_nonnegative_number_values(activity) do
    realized_feedback_weight_fields()
    |> Enum.map(fn field -> {field, Map.get(activity, field)} end)
    |> Enum.reject(fn {_field, value} -> feedback_value_missing?(value) end)
  end

  defp realized_activity_feedback_row_id(activity) do
    raw_feedback_identifier(activity["id"]) ||
      raw_feedback_identifier(activity["realized_activity_id"]) ||
      raw_feedback_identifier(activity["activity_id"])
  end

  defp realized_activity_feedback_unit_interval_values(activity) do
    [
      {"completed_fraction", activity["completed_fraction"]},
      {"image_quality_score", activity["image_quality_score"]},
      {"product_quality_score", activity["product_quality_score"]},
      {"quality_score", activity["quality_score"]},
      {"cloud_cover_fraction", activity["cloud_cover_fraction"]},
      {"cloud_fraction", activity["cloud_fraction"]},
      {"cloud_cover", activity["cloud_cover"]},
      {"blur_score", activity["blur_score"]},
      {"image_blur_score", activity["image_blur_score"]},
      {"sharpness_loss_fraction", activity["sharpness_loss_fraction"]},
      {"quality.image_quality_score", get_in(activity, ["quality", "image_quality_score"])},
      {"quality.product_quality_score", get_in(activity, ["quality", "product_quality_score"])},
      {"quality.score", get_in(activity, ["quality", "score"])},
      {"quality.cloud_cover_fraction", get_in(activity, ["quality", "cloud_cover_fraction"])},
      {"quality.cloud_fraction", get_in(activity, ["quality", "cloud_fraction"])},
      {"quality.cloud_cover", get_in(activity, ["quality", "cloud_cover"])},
      {"quality.blur_score", get_in(activity, ["quality", "blur_score"])},
      {"quality.image_blur_score", get_in(activity, ["quality", "image_blur_score"])},
      {"quality.sharpness_loss_fraction",
       get_in(activity, ["quality", "sharpness_loss_fraction"])},
      {"metadata.image_quality_score", get_in(activity, ["metadata", "image_quality_score"])},
      {"metadata.product_quality_score", get_in(activity, ["metadata", "product_quality_score"])},
      {"metadata.quality_score", get_in(activity, ["metadata", "quality_score"])},
      {"metadata.cloud_cover_fraction", get_in(activity, ["metadata", "cloud_cover_fraction"])},
      {"metadata.cloud_fraction", get_in(activity, ["metadata", "cloud_fraction"])},
      {"metadata.cloud_cover", get_in(activity, ["metadata", "cloud_cover"])},
      {"metadata.blur_score", get_in(activity, ["metadata", "blur_score"])},
      {"metadata.image_blur_score", get_in(activity, ["metadata", "image_blur_score"])},
      {"metadata.sharpness_loss_fraction",
       get_in(activity, ["metadata", "sharpness_loss_fraction"])}
    ]
    |> Enum.reject(fn {_field, value} -> feedback_value_missing?(value) end)
  end

  defp feedback_value_missing?(nil), do: true
  defp feedback_value_missing?(""), do: true
  defp feedback_value_missing?(_value), do: false

  defp invalid_realized_activity_feedback_identity_sections(activity) do
    activity
    |> realized_activity_feedback_identity_values()
    |> Enum.flat_map(fn {field, value} ->
      case raw_feedback_identifier(value) do
        nil ->
          []

        identifier ->
          if stable_id_string?(identifier) do
            []
          else
            [
              %{
                "field" => "realized_activities.#{field}",
                "key" => identifier,
                "reason" => "key_must_be_stable_id",
                "row_id" =>
                  raw_feedback_identifier(activity["id"]) ||
                    raw_feedback_identifier(activity["realized_activity_id"]) ||
                    raw_feedback_identifier(activity["activity_id"])
              }
              |> compact_map()
            ]
          end
      end
    end)
  end

  defp realized_activity_feedback_identity_values(activity) do
    [
      {"id", activity["id"]},
      {"realized_activity_id", activity["realized_activity_id"]},
      {"planned_activity_id", activity["planned_activity_id"]},
      {"activity_id", activity["activity_id"]},
      {"timeline_id", activity["timeline_id"]},
      {"metadata.timeline_id", get_in(activity, ["metadata", "timeline_id"])},
      {"scenario_id", activity["scenario_id"]},
      {"metadata.scenario_id", get_in(activity, ["metadata", "scenario_id"])},
      {"ground_station_id", activity["ground_station_id"]},
      {"station_id", activity["station_id"]},
      {"metadata.ground_station_id", get_in(activity, ["metadata", "ground_station_id"])},
      {"metadata.station_id", get_in(activity, ["metadata", "station_id"])},
      {"target_id", activity["target_id"]},
      {"metadata.target_id", get_in(activity, ["metadata", "target_id"])},
      {"spacecraft_id", activity["spacecraft_id"]},
      {"satellite_id", activity["satellite_id"]},
      {"metadata.spacecraft_id", get_in(activity, ["metadata", "spacecraft_id"])},
      {"resource_id", activity["resource_id"]},
      {"source_window_id", activity["source_window_id"]},
      {"metadata.source_window_id", get_in(activity, ["metadata", "source_window_id"])},
      {"target.id", nested_feedback_identifier(activity, "target", ["target_id", "id"])},
      {"station.id", nested_feedback_identifier(activity, "station", ["station_id", "id"])},
      {"ground_station.id",
       nested_feedback_identifier(activity, "ground_station", [
         "ground_station_id",
         "station_id",
         "id"
       ])},
      {"spacecraft.id",
       nested_feedback_identifier(activity, "spacecraft", ["spacecraft_id", "id"])},
      {"satellite.id", nested_feedback_identifier(activity, "satellite", ["satellite_id", "id"])},
      {"source_window.id",
       nested_feedback_identifier(activity, "source_window", ["source_window_id", "id"])}
    ]
  end

  defp nested_feedback_identifier(activity, object_key, identity_keys) do
    case Map.get(activity, object_key) do
      %{} = object -> Enum.find_value(identity_keys, &Map.get(object, &1))
      _value -> nil
    end
  end

  defp raw_feedback_identifier(nil), do: nil
  defp raw_feedback_identifier(value) when is_binary(value) and value != "", do: value
  defp raw_feedback_identifier(value) when is_atom(value), do: Atom.to_string(value)
  defp raw_feedback_identifier(value) when is_integer(value), do: Integer.to_string(value)
  defp raw_feedback_identifier(_value), do: nil

  defp realized_resource_margin_feedback(realized_activities) do
    realized_activities
    |> Enum.reduce(%{}, fn activity, feedback ->
      spacecraft_id = resource_feedback_spacecraft_id(activity)
      margins = realized_activity_resource_margins(activity)

      if spacecraft_id in [nil, ""] or margins == %{} do
        feedback
      else
        Map.update(feedback, spacecraft_id, margins, &merge_resource_margin_feedback(&1, margins))
      end
    end)
  end

  defp realized_activity_resource_margins(activity) do
    activity
    |> normalize_resource_margin_aliases()
    |> Map.take([
      "fuel_margin",
      "power_margin",
      "storage_margin",
      "downlink_margin",
      "thermal_margin_c",
      "battery_capacity_wh",
      "battery_energy_used_wh",
      "battery_state_of_charge"
    ])
    |> Enum.filter(fn {_field, value} -> is_number(value) end)
    |> Map.new(fn {field, value} -> {field, value * 1.0} end)
  end

  defp merge_resource_margin_feedback(existing, incoming) do
    Map.merge(existing, incoming, fn field, current, candidate ->
      merge_resource_margin_value(field, current, candidate)
    end)
  end

  defp merge_resource_margin_value("battery_energy_used_wh", current, candidate),
    do: max(current, candidate)

  defp merge_resource_margin_value(_field, current, candidate), do: min(current, candidate)

  defp realized_resource_availability_feedback(realized_activities) do
    realized_activities
    |> Enum.reduce(%{}, fn activity, feedback ->
      spacecraft_id = resource_feedback_spacecraft_id(activity)
      availability = realized_activity_resource_availability(activity)

      if spacecraft_id in [nil, ""] or availability == %{} do
        feedback
      else
        Map.update(
          feedback,
          spacecraft_id,
          availability,
          &merge_resource_availability_feedback(&1, availability)
        )
      end
    end)
  end

  defp realized_activity_resource_availability(activity) do
    activity
    |> normalize_resource_availability_aliases()
    |> Map.take([
      "payload_available",
      "antenna_available",
      "degraded",
      "spacecraft_available",
      "spacecraft_availability",
      "mode",
      "incompatible_activity_types",
      "suppressed_activity_types"
    ])
    |> Enum.reject(fn
      {_field, nil} -> true
      {_field, ""} -> true
      {_field, []} -> true
      {_field, _value} -> false
    end)
    |> Map.new()
  end

  defp merge_resource_availability_feedback(existing, incoming) do
    Map.merge(existing, incoming, fn
      field, current, candidate when field in ["payload_available", "antenna_available"] ->
        current != false and candidate != false

      field, current, candidate
      when field in ["spacecraft_available", "spacecraft_availability"] ->
        current != false and candidate != false

      "degraded", current, candidate ->
        truthy?(current) or truthy?(candidate)

      field, current, candidate
      when field in ["incompatible_activity_types", "suppressed_activity_types"] ->
        merge_string_lists(current, candidate)

      "mode", current, candidate ->
        degraded_mode_preference(current, candidate)

      _field, _current, candidate ->
        candidate
    end)
  end

  defp merge_string_lists(current, candidate) do
    [current, candidate]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp degraded_mode_preference(current, candidate) do
    Enum.find([current, candidate], &(encode_value(&1) in ["safe", "degraded", "degraded_mode"])) ||
      candidate ||
      current
  end

  defp resource_feedback_spacecraft_id(activity) do
    [
      Map.get(activity, "spacecraft_id"),
      Map.get(activity, "scenario_id"),
      Map.get(activity, "resource_id"),
      get_in(activity, ["metadata", "spacecraft_id"]),
      get_in(activity, ["provenance", "spacecraft_id"])
    ]
    |> Enum.map(&encode_value/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

  defp enrich_realized_activities_with_planned_context(realized_activities, prior_plan) do
    planned_by_feedback_key =
      prior_plan
      |> prior_activity_context_rows()
      |> Enum.flat_map(fn planned ->
        planned
        |> planned_feedback_context_keys()
        |> Enum.map(&{&1, planned})
      end)
      |> Enum.group_by(fn {key, _planned} -> key end, fn {_key, planned} -> planned end)
      |> Map.delete(nil)
      |> Map.delete("")

    Enum.map(realized_activities, fn realized ->
      planned = realized_feedback_context(realized, planned_by_feedback_key)

      planned
      |> Map.merge(realized)
      |> put_planned_feedback_activity_id(planned)
      |> put_realized_target_priority(realized)
    end)
  end

  defp put_realized_target_priority(activity, realized) do
    case declared_realized_target_priority(realized) do
      value when is_number(value) -> Map.put(activity, "__realized_target_priority", value)
      _value -> activity
    end
  end

  defp declared_realized_target_priority(activity) do
    [
      Map.get(activity, "realized_target_priority"),
      Map.get(activity, "target_priority"),
      get_in(activity, ["metadata", "target_priority"])
    ]
    |> Enum.find_value(&numeric_or_nil/1)
  end

  defp unique_prior_activity_context([planned]), do: planned
  defp unique_prior_activity_context(_matches), do: %{}

  defp realized_feedback_context(realized, planned_by_feedback_key) do
    realized
    |> realized_feedback_context_keys()
    |> Enum.find_value(%{}, fn key ->
      planned =
        planned_by_feedback_key
        |> Map.get(key, [])
        |> unique_prior_activity_context()

      if planned == %{}, do: nil, else: planned
    end)
  end

  defp put_planned_feedback_activity_id(activity, planned) when planned == %{}, do: activity

  defp put_planned_feedback_activity_id(activity, planned) do
    case planned_feedback_activity_id(planned) do
      nil -> activity
      id -> Map.put(activity, "__planned_feedback_activity_id", id)
    end
  end

  defp prior_activity_context_rows(prior_plan) do
    [
      prior_plan_activities(prior_plan),
      prior_plan_candidate_activities(prior_plan),
      prior_plan_proposed_contacts(prior_plan)
    ]
    |> List.flatten()
    |> Enum.map(&stringify_keys/1)
  end

  defp planned_feedback_context_keys(activity) do
    [
      Map.get(activity, "id"),
      Map.get(activity, "activity_id"),
      Map.get(activity, "planned_activity_id"),
      explicit_timeline_id(activity)
    ]
    |> feedback_identity_keys()
  end

  defp realized_feedback_context_keys(activity) do
    [
      Map.get(activity, "planned_activity_id"),
      Map.get(activity, "activity_id"),
      Map.get(activity, "id"),
      Map.get(activity, "realized_activity_id"),
      explicit_timeline_id(activity)
    ]
    |> feedback_identity_keys()
  end

  defp realized_feedback_activity_id(activity) do
    Map.get(activity, "__planned_feedback_activity_id") ||
      activity
      |> realized_feedback_context_keys()
      |> List.first()
  end

  defp planned_feedback_activity_id(activity) do
    activity
    |> planned_feedback_context_keys()
    |> List.first()
  end

  defp explicit_timeline_id(activity) do
    Map.get(activity, "timeline_id") || get_in(activity, ["metadata", "timeline_id"])
  end

  defp feedback_identity_keys(values) do
    values
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp realized_contact_feedback?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")

    (type in ["downlink", "contact", "planned_contact"] or downlink_activity?(activity) or
       Map.has_key?(activity, "ground_station_id") or Map.has_key?(activity, "station_id")) and
      (not is_nil(contact_success_value(activity)) or
         not is_nil(station_throughput_value(activity)))
  end

  defp realized_observation_feedback?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")

    type == "observe" and
      (Map.get(activity, "target_id") || Map.get(activity, "id")) not in [nil, ""] and
      (not is_nil(observation_success_value(activity)) or
         not is_nil(image_quality_score_value(activity)) or
         not is_nil(image_quality_status_value(activity)) or
         not is_nil(image_quality_source_value(activity)) or
         not is_nil(cloud_cover_fraction_value(activity)) or
         not is_nil(blur_score_value(activity)) or
         not is_nil(observation_downlink_demand_mb(activity)) or
         not is_nil(target_priority_override_value(activity)))
  end

  defp realized_maneuver_feedback?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")

    (type in ["maneuver", "impulsive_burn"] or Map.has_key?(activity, "maneuver_success") or
       Map.has_key?(activity, "maneuver_result")) and
      realized_feedback_activity_id(activity) not in [nil, ""] and
      not is_nil(maneuver_success_value(activity))
  end

  defp realized_command_feedback?(activity) do
    command_activity?(activity) and
      realized_feedback_activity_id(activity) not in [nil, ""] and
      not is_nil(command_success_value(activity))
  end

  defp station_feedback_average(activities, value_fun) do
    activities
    |> Enum.group_by(&(Map.get(&1, "ground_station_id") || Map.get(&1, "station_id")))
    |> Enum.reject(fn {station_id, _activities} -> station_id in [nil, ""] end)
    |> Map.new(fn {station_id, station_activities} ->
      values =
        station_activities
        |> Enum.map(&weighted_feedback_value(&1, value_fun))
        |> Enum.reject(&is_nil/1)

      {station_id, average_feedback_value(values)}
    end)
    |> Enum.reject(fn {_station_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp target_feedback_average(activities, value_fun) do
    activities
    |> Enum.group_by(&Map.get(&1, "target_id"))
    |> Enum.reject(fn {target_id, _activities} -> target_id in [nil, ""] end)
    |> Map.new(fn {target_id, target_activities} ->
      values =
        target_activities
        |> Enum.map(&weighted_feedback_value(&1, value_fun))
        |> Enum.reject(&is_nil/1)

      {target_id, average_feedback_value(values)}
    end)
    |> Enum.reject(fn {_target_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp target_feedback_text(activities, value_fun) do
    activities
    |> Enum.group_by(&Map.get(&1, "target_id"))
    |> Enum.reject(fn {target_id, _activities} -> target_id in [nil, ""] end)
    |> Map.new(fn {target_id, target_activities} ->
      value =
        target_activities
        |> Enum.map(value_fun)
        |> Enum.map(&encode_value/1)
        |> Enum.reject(&(&1 in [nil, ""]))
        |> Enum.uniq()
        |> Enum.sort()
        |> List.first()

      {target_id, value}
    end)
    |> Enum.reject(fn {_target_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp target_priority_feedback_average(activities) do
    activities
    |> Enum.group_by(&Map.get(&1, "target_id"))
    |> Enum.reject(fn {target_id, _activities} -> target_id in [nil, ""] end)
    |> Map.new(fn {target_id, target_activities} ->
      values =
        target_activities
        |> Enum.map(fn activity ->
          weighted_feedback_value(activity, &target_priority_override_value/1)
        end)
        |> Enum.reject(&is_nil/1)

      {target_id, average_nonnegative_value(values)}
    end)
    |> Enum.reject(fn {_target_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp activity_feedback_average(activities, value_fun) do
    activities
    |> Enum.group_by(&realized_feedback_activity_id/1)
    |> Enum.reject(fn {activity_id, _activities} -> activity_id in [nil, ""] end)
    |> Map.new(fn {activity_id, activity_rows} ->
      values =
        activity_rows
        |> Enum.map(&weighted_feedback_value(&1, value_fun))
        |> Enum.reject(&is_nil/1)

      {activity_id, average_feedback_value(values)}
    end)
    |> Enum.reject(fn {_activity_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp average_feedback_value([]), do: nil

  defp average_feedback_value(weighted_values) do
    weighted_values
    |> weighted_average()
    |> clamp_unit_interval()
  end

  defp average_nonnegative_value([]), do: nil

  defp average_nonnegative_value(weighted_values) do
    weighted_values
    |> weighted_average()
    |> max(0.0)
  end

  defp weighted_feedback_value(activity, value_fun) do
    case {value_fun.(activity), usable_feedback_weight(activity)} do
      {value, weight} when is_number(value) and is_number(weight) and weight > 0.0 ->
        {value, weight}

      _value ->
        nil
    end
  end

  defp weighted_average(weighted_values) do
    {weighted_sum, total_weight} =
      Enum.reduce(weighted_values, {0.0, 0.0}, fn {value, weight}, {sum, total} ->
        {sum + value * weight, total + weight}
      end)

    weighted_sum / total_weight
  end

  defp feedback_weight(activity) do
    case declared_feedback_weight(activity) do
      {:ok, weight} -> weight
      :missing -> 1.0
    end
  end

