  defp repair_candidate_diff_report(nil), do: nil

  defp repair_candidate_diff_report(%{} = candidate_refresh) do
    case Map.get(candidate_refresh, "candidate_diff_report") do
      %{} = report -> stringify_keys(report)
      _report -> nil
    end
  end

  defp repair_candidate_diff_replacements(nil), do: %{}

  defp repair_candidate_diff_replacements(%{} = candidate_refresh) do
    candidate_refresh
    |> repair_candidate_diff_report()
    |> case do
      %{} = report ->
        candidate_diff_replacements_by_invalidated_id(report)

      _report ->
        %{}
    end
  end

  defp repair_candidate_rejection_report(%{} = request) do
    request
    |> repair_candidate_rejection_reports()
    |> List.first()
  end

  defp repair_candidate_rejection_reports(%{} = request) do
    mission_state_reports =
      request.mission_state
      |> CandidateReviewSourceReports.candidate_rejection_reports(
        source_report_family_callbacks()
      )
      |> Enum.map(fn {report, _source_path} -> report end)

    mission_state_reports ++ repair_candidate_refresh_rejection_reports(request.candidate_refresh)
  end

  defp repair_candidate_refresh_rejection_reports(nil), do: []

  defp repair_candidate_refresh_rejection_reports(%{} = candidate_refresh) do
    ["source_candidate_rejection_report", "candidate_rejection_report"]
    |> Enum.flat_map(fn field ->
      candidate_refresh
      |> Map.get(field)
      |> List.wrap()
    end)
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
  end

  defp repair_rejected_candidate_ids(%{} = request) do
    request
    |> repair_candidate_rejection_reports()
    |> candidate_rejection_rejected_candidate_ids()
    |> MapSet.new()
  end

  defp candidate_rejection_rejected_candidate_ids(reports) do
    reports
    |> List.wrap()
    |> Enum.flat_map(fn report ->
      report
      |> stringify_keys()
      |> Map.get("rows", [])
      |> List.wrap()
    end)
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&(Map.get(&1, "rejection_status", "rejected") == "rejected"))
    |> Enum.map(&candidate_rejection_candidate_id/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp candidate_diff_replacements_by_invalidated_id(%{} = report) do
    report
    |> candidate_diff_replacement_rows()
    |> group_candidate_diff_replacement_rows(&Map.get(&1, "id"))
  end

  defp candidate_diff_replacements_by_replacement_id(nil), do: %{}

  defp candidate_diff_replacements_by_replacement_id(%{} = report) do
    report
    |> candidate_diff_replacement_rows()
    |> group_candidate_diff_replacement_rows(&Map.get(&1, "replacement_candidate_id"))
  end

  defp candidate_diff_replacement_rows(report) do
    CandidateReviewSourceReports.candidate_diff_replacement_rows(report)
  end

  defp group_candidate_diff_replacement_rows(rows, key_fun) do
    rows
    |> Enum.group_by(key_fun)
    |> Enum.reject(fn {key, _rows} -> is_nil(key) end)
    |> Map.new()
  end

  defp candidate_diff_replacement_map_rows(replacements_by_key) do
    replacements_by_key
    |> Map.values()
    |> Enum.flat_map(fn
      rows when is_list(rows) -> rows
      row -> [row]
    end)
  end

  defp candidate_diff_match(nil, _scope), do: nil
  defp candidate_diff_match([], _scope), do: nil
  defp candidate_diff_match(%{} = row, _scope), do: row
  defp candidate_diff_match([row], _scope), do: row

  defp candidate_diff_match(rows, scope) when is_list(rows) do
    replacement_ids =
      rows
      |> Enum.map(&Map.get(&1, "replacement_candidate_id"))
      |> Enum.reject(&is_nil/1)
      |> Enum.uniq()

    budget_dropped_candidate_ids =
      rows
      |> Enum.flat_map(&(Map.get(&1, "budget_dropped_candidate_ids") || []))
      |> Enum.uniq()
      |> Enum.sort()

    %{
      "replacement_candidate_id" => single_value(replacement_ids),
      "invalidated_reason" => "ambiguous_candidate_diff_match",
      "candidate_diff_match_status" => "ambiguous_#{scope}_candidate_diff",
      "candidate_diff_match_count" => length(rows),
      "invalidated_candidate_ids" =>
        Enum.map(rows, &(Map.get(&1, "invalidated_candidate_id") || Map.get(&1, "id"))),
      "candidate_budget_match_status" =>
        single_value(
          rows
          |> Enum.map(&Map.get(&1, "candidate_budget_match_status"))
          |> Enum.reject(&is_nil/1)
          |> Enum.uniq()
        ),
      "candidate_budget_match_count" =>
        case budget_dropped_candidate_ids do
          [] -> nil
          ids -> length(ids)
        end,
      "budget_dropped_candidate_ids" => budget_dropped_candidate_ids,
      "semantic_change_reasons" =>
        rows
        |> Enum.flat_map(&Map.get(&1, "semantic_change_reasons", []))
        |> Enum.uniq()
        |> Enum.sort()
    }
    |> compact_map()
  end

  defp single_value([value]), do: value
  defp single_value(_values), do: nil

  defp repair_freshness_report(nil), do: nil

  defp repair_freshness_report(%{} = candidate_refresh) do
    case Map.get(candidate_refresh, "freshness_report") do
      %{} = report -> stringify_keys(report)
      _report -> nil
    end
  end

  defp repair_operational_readiness_report(candidate_refresh) do
    repair_source_report(
      candidate_refresh,
      "source_operational_readiness_report",
      "operational_readiness_report"
    )
  end

  defp repair_quality_gate_report(candidate_refresh) do
    repair_source_report(candidate_refresh, "source_quality_gate_report", "quality_gate_report")
  end

  defp repair_source_report(nil, _source_key, _canonical_key), do: nil

  defp repair_source_report(%{} = candidate_refresh, source_key, canonical_key) do
    candidate_refresh = stringify_keys(candidate_refresh)

    [
      Map.get(candidate_refresh, source_key),
      Map.get(candidate_refresh, canonical_key)
    ]
    |> Enum.find(&is_map/1)
    |> case do
      %{} = report -> stringify_keys(report)
      _report -> nil
    end
  end

  defp repair_refresh_budget_report(nil), do: nil

  defp repair_refresh_budget_report(%{} = candidate_refresh) do
    case Map.get(candidate_refresh, "refresh_budget_report") do
      %{} = report -> stringify_keys(report)
      _report -> nil
    end
  end

  defp maybe_put_source_report(artifact, _key, nil), do: artifact

  defp maybe_put_source_report(artifact, key, %{} = report) do
    Map.put(artifact, key, report)
  end

  defp repair_refresh_warnings(nil), do: []

  defp repair_refresh_warnings(%{} = candidate_refresh) do
    freshness_warnings =
      candidate_refresh
      |> repair_freshness_report()
      |> case do
        %{"status" => "stale"} ->
          [
            "candidate refresh freshness policy marked the snapshot, horizon, or state quality stale"
          ]

        %{"status" => "unknown"} ->
          ["candidate refresh freshness could not be fully evaluated"]

        _report ->
          []
      end

    source_warnings =
      candidate_refresh
      |> Map.get("warnings", [])
      |> List.wrap()
      |> Enum.filter(&is_binary/1)

    (freshness_warnings ++ source_warnings)
    |> Enum.uniq()
  end

  defp repair_candidate_source(prior_plan, candidate_refresh, candidate_refresh_request)

  defp repair_candidate_source(prior_plan, nil, _candidate_refresh_request) do
    %{
      "type" => "prior_plan",
      "source_plan_id" => source_plan_id(prior_plan),
      "candidate_count" => length(prior_plan_candidate_activities(prior_plan))
    }
  end

  defp repair_candidate_source(_prior_plan, %{} = candidate_refresh, candidate_refresh_request) do
    source =
      %{
        "type" => "candidate_refresh.v1",
        "refresh_id" => Map.get(candidate_refresh, "refresh_id"),
        "snapshot_id" => Map.get(candidate_refresh, "snapshot_id"),
        "generated_at" => Map.get(candidate_refresh, "generated_at"),
        "candidate_count" => length(Map.get(candidate_refresh, "candidate_activities", [])),
        "maneuver_execution_delta_count" =>
          get_in(candidate_refresh, [
            "accepted_planning_state",
            "maneuver_execution_delta_count"
          ]) || 0,
        "invalidated_candidate_count" =>
          length(Map.get(candidate_refresh, "invalidated_candidates", []))
      }
      |> maybe_put_candidate_source_operational_feedback(candidate_refresh)
      |> StrategyCandidateSource.report_provenance_inputs(candidate_refresh)
      |> StrategyCandidateSource.report_inputs(candidate_refresh_request)

    if candidate_refresh_request do
      Map.put(source, "scope", "repair_generated")
    else
      source
    end
  end

  defp maybe_put_candidate_source_operational_feedback(source, candidate_refresh) do
    feedback_provenance = get_in(candidate_refresh, ["provenance", "operational_feedback"])
    input_keys = Map.get(feedback_provenance || %{}, "input_keys", [])
    feedback = candidate_refresh_operational_feedback(candidate_refresh)

    if input_keys == [] and operational_feedback_data_keys(feedback) == [] do
      source
    else
      source
      |> Map.put("operational_feedback_input_keys", operational_feedback_data_keys(feedback))
      |> put_if_present(
        "operational_feedback_trust_boundary_status",
        Map.get(feedback_provenance || %{}, "trust_boundary_status")
      )
      |> put_if_present(
        "operational_feedback_trust_boundary",
        Map.get(feedback_provenance || %{}, "trust_boundary")
      )
      |> put_if_present(
        "source_operational_feedback_provenance",
        feedback_provenance
      )
    end
  end

  defp repair_assumptions(prior_plan, request) do
    %{
      "source_plan_assumptions" => Map.get(prior_plan, "assumptions", %{}),
      "repair_model" =>
        if(request.candidate_refresh,
          do: "candidate_refresh_windows_greedy_repair",
          else: "prior_candidate_windows_greedy_repair"
        ),
      "candidate_source" => request.candidate_source,
      "remaining_horizon" => request.remaining_horizon,
      "constraints" => request.constraints,
      "scoring_policy" => request.scoring_policy,
      "policy_model" => "policy_decision_v1_artifact_only_no_execution",
      "degraded_mode_model" =>
        "suppress_incompatible_payload_activities_preserve_command_health_locked_approved"
    }
  end

  defp repair_provenance(prior_plan, candidate_source) do
    %{
      "source_plan_id" => source_plan_id(prior_plan),
      "source_plan_generated_at" => Map.get(prior_plan, "generated_at"),
      "source_study_id" => Map.get(prior_plan, "study_id"),
      "source_provenance" => Map.get(prior_plan, "provenance", %{}),
      "candidate_source" => candidate_source
    }
  end

  defp repair_id(prior_plan, realized_state, current_epoch_s, candidate_source) do
    :crypto.hash(
      :sha256,
      :erlang.term_to_binary({
        source_plan_id(prior_plan),
        realized_state_identity_input(realized_state),
        current_epoch_s,
        candidate_source
      })
    )
    |> Base.encode16(case: :lower)
  end

  defp realized_state_identity_input(realized_state) when is_map(realized_state) do
    Map.delete(realized_state, "model_limits")
  end

  defp realized_state_identity_input(realized_state), do: realized_state

  defp source_plan_id(prior_plan) do
    Map.get(prior_plan, "plan_id") ||
      [Map.get(prior_plan, "study_id"), Map.get(prior_plan, "generated_at")]
      |> Enum.reject(&is_nil/1)
      |> Enum.join(":")
  end

  defp plan_id(study_id, generated_at) do
    "campaign_plan:" <> encode_value(study_id) <> ":" <> DateTime.to_iso8601(generated_at)
  end

  defp repair_policy_to_map(%RepairPolicy{} = policy) do
    %{
      "preserve_approved" => policy.preserve_approved?,
      "preserve_executed" => policy.preserve_executed?,
      "allow_locked_changes" => policy.allow_locked_changes?,
      "schedule_churn_cost_weight" => policy.schedule_churn_cost_weight,
      "schedule_move_cost_weight" => policy.schedule_move_cost_weight,
      "degraded_payload_activity_types" => policy.degraded_payload_activity_types,
      "command_health_activity_types" => policy.command_health_activity_types
    }
  end

  defp normalize_repair_policy(%RepairPolicy{} = policy), do: policy

  defp normalize_repair_policy(policy) do
    policy = stringify_keys(policy || %{})

    %RepairPolicy{
      preserve_approved?: boolean_policy_value(policy, "preserve_approved", true),
      preserve_executed?: boolean_policy_value(policy, "preserve_executed", true),
      allow_locked_changes?: boolean_policy_value(policy, "allow_locked_changes", false),
      schedule_churn_cost_weight:
        numeric_policy_value(policy, "schedule_churn_cost_weight", 100.0),
      schedule_move_cost_weight: numeric_policy_value(policy, "schedule_move_cost_weight", 0.01),
      degraded_payload_activity_types:
        Map.get(policy, "degraded_payload_activity_types", ["observe"]),
      command_health_activity_types:
        Map.get(policy, "command_health_activity_types", ["command", "health_check"])
    }
  end

  defp normalize_realized_state(realized_state) when is_list(realized_state) do
    normalize_realized_state(%{"activities" => realized_state})
  end

  defp normalize_realized_state(realized_state) do
    realized_state = stringify_keys(realized_state || %{})

    activities =
      (Map.get(realized_state, "activities") || Map.get(realized_state, "realized_activities") ||
         [])
      |> Enum.map(&normalize_realized_activity/1)
      |> Enum.sort_by(& &1["id"])

    {spacecraft_states, dropped_spacecraft_state_counts} =
      (Map.get(realized_state, "spacecraft_states") || Map.get(realized_state, "spacecraft") || [])
      |> normalize_realized_spacecraft_states()

    metadata =
      realized_state
      |> Map.get("metadata", %{})
      |> put_dropped_spacecraft_state_counts(dropped_spacecraft_state_counts)

    model_limits =
      realized_state
      |> Map.get("model_limits", @realized_state_snapshot_model_limits)
      |> normalize_string_list(@realized_state_snapshot_model_limits)

    %{
      "schema_contract" => "realized_state_snapshot.v1",
      "activities" => activities,
      "spacecraft_states" => spacecraft_states,
      "metadata" => metadata,
      "model_limits" => model_limits
    }
  end

  defp normalize_realized_spacecraft_states(states) do
    states
    |> Enum.reduce({[], %{identityless: 0, invalid_identity: 0}}, fn state,
                                                                     {normalized, dropped_counts} ->
      case normalize_realized_spacecraft_state(state) do
        {:ok, normalized_state} ->
          {[normalized_state | normalized], dropped_counts}

        {:drop, reason} ->
          {normalized, Map.update!(dropped_counts, reason, &(&1 + 1))}
      end
    end)
    |> then(fn {normalized, dropped_counts} ->
      normalized =
        normalized
        |> Enum.reverse()
        |> Enum.sort_by(& &1["scenario_id"])

      {normalized, dropped_counts}
    end)
  end

  defp normalize_realized_spacecraft_state(state) do
    state = stringify_keys(state || %{})
    state = normalize_spacecraft_state_booleans(state)

    cond do
      stable_id_string?(Map.get(state, "scenario_id")) ->
        {:ok, state}

      stable_id_string?(Map.get(state, "id")) ->
        {:ok,
         state
         |> Map.put("scenario_id", Map.get(state, "id"))
         |> Map.delete("id")}

      non_empty_string?(Map.get(state, "scenario_id")) or non_empty_string?(Map.get(state, "id")) ->
        {:drop, :invalid_identity}

      true ->
        {:drop, :identityless}
    end
  end

  defp normalize_spacecraft_state_booleans(state) do
    Enum.reduce(
      [
        "degraded",
        "spacecraft_available",
        "spacecraft_availability",
        "payload_available",
        "antenna_available"
      ],
      state,
      fn key, acc ->
        case Map.fetch(acc, key) do
          {:ok, value} -> Map.put(acc, key, spacecraft_state_boolean_value(key, value))
          :error -> acc
        end
      end
    )
  end

  defp spacecraft_state_boolean_value("degraded", value) do
    case json_boolean_value(value) do
      value when is_boolean(value) -> value
      _value -> value
    end
  end

  defp spacecraft_state_boolean_value(_availability_field, value) do
    case resource_availability_boolean_value(value) do
      value when is_boolean(value) -> value
      _value -> value
    end
  end

  defp put_dropped_spacecraft_state_counts(metadata, %{identityless: 0, invalid_identity: 0}),
    do: metadata

  defp put_dropped_spacecraft_state_counts(metadata, counts) do
    metadata = stringify_keys(metadata)

    metadata
    |> maybe_put_positive_count(
      "dropped_identityless_spacecraft_state_count",
      Map.fetch!(counts, :identityless)
    )
    |> maybe_put_positive_count(
      "dropped_invalid_spacecraft_state_count",
      Map.fetch!(counts, :invalid_identity)
    )
  end

  defp maybe_put_positive_count(metadata, _field, 0), do: metadata

  defp maybe_put_positive_count(metadata, field, count) do
    Map.put(metadata, field, count)
  end

  defp normalize_string_list(values, default) when is_list(values) do
    values
    |> Enum.filter(&is_binary/1)
    |> case do
      [] -> default
      strings -> strings
    end
  end

  defp normalize_string_list(_values, default), do: default

  defp normalize_realized_activity(%RealizedActivity{} = activity) do
    activity
    |> Map.from_struct()
    |> normalize_realized_activity()
  end

  defp normalize_realized_activity(activity) do
    activity = stringify_keys(activity)

    raw_status =
      activity
      |> Map.get("status")
      |> encode_value()
      |> normalize_realized_status_value()

    raw_realized_status =
      activity
      |> Map.get("realized_status")
      |> encode_value()
      |> normalize_realized_status_value()

    {status, feedback_status, realized_status} =
      normalize_realized_activity_status(raw_status, raw_realized_status)

    unless status in @realized_statuses do
      raise ArgumentError, "unsupported realized activity status #{inspect(status)}"
    end

    %{
      "schema_contract" => "realized_activity.v1",
      "id" => encode_value(Map.fetch!(activity, "id")),
      "status" => status,
      "actual_starts_at_s" =>
        Map.get(activity, "actual_starts_at_s") || Map.get(activity, "actual_start_s"),
      "actual_ends_at_s" =>
        Map.get(activity, "actual_ends_at_s") || Map.get(activity, "actual_end_s"),
      "completed_fraction" => Map.get(activity, "completed_fraction"),
      "reason" => Map.get(activity, "reason"),
      "feedback_status" => feedback_status,
      "realized_status" => realized_status,
      "metadata" => Map.get(activity, "metadata", %{})
    }
    |> Map.merge(realized_activity_passthrough_context(activity))
    |> Enum.reject(fn {_key, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp realized_activity_passthrough_context(activity) do
    activity
    |> Map.take([
      "type",
      "direction",
      "ground_station_id",
      "station_availability",
      "station_contention_status",
      "station_calendar_entry_id",
      "station_calendar_directions",
      "station_calendar_status",
      "station_calendar_overlap_count",
      "station_calendar_overlap_entry_ids",
      "station_calendar_overlap_availabilities",
      "station_calendar_trust_boundary_status",
      "station_reservation_id",
      "station_reserved_by",
      "station_reservation_status",
      "station_reservation_match_status",
      "trust_boundary",
      "provenance",
      "source_station_calendar_entry",
      "source_station_calendar_overlaps"
    ])
    |> compact_map()
  end

  defp normalize_realized_activity_status(status, realized_status)
       when status in @realized_feedback_match_statuses and realized_status in @realized_statuses do
    {realized_status, status, realized_status}
  end

  defp normalize_realized_activity_status(status, _realized_status) do
    {status, nil, nil}
  end

  defp realized_activities_by_id(realized_state) do
    realized_state
    |> Map.get("activities", [])
    |> Enum.group_by(fn activity -> activity["id"] end)
  end

  defp realized_activity_match(realized_by_id, activity_id) do
    case Map.get(realized_by_id, activity_id, []) do
      [] -> {:ok, nil}
      [realized] -> {:ok, realized}
      realized_rows -> {:ambiguous, realized_rows}
    end
  end

  defp realized_feedback_statuses(realized_rows) do
    realized_rows
    |> Enum.map(&Map.get(&1, "status"))
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp selected_activity_ids(planned_activities) do
    planned_activities
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&activity_id/1)
    |> MapSet.new()
  end

  defp degraded_modes_by_scenario(realized_state, repair_policy) do
    realized_state
    |> Map.get("spacecraft_states", [])
    |> Enum.filter(fn state ->
      Map.get(state, "mode") in ["degraded", "degraded_mode"] or
        truthy?(Map.get(state, "degraded"))
    end)
    |> Map.new(fn state ->
      scenario_id = Map.get(state, "scenario_id") || Map.get(state, "id")

      incompatible_types =
        (Map.get(state, "incompatible_activity_types") ||
           Map.get(state, "suppressed_activity_types") ||
           repair_policy.degraded_payload_activity_types)
        |> normalize_incompatible_activity_types()

      {scenario_id, incompatible_types}
    end)
  end

  defp realized_status(activity, nil, current_epoch_s) do
    if activity_end(activity) <= current_epoch_s, do: "unreported_past", else: "planned"
  end

  defp realized_status(_activity, realized, _current_epoch_s),
    do: normalize_realized_status_value(realized["status"])

  defp normalize_realized_feedback_status(%{} = activity) do
    activity = stringify_keys(activity)

    status =
      activity
      |> Map.get("status")
      |> encode_value()
      |> normalize_realized_status_value()

    raw_realized_status =
      activity
      |> Map.get("realized_status")
      |> encode_value()
      |> normalize_realized_status_value()

    {status, feedback_status, realized_status} =
      normalize_realized_activity_status(status, raw_realized_status)

    activity
    |> put_if_present("status", status)
    |> put_if_present("feedback_status", feedback_status)
    |> put_if_present("realized_status", realized_status || raw_realized_status)
  end

  defp normalize_realized_feedback_status(activity), do: activity

  defp normalize_realized_status_value(status) when is_binary(status) do
    status
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp normalize_realized_status_value(status) when is_atom(status) do
    status
    |> Atom.to_string()
    |> normalize_realized_status_value()
  end

  defp normalize_realized_status_value(status), do: status

  defp degraded_incompatible?(activity, degraded_modes, repair_policy) do
    incompatible_types = Map.get(degraded_modes, activity["scenario_id"], [])

    exempt_activity_types =
      repair_policy.command_health_activity_types || @command_health_activity_types

    activity["type"] in incompatible_types and
      activity["type"] not in exempt_activity_types
  end

  defp locked_or_approved?(activity) do
    metadata = Map.get(activity, "metadata", %{})

    truthy?(Map.get(activity, "locked")) or truthy?(Map.get(activity, "approved")) or
      truthy?(Map.get(metadata, "locked")) or truthy?(Map.get(metadata, "approved")) or
      Map.get(activity, "approval_status") in ["approved", "locked"] or
      Map.get(metadata, "approval_status") in ["approved", "locked"]
  end

  defp maneuver_activity?(activity), do: activity["type"] in ["maneuver", "impulsive_burn"]

  defp within_remaining_horizon?(activity, %{
         "starts_at_s" => starts_at_s,
         "ends_at_s" => ends_at_s
       }) do
    activity_end(activity) > starts_at_s and activity_start(activity) < ends_at_s
  end

  defp remaining_horizon(prior_plan, nil, current_epoch_s) do
    duration_s = planning_horizon_duration_s(prior_plan, current_epoch_s)

    %{
      "starts_at_s" => current_epoch_s,
      "ends_at_s" => duration_s
    }
  end

  defp remaining_horizon(_prior_plan, horizon, _current_epoch_s) do
    horizon = stringify_keys(horizon)

    %{
      "starts_at_s" =>
        numeric!(Map.fetch!(horizon, "starts_at_s"), "remaining_horizon.starts_at_s"),
      "ends_at_s" => numeric!(Map.fetch!(horizon, "ends_at_s"), "remaining_horizon.ends_at_s")
    }
  end

  defp planning_horizon_duration_s(prior_plan, default) do
    prior_plan
    |> get_in(["planning_horizon", "duration_s"])
    |> numeric_or_nil()
    |> case do
      value when is_number(value) -> value
      _value -> default
    end
  end

  defp shift_activity(activity, delay_s) do
    activity
    |> maybe_shift("starts_at_s", delay_s)
    |> maybe_shift("ends_at_s", delay_s)
  end

  defp maybe_shift(activity, key, delay_s) do
    case Map.fetch(activity, key) do
      {:ok, value} -> Map.put(activity, key, value + delay_s)
      :error -> activity
    end
  end

  defp put_repair_metadata(activity, metadata) do
    Map.update(activity, "repair", metadata, &Map.merge(&1, metadata))
  end

  defp same_scenario?(left, right), do: left["scenario_id"] == right["scenario_id"]

  defp activity_id(activity), do: encode_value(Map.fetch!(activity, "id"))

  defp activity_start(activity) do
    activity_raw_start(activity) || 0.0
  end

  defp activity_end(activity) do
    activity_raw_end(activity) || activity_start(activity)
  end

  defp activity_raw_start(activity) do
    numeric_or_nil(Map.get(activity, "starts_at_s")) ||
      numeric_or_nil(Map.get(activity, "start_s")) ||
      numeric_or_nil(Map.get(activity, "epoch_s"))
  end

  defp activity_raw_end(activity) do
    numeric_or_nil(Map.get(activity, "ends_at_s")) ||
      numeric_or_nil(Map.get(activity, "end_s")) ||
      numeric_or_nil(Map.get(activity, "epoch_s"))
  end

  defp truthy?(value), do: json_boolean_value(value) == true

  defp numeric!(value, _field) when is_integer(value) or is_float(value), do: value

  defp numeric!(value, field) when is_binary(value) do
    case Float.parse(value) do
      {number, ""} -> number
      _error -> raise ArgumentError, "#{field} must be numeric"
    end
  end

  defp numeric!(_value, field), do: raise(ArgumentError, "#{field} must be numeric")

  defp numeric_or_nil(nil), do: nil
  defp numeric_or_nil(value) when is_integer(value) or is_float(value), do: value

  defp numeric_or_nil(value) when is_binary(value) do
    case Float.parse(value) do
      {number, ""} -> number
      _error -> nil
    end
  end

  defp numeric_or_nil(_value), do: nil

  defp numeric_or_zero(value) when is_integer(value) or is_float(value), do: value * 1.0
  defp numeric_or_zero(_value), do: 0.0

  defp get_key(nil, _key), do: nil

  defp get_key(%{} = map, key) when is_atom(key),
    do: fetch_key_or_alias(map, key, Atom.to_string(key))

  defp get_key(%{} = map, key), do: fetch_key_or_alias(map, key, String.to_atom(key))

  defp fetch_key_or_alias(map, key, alias_key) do
    case Map.fetch(map, key) do
      {:ok, nil} -> Map.get(map, alias_key)
      {:ok, value} -> value
      :error -> Map.get(map, alias_key)
    end
  end

  defp stringify_keys(%_struct{} = struct), do: struct |> Map.from_struct() |> stringify_keys()

  defp stringify_keys(%{} = map) do
    Map.new(map, fn {key, value} -> {encode_value(key), stringify_keys(value)} end)
  end

  defp stringify_keys(values) when is_list(values), do: Enum.map(values, &stringify_keys/1)
  defp stringify_keys(value), do: encode_value(value)

  defp compact_map(map) do
    map
    |> Enum.reject(fn {_key, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp reject_empty_values(map) do
    map
    |> Enum.reject(fn {_key, value} -> value in [nil, "", []] end)
    |> Map.new()
  end

  defp campaign_targets(campaign), do: Map.get(campaign, "targets", [])

  defp overlaps?(left, right) do
    left["starts_at_s"] < right["ends_at_s"] and right["starts_at_s"] < left["ends_at_s"]
  end

  defp overlap_duration(interval, intervals) do
    intervals
    |> Enum.map(fn other -> interval_overlap_duration(interval, other) end)
    |> Enum.sum()
  end

  defp interval_overlap_duration({left_start, left_end}, {right_start, right_end}) do
    max(0.0, min(left_end, right_end) - max(left_start, right_start))
  end

  defp score(score_terms) do
    score_terms
    |> Map.values()
    |> Enum.sum()
  end

  defp event_timing_metadata(metadata) do
    metadata
    |> Map.take(@event_timing_keys)
    |> encode_value()
  end

  defp window_id(scenario_id, type, source_id, index) do
    ["window", scenario_id, type, source_id, index]
    |> Enum.map(&encode_value/1)
    |> Enum.join(":")
  end

  defp activity_id(scenario_id, type, source_id, index) do
    [scenario_id, type, source_id, index]
    |> Enum.map(&encode_value/1)
    |> Enum.join("_")
  end

  defp maybe_warn(warnings, true, message), do: [message | warnings]
  defp maybe_warn(warnings, false, _message), do: warnings

  defp non_empty_string?(value), do: is_binary(value) and value != ""

  defp stable_id_string?(value),
    do: non_empty_string?(value) and Regex.match?(@stable_id_regex, value)

  defp encode_value(%_{} = struct), do: struct |> Map.from_struct() |> encode_value()

  defp encode_value(%{} = map) do
    Map.new(map, fn {key, value} -> {encode_value(key), encode_value(value)} end)
  end

  defp encode_value(values) when is_list(values) do
    if Keyword.keyword?(values) do
      Map.new(values, fn {key, value} -> {encode_value(key), encode_value(value)} end)
    else
      Enum.map(values, &encode_value/1)
    end
  end

  defp encode_value(value) when is_tuple(value), do: value |> Tuple.to_list() |> encode_value()
  defp encode_value(nil), do: nil
  defp encode_value(value) when is_boolean(value), do: value
  defp encode_value(value) when is_atom(value), do: Atom.to_string(value)
  defp encode_value(value), do: value
end
